INSERT INTO spell VALUES (123,'Awaken','awaken','Transmutation',NULL,NULL,NULL,'Druid 5','V, S, DF, XP','24 hours','Touch','Animal or tree touched',NULL,NULL,'Instantaneous','Will negates','Yes','Animal or tree gains human intellect.',NULL,NULL,NULL,NULL,'\n      <p>You awaken a tree or animal to humanlike sentience. To succeed, you must make a Will save (DC 10 + the animal\'s current HD, or the HD the tree will have once awakened).</p>\n      <p>The <i>awakened</i> animal or tree is friendly toward you. You have no special empathy or connection with a creature you awaken, although it serves you in specific tasks or endeavors if you communicate your desires to it.</p>\n      <p>An <i>awakened</i> tree has characteristics as if it were an animated object, except that it gains the plant type and its Intelligence, Wisdom, and Charisma scores are each 3d6. An <i>awakened</i> plant gains the ability to move its limbs, roots, vines, creepers, and so forth, and it has senses similar to a human\'s.</p>\n      <p>An <i>awakened</i> animal gets 3d6 Intelligence, +1d3 Charisma, and +2 HD. Its type becomes magical beast (augmented animal). An awakened animal can\'t serve as an animal companion, familiar, or special mount.</p>\n      <p>An <i>awakened</i> tree or animal can speak one language that you know, plus one additional language that you know per point of Intelligence bonus (if any).</p>\n      <p/>\n    ','250 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Awaken\" level=\"5\"><p><h5>Awaken</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>24 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Animal or tree touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You awaken a tree or animal to humanlike sentience. To succeed, you must make a Will save (DC 10 + the animal\'s current HD, or the HD the tree will have once awakened).</p><p>The <i>awakened</i> animal or tree is friendly toward you. You have no special empathy or connection with a creature you awaken, although it serves you in specific tasks or endeavors if you communicate your desires to it.</p><p>An <i>awakened</i> tree has characteristics as if it were an animated object, except that it gains the plant type and its Intelligence, Wisdom, and Charisma scores are each 3d6. An <i>awakened</i> plant gains the ability to move its limbs, roots, vines, creepers, and so forth, and it has senses similar to a human\'s.</p><p>An <i>awakened</i> animal gets 3d6 Intelligence, +1d3 Charisma, and +2 HD. Its type becomes magical beast (augmented animal). An awakened animal can\'t serve as an animal companion, familiar, or special mount.</p><p>An <i>awakened</i> tree or animal can speak one language that you know, plus one additional language that you know per point of Intelligence bonus (if any).</p><p><i>XP Cost:</i> 250 XP.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (124,'Baleful Polymorph','baleful polymorph','Transmutation',NULL,NULL,NULL,'Druid 5, Sorcerer/Wizard 5','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Permanent','Fortitude negates, Will partial; see text','Yes','Transforms subject into harmless animal.',NULL,'An empty cocoon.',NULL,NULL,'\n      <p>As <i>polymorph</i>,  except that you change the subject into a Small or smaller animal of no more than 1 HD. If the new form would prove fatal to the creature the subject gets a +4 bonus on the save.</p>\n      <p>If the spell succeeds, the subject must also make a Will save. If this second save fails, the creature loses its extraordinary, supernatural, and spell-like abilities, loses its ability to cast spells (if it had the ability), and gains the alignment, special abilities, and Intelligence, Wisdom, and Charisma scores of its new form in place of its own. It still retains its class and level (or HD), as well as all benefits deriving therefrom (such as base attack bonus, base save bonuses, and hit points). It retains any class features (other than spellcasting) that aren\'t extraordinary, supernatural, or spell-like abilities.</p>\n      <p>Incorporeal or gaseous creatures are immune to being <i>polymorphed</i>, and a creature with the shapechanger subtype can revert to its natural form as a standard action.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Baleful Polymorph\" level=\"5\"><p><h5>Baleful Polymorph</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 5, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates, Will partial; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>As <i>polymorph</i>,  except that you change the subject into a Small or smaller animal of no more than 1 HD. If the new form would prove fatal to the creature the subject gets a +4 bonus on the save.</p><p>If the spell succeeds, the subject must also make a Will save. If this second save fails, the creature loses its extraordinary, supernatural, and spell-like abilities, loses its ability to cast spells (if it had the ability), and gains the alignment, special abilities, and Intelligence, Wisdom, and Charisma scores of its new form in place of its own. It still retains its class and level (or HD), as well as all benefits deriving therefrom (such as base attack bonus, base save bonuses, and hit points). It retains any class features (other than spellcasting) that aren\'t extraordinary, supernatural, or spell-like abilities.</p><p>Incorporeal or gaseous creatures are immune to being <i>polymorphed</i>, and a creature with the shapechanger subtype can revert to its natural form as a standard action.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (125,'Bane','bane','Enchantment','Compulsion','Fear, Mind-Affecting',NULL,'Cleric 1','V, S, DF','1 standard action','50 ft.',NULL,'All enemies within 50 ft.',NULL,'1 min./level','Will negates','Yes','Enemies take -1 on attack rolls and saves against fear.',NULL,NULL,NULL,NULL,'\n      <p><i>Bane</i> fills your enemies with fear and doubt. Each affected creature takes a -1 penalty on attack rolls and a -1 penalty on saving throws against fear effects.</p>\n      <p><i>Bane</i> counters and dispels <i>bless</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Bane\" level=\"5\"><p><h5>Bane</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Fear, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>50 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>All enemies within 50 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p><i>Bane</i> fills your enemies with fear and doubt. Each affected creature takes a -1 penalty on attack rolls and a -1 penalty on saving throws against fear effects.</p><p><i>Bane</i> counters and dispels <i>bless</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (126,'Banishment','banishment','Abjuration',NULL,NULL,NULL,'Cleric 6, Sorcerer/Wizard 7','V, S, F','1 standard action','Close (25 ft. + 5 ft./2 levels)','One or more extraplanar creatures, no two of which can be more than 30 ft. apart',NULL,NULL,'Instantaneous','Will negates','Yes','Banishes 2 HD/level of extraplanar creatures.',NULL,NULL,NULL,NULL,'\n      <p>A <i>banishment</i> spell is a more powerful version of the <i>dismissal</i> spell. It enables you to force extraplanar creatures out of your home plane. As many as 2 Hit Dice of creatures per caster level can be banished.</p>\n      <p>You can improve the spell\'s chance of success by presenting at least one object or substance that the target hates, fears, or otherwise opposes. For each such object or substance, you gain a +1 bonus on your caster level check to overcome the target\'s spell resistance (if any), the saving throw DC increases by 2.</p>\n      <p>Certain rare items might work twice as well as a normal item for the purpose of the bonuses (each providing a +2 bonus on the caster level check against spell resistance and increasing the save DC by 4).</p>\n      <p/>\n    ',NULL,'Any item that is distasteful to the subject (optional, see above).',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Banishment\" level=\"5\"><p><h5>Banishment</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One or more extraplanar creatures, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A <i>banishment</i> spell is a more powerful version of the <i>dismissal</i> spell. It enables you to force extraplanar creatures out of your home plane. As many as 2 Hit Dice of creatures per caster level can be banished.</p><p>You can improve the spell\'s chance of success by presenting at least one object or substance that the target hates, fears, or otherwise opposes. For each such object or substance, you gain a +1 bonus on your caster level check to overcome the target\'s spell resistance (if any), the saving throw DC increases by 2.</p><p>Certain rare items might work twice as well as a normal item for the purpose of the bonuses (each providing a +2 bonus on the caster level check against spell resistance and increasing the save DC by 4).</p><p><i>Arcane Focus:</i> Any item that is distasteful to the subject (optional, see above).</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (127,'Barkskin','barkskin','Transmutation',NULL,NULL,NULL,'Druid 2, Ranger 2, Plant 2','V, S, DF','1 standard action','Touch','Living creature touched',NULL,NULL,'10 min./level','None','Yes (harmless)','Grants +2 (or higher) enhancement to natural armor.',NULL,NULL,NULL,NULL,'\n      <p><i>Barkskin</i> toughens a creature\'s skin. The effect grants a +2 enhancement bonus to the creature\'s existing natural armor bonus. This enhancement bonus increases by 1 for every three caster levels above 3rd, to a maximum of +5 at caster level 12th.</p>\n      <p>The enhancement bonus provided by <i>Barkskin</i> stacks with the target\'s natural armor bonus, but not with other enhancement bonuses to natural armor. A creature without natural armor has an effective natural armor bonus of +0.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Barkskin\" level=\"5\"><p><h5>Barkskin</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 2, Ranger 2, Plant 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p><i>Barkskin</i> toughens a creature\'s skin. The effect grants a +2 enhancement bonus to the creature\'s existing natural armor bonus. This enhancement bonus increases by 1 for every three caster levels above 3rd, to a maximum of +5 at caster level 12th.</p><p>The enhancement bonus provided by <i>Barkskin</i> stacks with the target\'s natural armor bonus, but not with other enhancement bonuses to natural armor. A creature without natural armor has an effective natural armor bonus of +0.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (128,'Bear\'s Endurance','bear\'s endurance','Transmutation',NULL,NULL,NULL,'Cleric 2, Druid 2, Ranger 2, Sorcerer/Wizard 2','V, S, DF','1 standard action','Touch','Creature touched',NULL,NULL,'1 min./level','Will negates (harmless)','Yes','Subject gains +4 to Con for 1 min./level.',NULL,NULL,NULL,NULL,'\n      <p>The affected creature gains greater vitality and stamina. The spell grants the subject a +4 enhancement bonus to Constitution, which adds the usual benefits to hit points, Fortitude saves, Constitution checks, and so forth.</p>\n      <p>Hit points gained by a temporary increase in Constitution score are not temporary hit points. They go away when the subject\'s Constitution drops back to normal. They are not lost first as temporary hit points are.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Bear\'s Endurance\" level=\"5\"><p><h5>Bear\'s Endurance</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Druid 2, Ranger 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>The affected creature gains greater vitality and stamina. The spell grants the subject a +4 enhancement bonus to Constitution, which adds the usual benefits to hit points, Fortitude saves, Constitution checks, and so forth.</p><p>Hit points gained by a temporary increase in Constitution score are not temporary hit points. They go away when the subject\'s Constitution drops back to normal. They are not lost first as temporary hit points are.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (129,'Bear\'s Endurance, Mass','mass bear\'s endurance','Transmutation',NULL,NULL,NULL,'Cleric 6, Druid 6, Sorcerer/Wizard 6','V, S, DF','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'1 min./level','Will negates (harmless)','Yes','As bear\'s endurance, affects one subject/level.',NULL,NULL,NULL,NULL,'\n      <p><i>Mass bear\'s endurance</i> works like <i>bear\'s endurance</i>, except that it affects multiple creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Bear\'s Endurance, Mass\" level=\"5\"><p><h5>Bear\'s Endurance, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Druid 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level, no two of which can be more than 30 ft. apart<br/></td></tr></table><p><i>Mass bear\'s endurance</i> works like <i>bear\'s endurance</i>, except that it affects multiple creatures.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (130,'Bestow Curse','bestow curse','Necromancy',NULL,NULL,NULL,'Cleric 3, Sorcerer/Wizard 4','V, S','1 standard action','Touch','Creature touched',NULL,NULL,'Permanent','Will negates','Yes','-6 to an ability score; -4 on attack rolls, saves, and checks; or 50% chance of losing each action.',NULL,NULL,NULL,NULL,'\n      <p>You place a curse on the subject. Choose one of the following three effects.</p>\n      <ul>\n <li> -6 decrease to an ability score (minimum 1).</li>\n <li> -4 penalty on attack rolls, saves, ability checks, and skill checks.</li>\n <li> Each turn, the target has a 50% chance to act normally; otherwise, it takes no action.</li>\n</ul>\n      <p>You may also invent your own curse, but it should be no more powerful than those described above.</p>\n      <p>The <i>curse</i> bestowed by this spell cannot be dispelled, but it can be removed with a <i>break enchantment</i>, <i>limited wish</i>, <i>miracle</i>, <i>remove curse</i>, or <i>wish</i> spell.</p>\n      <p><i>Bestow curse</i> counters <i>remove curse</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Bestow Curse\" level=\"5\"><p><h5>Bestow Curse</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You place a curse on the subject. Choose one of the following three effects.</p><ul>\n <li> -6 decrease to an ability score (minimum 1).</li>\n <li> -4 penalty on attack rolls, saves, ability checks, and skill checks.</li>\n <li> Each turn, the target has a 50% chance to act normally; otherwise, it takes no action.</li>\n</ul><p>You may also invent your own curse, but it should be no more powerful than those described above.</p><p>The <i>curse</i> bestowed by this spell cannot be dispelled, but it can be removed with a <i>break enchantment</i>, <i>limited wish</i>, <i>miracle</i>, <i>remove curse</i>, or <i>wish</i> spell.</p><p><i>Bestow curse</i> counters <i>remove curse</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (131,'Binding','binding','Enchantment','Compulsion','Mind-Affecting',NULL,'Sorcerer/Wizard 8','The components for a binding spell vary according to the version of the spell, but they always include a continuous chanting utterance read from the scroll or spellbook page containing the spell, somatic gestures, and materials appropriate to the form of binding used. These components can include such items as miniature chains of special metals, soporific herbs of the rarest sort (for slumber bindings), a bell jar of the finest crystal, and the like.','One minute','Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'See text (D)','Will negates; see text','Yes','Utilizes an array of techniques to imprison a creature.',NULL,NULL,NULL,NULL,'\n      <p>A <i>binding</i> spell creates a magical restraint to hold a creature. The target gets an initial saving throw only if its Hit Dice equal at least one-half your caster level.</p>\n      <p>You may have as many as six assistants help you with the spell. For each assistant who casts <i>suggestion</i>, your caster level for this casting of <i>binding</i> increases by 1. For each assistant who casts <i>dominate animal</i>,  <i>dominate person</i>,  or <i>dominate monster</i>,  your caster level for this casting of <i>binding</i> increases by a number equal to one-third of that assistant\'s level, provided that the spell\'s target is appropriate for a <i>binding</i> spell. Since the assistants\' spells are cast simply to improve your caster level for the purpose of the <i>binding</i> spell, saving throws and spell resistance against the assistants\' spells are irrelevant. Your caster level determines whether the target gets an initial Will saving throw and how long the <i>binding</i> lasts. All <i>binding</i> spells are dismissible.</p>\n      <p>Regardless of the version of <i>binding</i> you cast, you can specify triggering conditions that end the spell and release the creature whenever they occur. These triggers can be as simple or elaborate as you desire, but the condition must be reasonable and have a likelihood of coming to pass. The conditions can be based on a creature\'s name, identity, or alignment but otherwise must be based on observable actions or qualities. Intangibles such as level, class, Hit Dice, or hit points don\'t qualify. Once the spell is cast, its triggering conditions cannot be changed. Setting a release condition increases the save DC (assuming a saving throw is allowed) by 2.</p>\n      <p>If you are casting any of the first three versions of <i>binding</i> (those with limited durations), you may cast additional <i>binding</i> spells to prolong the effect, since the durations overlap. If you do so, the target gets a saving throw at the end of the first spell\'s duration, even if your caster level was high enough to disallow an initial saving throw. If the creature succeeds on this save, all the <i>binding</i> spells it has received are broken.</p>\n      <p>The <i>binding</i> spell has six versions. Choose one of the following versions when you cast the spell.</p>\n      <p><i>Chaining:</i> The subject is confined by restraints that generate an <i>Antipathy</i> spell affecting all creatures who approach the subject, except you. The duration is one year per caster level. The subject of this form of <i>binding</i> is confined to the spot it occupied when it received the spell.</p>\n      <p><i>Slumber:</i> This version causes the subject to become comatose for as long as one year per caster level. The subject does not need to eat or drink while <i>slumbering</i>, nor does it age. This form of <i>binding</i> is more difficult to cast than <i>chaining</i>, making it slightly easier to resist. Reduce the spell\'s save DC by 1.</p>\n      <p><i>Bound Slumber:</i> This combination of <i>chaining</i> and <i>slumber</i> lasts for as long as one month per caster level. Reduce the save DC by 2.</p>\n      <p><i>Hedged Prison:</i> The subject is transported to or otherwise brought within a confined area from which it cannot wander by any means. The effect is permanent. Reduce the save DC by 3.</p>\n      <p><i>Metamorphosis:</i> The subject assumes gaseous form, except for its head or face. It is held harmless in a jar or other container, which may be transparent if you so choose. The creature remains aware of its surroundings and can speak, but it cannot leave the container, attack, or use any of its powers or abilities. The <i>binding</i> is permanent. The subject does not need to breathe, eat, or drink while <i>metamorphosed</i>, nor does it age. Reduce the save DC by 4.</p>\n      <p><i>Minimus Containment:</i> The subject is shrunk to a height of 1 inch or even less and held within some gem, jar, or similar object. The <i>binding</i> is permanent. The subject does not need to breathe, eat, or drink while <i>contained</i>, nor does it age. Reduce the save DC by 4.</p>\n      <p>You can\'t dispel a <i>binding</i> spell with <i>dispel magic</i> or a similar effect, though an <i>antimagic field</i> or <i>Mage\'s disjunction</i> affects it normally. A bound extraplanar creature cannot be sent back to its home plane due to <i>dismissal</i>,  <i>banishment</i>,  or a similar effect.</p>\n      <p>In addition to the specially made props suited to the specific type of <i>binding</i> (cost 500 gp), the spell requires opals worth at least 500 gp for each HD of the target and a vellum depiction or carved statuette of the subject to be captured.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Binding\" level=\"5\"><p><h5>Binding</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>One minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>See text (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A <i>binding</i> spell creates a magical restraint to hold a creature. The target gets an initial saving throw only if its Hit Dice equal at least one-half your caster level.</p><p>You may have as many as six assistants help you with the spell. For each assistant who casts <i>suggestion</i>, your caster level for this casting of <i>binding</i> increases by 1. For each assistant who casts <i>dominate animal</i>,  <i>dominate person</i>,  or <i>dominate monster</i>,  your caster level for this casting of <i>binding</i> increases by a number equal to one-third of that assistant\'s level, provided that the spell\'s target is appropriate for a <i>binding</i> spell. Since the assistants\' spells are cast simply to improve your caster level for the purpose of the <i>binding</i> spell, saving throws and spell resistance against the assistants\' spells are irrelevant. Your caster level determines whether the target gets an initial Will saving throw and how long the <i>binding</i> lasts. All <i>binding</i> spells are dismissible.</p><p>Regardless of the version of <i>binding</i> you cast, you can specify triggering conditions that end the spell and release the creature whenever they occur. These triggers can be as simple or elaborate as you desire, but the condition must be reasonable and have a likelihood of coming to pass. The conditions can be based on a creature\'s name, identity, or alignment but otherwise must be based on observable actions or qualities. Intangibles such as level, class, Hit Dice, or hit points don\'t qualify. Once the spell is cast, its triggering conditions cannot be changed. Setting a release condition increases the save DC (assuming a saving throw is allowed) by 2.</p><p>If you are casting any of the first three versions of <i>binding</i> (those with limited durations), you may cast additional <i>binding</i> spells to prolong the effect, since the durations overlap. If you do so, the target gets a saving throw at the end of the first spell\'s duration, even if your caster level was high enough to disallow an initial saving throw. If the creature succeeds on this save, all the <i>binding</i> spells it has received are broken.</p><p>The <i>binding</i> spell has six versions. Choose one of the following versions when you cast the spell.</p><p><i>Chaining:</i> The subject is confined by restraints that generate an <i>Antipathy</i> spell affecting all creatures who approach the subject, except you. The duration is one year per caster level. The subject of this form of <i>binding</i> is confined to the spot it occupied when it received the spell.</p><p><i>Slumber:</i> This version causes the subject to become comatose for as long as one year per caster level. The subject does not need to eat or drink while <i>slumbering</i>, nor does it age. This form of <i>binding</i> is more difficult to cast than <i>chaining</i>, making it slightly easier to resist. Reduce the spell\'s save DC by 1.</p><p><i>Bound Slumber:</i> This combination of <i>chaining</i> and <i>slumber</i> lasts for as long as one month per caster level. Reduce the save DC by 2.</p><p><i>Hedged Prison:</i> The subject is transported to or otherwise brought within a confined area from which it cannot wander by any means. The effect is permanent. Reduce the save DC by 3.</p><p><i>Metamorphosis:</i> The subject assumes gaseous form, except for its head or face. It is held harmless in a jar or other container, which may be transparent if you so choose. The creature remains aware of its surroundings and can speak, but it cannot leave the container, attack, or use any of its powers or abilities. The <i>binding</i> is permanent. The subject does not need to breathe, eat, or drink while <i>metamorphosed</i>, nor does it age. Reduce the save DC by 4.</p><p><i>Minimus Containment:</i> The subject is shrunk to a height of 1 inch or even less and held within some gem, jar, or similar object. The <i>binding</i> is permanent. The subject does not need to breathe, eat, or drink while <i>contained</i>, nor does it age. Reduce the save DC by 4.</p><p>You can\'t dispel a <i>binding</i> spell with <i>dispel magic</i> or a similar effect, though an <i>antimagic field</i> or <i>Mage\'s disjunction</i> affects it normally. A bound extraplanar creature cannot be sent back to its home plane due to <i>dismissal</i>,  <i>banishment</i>,  or a similar effect.</p><p><i>Components:</i> The components for a <i>binding</i> spell vary according to the version of the spell, but they always include a continuous chanting utterance read from the scroll or spellbook page containing the spell, somatic gestures, and materials appropriate to the form of <i>binding</i> used. These components can include such items as miniature chains of special metals, soporific herbs of the rarest sort (for <i>slumber</i> bindings), a bell jar of the finest crystal, and the like.</p><p>In addition to the specially made props suited to the specific type of <i>binding</i> (cost 500 gp), the spell requires opals worth at least 500 gp for each HD of the target and a vellum depiction or carved statuette of the subject to be captured.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (132,'Black Tentacles','black tentacles','Conjuration','Creation',NULL,NULL,'Sorcerer/Wizard 4','V, S, M','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'20-ft. -radius spread',NULL,'1 round/level (D)','None','No','Tentacles grapple all within 20 ft. spread.',NULL,'A piece of tentacle from a giant octopus or a giant squid.',NULL,NULL,'\n      <p>This spell conjures a field of rubbery black tentacles, each 10 feet long. These waving members seem to spring forth from the earth, floor, or whatever surface is underfoot-including water. They grasp and entwine around creatures that enter the area, holding them fast and crushing them with great strength.</p>\n      <p>Every creature within the area of the spell must make a grapple check, opposed by the grapple check of the tentacles. Treat the tentacles attacking a particular target as a Large creature with a base attack bonus equal to your caster level and a Strength score of 19. Thus, its grapple check modifier is equal to your caster level +8. The tentacles are immune to all types of damage.</p>\n      <p>Once the tentacles grapple an opponent, they may make a grapple check each round on your turn to deal 1d6+4 points of bludgeoning damage. The tentacles continue to crush the opponent until the spell ends or the opponent escapes.</p>\n      <p>Any creature that enters the area of the spell is immediately attacked by the tentacles. Even creatures who aren\'t grappling with the tentacles may move through the area at only half normal speed.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Black Tentacles\" level=\"5\"><p><h5>Black Tentacles</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>20-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell conjures a field of rubbery black tentacles, each 10 feet long. These waving members seem to spring forth from the earth, floor, or whatever surface is underfoot-including water. They grasp and entwine around creatures that enter the area, holding them fast and crushing them with great strength.</p><p>Every creature within the area of the spell must make a grapple check, opposed by the grapple check of the tentacles. Treat the tentacles attacking a particular target as a Large creature with a base attack bonus equal to your caster level and a Strength score of 19. Thus, its grapple check modifier is equal to your caster level +8. The tentacles are immune to all types of damage.</p><p>Once the tentacles grapple an opponent, they may make a grapple check each round on your turn to deal 1d6+4 points of bludgeoning damage. The tentacles continue to crush the opponent until the spell ends or the opponent escapes.</p><p>Any creature that enters the area of the spell is immediately attacked by the tentacles. Even creatures who aren\'t grappling with the tentacles may move through the area at only half normal speed.</p><p><i>Material Component:</i> A piece of tentacle from a giant octopus or a giant squid.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (133,'Blade Barrier','blade barrier','Evocation',NULL,'Force',NULL,'Cleric 6, Good 6, War 6','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Wall of whirling blades up to 20 ft. long/level, or a ringed wall of whirling blades with a radius of up to 5 ft. per two levels; either form 20 ft. high','1 min./level (D)','Reflex half or Reflex negates; see text','Yes','Wall of blades deals 1d6/level damage.',NULL,NULL,NULL,NULL,'\n      <p>An immobile, vertical curtain of whirling blades shaped of pure force springs into existence. Any creature passing through the wall takes 1d6 points of damage per caster level (maximum 15d6), with a Reflex save for half damage.</p>\n      <p>If you evoke the barrier so that it appears where creatures are, each creature takes damage as if passing through the wall. Each such creature can avoid the wall (ending up on the side of its choice) and thus take no damage by making a successful Reflex save.</p>\n      <p>A <i>blade barrier</i> provides cover (+4 bonus to AC, +2 bonus on Reflex saves) against attacks made through it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Blade Barrier\" level=\"5\"><p><h5>Blade Barrier</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Good 6, War 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Wall of whirling blades up to 20 ft. long/level, or a ringed wall of whirling blades with a radius of up to 5 ft. per two levels; either form 20 ft. high<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half or Reflex negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>An immobile, vertical curtain of whirling blades shaped of pure force springs into existence. Any creature passing through the wall takes 1d6 points of damage per caster level (maximum 15d6), with a Reflex save for half damage.</p><p>If you evoke the barrier so that it appears where creatures are, each creature takes damage as if passing through the wall. Each such creature can avoid the wall (ending up on the side of its choice) and thus take no damage by making a successful Reflex save.</p><p>A <i>blade barrier</i> provides cover (+4 bonus to AC, +2 bonus on Reflex saves) against attacks made through it.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (134,'Blasphemy','blasphemy','Evocation',NULL,'Evil, Sonic',NULL,'Cleric 7, Evil 7','V','1 standard action','40 ft.',NULL,'Nonevil creatures in a 40-ft. -radius spread centered on you',NULL,'Instantaneous','None or Will negates; see text','Yes','Kills, paralyzes, weakens, or dazes nonevil subjects.',NULL,NULL,NULL,NULL,'\n      <p>Any nonevil creature within the area of a <i>blasphemy</i> spell suffers the following ill effects.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>HD</b><br/></td>\n<td><b>Effect</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Equal to caster level<br/></td>\n<td>Dazed<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -1<br/></td>\n<td>Weakened, dazed<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -5<br/></td>\n<td>Paralyzed, weakened, dazed<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -10<br/></td>\n<td>Killed, paralyzed, weakened, dazed<br/></td>\n\n</tr>\n</table>\n      <p>The effects are cumulative and concurrent.</p>\n      <p>No saving throw is allowed against these effects.</p>\n      <p><i>Dazed:</i> The creature can take no actions for 1 round, though it defends itself normally.</p>\n      <p><i>Weakened:</i> The creature\'s Strength score decreases by 2d6 points for 2d4 rounds.</p>\n      <p><i>Paralyzed:</i> The creature is paralyzed and helpless for 1d10 minutes.</p>\n      <p><i>Killed:</i> Living creatures die. Undead creatures are destroyed.</p>\n      <p>Furthermore, if you are on your home plane when you cast this spell, nonevil extraplanar creatures within the area are instantly banished back to their home planes. Creatures so banished cannot return for at least 24 hours. This effect takes place regardless of whether the creatures hear the <i>blasphemy</i>. The banishment effect allows a Will save (at a -4 penalty) to negate.</p>\n      <p>Creatures whose Hit Dice exceed your caster level are unaffected by <i>blasphemy</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Blasphemy\" level=\"5\"><p><h5>Blasphemy</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Evil, Sonic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7, Evil 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>40 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Nonevil creatures in a 40-ft. -radius spread centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None or Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Any nonevil creature within the area of a <i>blasphemy</i> spell suffers the following ill effects.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>HD</b><br/></td>\n<td><b>Effect</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Equal to caster level<br/></td>\n<td>Dazed<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -1<br/></td>\n<td>Weakened, dazed<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -5<br/></td>\n<td>Paralyzed, weakened, dazed<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Up to caster level -10<br/></td>\n<td>Killed, paralyzed, weakened, dazed<br/></td>\n\n</tr>\n</table><p>The effects are cumulative and concurrent.</p><p>No saving throw is allowed against these effects.</p><p><i>Dazed:</i> The creature can take no actions for 1 round, though it defends itself normally.</p><p><i>Weakened:</i> The creature\'s Strength score decreases by 2d6 points for 2d4 rounds.</p><p><i>Paralyzed:</i> The creature is paralyzed and helpless for 1d10 minutes.</p><p><i>Killed:</i> Living creatures die. Undead creatures are destroyed.</p><p>Furthermore, if you are on your home plane when you cast this spell, nonevil extraplanar creatures within the area are instantly banished back to their home planes. Creatures so banished cannot return for at least 24 hours. This effect takes place regardless of whether the creatures hear the <i>blasphemy</i>. The banishment effect allows a Will save (at a -4 penalty) to negate.</p><p>Creatures whose Hit Dice exceed your caster level are unaffected by <i>blasphemy</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (135,'Bless','bless','Enchantment','Compulsion','Mind-Affecting',NULL,'Cleric 1, Paladin 1','V, S, DF','1 standard action','50 ft.',NULL,'The caster and all allies within a 50-ft. burst, centered on the caster',NULL,'1 min./level','None','Yes (harmless)','Allies gain +1 on attack rolls and +1 on saves against fear.',NULL,NULL,NULL,NULL,'\n      <p><i>Bless</i> fills your allies with courage. Each ally gains a +1 morale bonus on attack rolls and on saving throws against fear effects.</p>\n      <p><i>Bless</i> counters and dispels <i>bane</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Bless\" level=\"5\"><p><h5>Bless</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1, Paladin 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>50 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>The caster and all allies within a 50-ft. burst, centered on the caster<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p><i>Bless</i> fills your allies with courage. Each ally gains a +1 morale bonus on attack rolls and on saving throws against fear effects.</p><p><i>Bless</i> counters and dispels <i>bane</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (136,'Bless Water','bless water','Transmutation',NULL,'Good',NULL,'Cleric 1, Paladin 1','V, S, M','1 minute','Touch','Flask of water touched',NULL,NULL,'Instantaneous','Will negates (object)','Yes (object)','Makes holy water.',NULL,'5 pounds of powdered silver (worth 25 gp).',NULL,NULL,'\n      <p>This transmutation imbues a flask (1 pint) of water with positive energy, turning it into holy water.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Bless Water\" level=\"5\"><p><h5>Bless Water</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Good]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1, Paladin 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Flask of water touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>This transmutation imbues a flask (1 pint) of water with positive energy, turning it into holy water.</p><p><i>Material Component:</i> 5 pounds of powdered silver (worth 25 gp).</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (137,'Bless Weapon','bless weapon','Transmutation',NULL,NULL,NULL,'Paladin 1','V, S','1 standard action','Touch','Weapon touched',NULL,NULL,'1 min./level','None','No','Weapon strikes true against evil foes.',NULL,NULL,NULL,NULL,'\n      <p>This transmutation makes a weapon strike true against evil foes. The weapon is treated as having a +1 enhancement bonus for the purpose of bypassing the damage reduction of evil creatures or striking evil incorporeal creatures (though the spell doesn\'t grant an actual enhancement bonus). The weapon also becomes good, which means it can bypass the damage reduction of certain creatures. (This effect overrides and suppresses any other alignment the weapon might have.) Individual arrows or bolts can be transmuted, but affected projectile weapons (such as bows) don\'t confer the benefit to the projectiles they shoot.</p>\n      <p>In addition, all critical hit rolls against evil foes are automatically successful, so every threat is a critical hit. This last effect does not apply to any weapon that already has a magical effect related to critical hits, such as a keen weapon or a vorpal sword.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Bless Weapon\" level=\"5\"><p><h5>Bless Weapon</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Paladin 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Weapon touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This transmutation makes a weapon strike true against evil foes. The weapon is treated as having a +1 enhancement bonus for the purpose of bypassing the damage reduction of evil creatures or striking evil incorporeal creatures (though the spell doesn\'t grant an actual enhancement bonus). The weapon also becomes good, which means it can bypass the damage reduction of certain creatures. (This effect overrides and suppresses any other alignment the weapon might have.) Individual arrows or bolts can be transmuted, but affected projectile weapons (such as bows) don\'t confer the benefit to the projectiles they shoot.</p><p>In addition, all critical hit rolls against evil foes are automatically successful, so every threat is a critical hit. This last effect does not apply to any weapon that already has a magical effect related to critical hits, such as a keen weapon or a vorpal sword.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (138,'Blight','blight','Necromancy',NULL,NULL,NULL,'Druid 4, Sorcerer/Wizard 5','V, S, DF','1 standard action','Touch','One plant',NULL,NULL,'Instantaneous','Fortitude half; see text','Yes','Withers one plant or deals 1d6/level damage to plant creature.',NULL,NULL,NULL,NULL,'\n      <p>This spell withers a single plant of any size. An affected plant creature takes 1d6 points of damage per level (maximum 15d6) and may attempt a Fortitude saving throw for half damage. A plant that isn\'t a creature doesn\'t receive a save and immediately withers and dies.</p>\n      <p>This spell has no effect on the soil or surrounding plant life.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Blight\" level=\"5\"><p><h5>Blight</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 4, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One plant<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude half; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell withers a single plant of any size. An affected plant creature takes 1d6 points of damage per level (maximum 15d6) and may attempt a Fortitude saving throw for half damage. A plant that isn\'t a creature doesn\'t receive a save and immediately withers and dies.</p><p>This spell has no effect on the soil or surrounding plant life.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (139,'Blindness/Deafness','blindness/deafness','Necromancy',NULL,NULL,NULL,'Bard 2, Cleric 3, Sorcerer/Wizard 2','V','1 standard action','Medium (100 ft. + 10 ft./level)','One living creature',NULL,NULL,'Permanent (D)','Fortitude negates','Yes','Makes subject blinded or deafened.',NULL,NULL,NULL,NULL,'\n      <p>You call upon the powers of unlife to render the subject blinded or deafened, as you choose.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Blindness/Deafness\" level=\"5\"><p><h5>Blindness/Deafness</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Cleric 3, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You call upon the powers of unlife to render the subject blinded or deafened, as you choose.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (140,'Blink','blink','Transmutation',NULL,NULL,NULL,'Bard 3, Sorcerer/Wizard 3','V, S','1 standard action','Personal','You',NULL,NULL,'1 round/level (D)',NULL,NULL,'You randomly vanish and reappear for 1 round/level.',NULL,NULL,NULL,NULL,'\n      <p>You \'blink\' back and forth between the Material Plane and the Ethereal Plane. You look as though you\'re winking in and out of reality very quickly and at random.</p>\n      <p><i>Blinking</i> has several effects, as follows.</p>\n      <p>Physical attacks against you have a 50% miss chance, and the Blind-Fight feat doesn\'t help opponents, since you\'re ethereal and not merely invisible. If the attack is capable of striking ethereal creatures, the miss chance is only 20% (for concealment).</p>\n      <p>If the attacker can see invisible creatures, the miss chance is also only 20%. (For an attacker who can both see and strike ethereal creatures, there is no miss chance.) Likewise, your own attacks have a 20% miss chance, since you sometimes go ethereal just as you are about to strike.</p>\n      <p>Any individually targeted spell has a 50% chance to fail against you while you\'re <i>Blinking</i> unless your attacker can target invisible, ethereal creatures. Your own spells have a 20% chance to activate just as you go ethereal, in which case they typically do not affect the Material Plane.</p>\n      <p>While <i>blinking</i>, you take only half damage from area attacks (but full damage from those that extend onto the Ethereal Plane). You strike as an invisible creature (with a +2 bonus on attack rolls), denying your target any Dexterity bonus to AC.</p>\n      <p>You take only half damage from falling, since you fall only while you are material.</p>\n      <p>While <i>blinking</i>, you can step through (but not see through) solid objects. For each 5 feet of solid material you walk through, there is a 50% chance that you become material. If this occurs, you are shunted off to the nearest open space and take 1d6 points of damage per 5 feet so traveled. You can move at only three-quarters speed (because movement on the Ethereal Plane is at half speed, and you spend about half your time there and half your time material.)</p>\n      <p>Since you spend about half your time on the Ethereal Plane, you can see and even attack ethereal creatures. You interact with ethereal creatures roughly the same way you interact with material ones.</p>\n      <p>An ethereal creature is invisible, incorporeal, and capable of moving in any direction, even up or down. As an incorporeal creature, you can move through solid objects, including living creatures.</p>\n      <p>An ethereal creature can see and hear the Material Plane, but everything looks gray and insubstantial. Sight and hearing on the Material Plane are limited to 60 feet.</p>\n      <p>Force effects and abjurations affect you normally. Their effects extend onto the Ethereal Plane from the Material Plane, but not vice versa. An ethereal creature can\'t attack material creatures, and spells you cast while ethereal affect only other ethereal things. Certain material creatures or objects have attacks or effects that work on the Ethereal Plane. Treat other ethereal creatures and objects as material.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Blink\" level=\"5\"><p><h5>Blink</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr></table><p>You \'blink\' back and forth between the Material Plane and the Ethereal Plane. You look as though you\'re winking in and out of reality very quickly and at random.</p><p><i>Blinking</i> has several effects, as follows.</p><p>Physical attacks against you have a 50% miss chance, and the Blind-Fight feat doesn\'t help opponents, since you\'re ethereal and not merely invisible. If the attack is capable of striking ethereal creatures, the miss chance is only 20% (for concealment).</p><p>If the attacker can see invisible creatures, the miss chance is also only 20%. (For an attacker who can both see and strike ethereal creatures, there is no miss chance.) Likewise, your own attacks have a 20% miss chance, since you sometimes go ethereal just as you are about to strike.</p><p>Any individually targeted spell has a 50% chance to fail against you while you\'re <i>Blinking</i> unless your attacker can target invisible, ethereal creatures. Your own spells have a 20% chance to activate just as you go ethereal, in which case they typically do not affect the Material Plane.</p><p>While <i>blinking</i>, you take only half damage from area attacks (but full damage from those that extend onto the Ethereal Plane). You strike as an invisible creature (with a +2 bonus on attack rolls), denying your target any Dexterity bonus to AC.</p><p>You take only half damage from falling, since you fall only while you are material.</p><p>While <i>blinking</i>, you can step through (but not see through) solid objects. For each 5 feet of solid material you walk through, there is a 50% chance that you become material. If this occurs, you are shunted off to the nearest open space and take 1d6 points of damage per 5 feet so traveled. You can move at only three-quarters speed (because movement on the Ethereal Plane is at half speed, and you spend about half your time there and half your time material.)</p><p>Since you spend about half your time on the Ethereal Plane, you can see and even attack ethereal creatures. You interact with ethereal creatures roughly the same way you interact with material ones.</p><p>An ethereal creature is invisible, incorporeal, and capable of moving in any direction, even up or down. As an incorporeal creature, you can move through solid objects, including living creatures.</p><p>An ethereal creature can see and hear the Material Plane, but everything looks gray and insubstantial. Sight and hearing on the Material Plane are limited to 60 feet.</p><p>Force effects and abjurations affect you normally. Their effects extend onto the Ethereal Plane from the Material Plane, but not vice versa. An ethereal creature can\'t attack material creatures, and spells you cast while ethereal affect only other ethereal things. Certain material creatures or objects have attacks or effects that work on the Ethereal Plane. Treat other ethereal creatures and objects as material.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (141,'Blur','blur','Illusion','Glamer',NULL,NULL,'Bard 2, Sorcerer/Wizard 2','V','1 standard action','Touch','Creature touched',NULL,NULL,'1 min./level (D)','Will negates (harmless)','Yes (harmless)','Attacks miss subject 20% of the time.',NULL,NULL,NULL,NULL,'\n      <p>The subject\'s outline appears blurred, shifting and wavering. This distortion grants the subject concealment (20% miss chance).</p>\n      <p>A <i>see invisibility</i> spell does not counteract the <i>blur</i> effect, but a <i>true seeing</i> spell does.</p>\n      <p>Opponents that cannot see the subject ignore the spell\'s effect (though fighting an unseen opponent carries penalties of its own).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Blur\" level=\"5\"><p><h5>Blur</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Glamer)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject\'s outline appears blurred, shifting and wavering. This distortion grants the subject concealment (20% miss chance).</p><p>A <i>see invisibility</i> spell does not counteract the <i>blur</i> effect, but a <i>true seeing</i> spell does.</p><p>Opponents that cannot see the subject ignore the spell\'s effect (though fighting an unseen opponent carries penalties of its own).</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (142,'Break Enchantment','break enchantment','Abjuration',NULL,NULL,NULL,'Bard 4, Cleric 5, Luck 5, Paladin 4, Sorcerer/Wizard 5','V, S','1 minute','Close (25 ft. + 5 ft./2 levels)','Up to one creature per level, all within 30 ft. of each other',NULL,NULL,'Instantaneous','See text','No','Frees subjects from enchantments, alterations, curses, and petrification.',NULL,NULL,NULL,NULL,'\n      <p>This spell frees victims from enchantments, transmutations, and curses. <i>Break enchantment</i> can reverse even an instantaneous effect. For each such effect, you make a caster level check (1d20 + caster level, maximum +15) against a DC of 11 + caster level of the effect. Success means that the creature is free of the spell, curse, or effect. For a cursed magic item, the DC is 25.</p>\n      <p>If the spell is one that cannot be dispelled by <i>dispel magic</i>, <i>Break enchantment</i> works only if that spell is 5th level or lower.</p>\n      <p>If the effect comes from some permanent magic item <i>Break enchantment</i> does not remove the curse from the item, but it does frees the victim from the item\'s effects.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Break Enchantment\" level=\"5\"><p><h5>Break Enchantment</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4, Cleric 5, Luck 5, Paladin 4, Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to one creature per level, all within 30 ft. of each other<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell frees victims from enchantments, transmutations, and curses. <i>Break enchantment</i> can reverse even an instantaneous effect. For each such effect, you make a caster level check (1d20 + caster level, maximum +15) against a DC of 11 + caster level of the effect. Success means that the creature is free of the spell, curse, or effect. For a cursed magic item, the DC is 25.</p><p>If the spell is one that cannot be dispelled by <i>dispel magic</i>, <i>Break enchantment</i> works only if that spell is 5th level or lower.</p><p>If the effect comes from some permanent magic item <i>Break enchantment</i> does not remove the curse from the item, but it does frees the victim from the item\'s effects.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (143,'Bull\'s Strength','bull\'s strength','Transmutation',NULL,NULL,NULL,'Cleric 2, Druid 2, Paladin 2, Sorcerer/Wizard 2, Strength 2','V, S, M/DF','1 standard action','Touch','Creature touched',NULL,NULL,'1 min./level','Will negates (harmless)','Yes (harmless)','Subject gains +4 to Str for 1 min./level.',NULL,NULL,'A few hairs, or a pinch of dung, from a bull.',NULL,'\n      <p>The subject becomes stronger. The spell grants a +4 enhancement bonus to Strength, adding the usual benefits to melee attack rolls, melee damage rolls, and other uses of the Strength modifier.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Bull\'s Strength\" level=\"5\"><p><h5>Bull\'s Strength</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Druid 2, Paladin 2, Sorcerer/Wizard 2, Strength 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject becomes stronger. The spell grants a +4 enhancement bonus to Strength, adding the usual benefits to melee attack rolls, melee damage rolls, and other uses of the Strength modifier.</p><p><i>Arcane Material Component:</i> A few hairs, or a pinch of dung, from a bull.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (144,'Bull\'s Strength, Mass','mass bull\'s strength','Transmutation',NULL,NULL,NULL,'Cleric 6, Druid 6, Sorcerer/Wizard 6','V, S, M/DF','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'1 min./level','Will negates (harmless)','Yes (harmless)','As bull\'s strength, affects one subject/level.',NULL,NULL,'A few hairs, or a pinch of dung, from a bull.',NULL,'\n      <p>This spell functions like <i>bull\'s strength</i>, except that it affects multiple creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Bull\'s Strength, Mass\" level=\"5\"><p><h5>Bull\'s Strength, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Druid 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>bull\'s strength</i>, except that it affects multiple creatures.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (145,'Burning Hands','burning hands','Evocation',NULL,'Fire',NULL,'Fire 1, Sorcerer/Wizard 1','V, S','1 standard action','15 ft.',NULL,'Cone-shaped burst',NULL,'Instantaneous','Reflex half','Yes','1d4/level fire damage (max 5d4).',NULL,NULL,NULL,NULL,'\n      <p>A cone of searing flame shoots from your fingertips. Any creature in the area of the flames takes 1d4 points of fire damage per caster level (maximum 5d4). Flammable materials burn if the flames touch them. A character can extinguish burning items as a full-round action.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Burning Hands\" level=\"5\"><p><h5>Burning Hands</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Fire]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Fire 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>15 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A cone of searing flame shoots from your fingertips. Any creature in the area of the flames takes 1d4 points of fire damage per caster level (maximum 5d4). Flammable materials burn if the flames touch them. A character can extinguish burning items as a full-round action.</p><p/>\n</div>\n    ','SRD 3.5 SpellsA-B');
INSERT INTO spell VALUES (146,'Call Lightning','call lightning','Evocation',NULL,'Electricity',NULL,'Druid 3','V, S','1 round','Medium (100 ft. + 10 ft./level)',NULL,NULL,'One or more 30-ft. -long vertical lines of lightning','1 min./level','Reflex half','Yes','Calls down lightning bolts (3d6 per bolt) from sky.',NULL,NULL,NULL,NULL,'\n      <p>Immediately upon completion of the spell, and once per round thereafter, you may call down a 5-foot-wide, 30-foot-long, vertical bolt of lightning that deals 3d6 points of electricity damage. The bolt of lightning flashes down in a vertical stroke at whatever target point you choose within the spell\'s range (measured from your position at the time). Any creature in the target square or in the path of the bolt is affected.</p>\n      <p>You need not call a bolt of lightning immediately; other actions, even spellcasting, can be performed. However, each round after the first you may use a standard action (concentrating on the spell) to call a bolt. You may call a total number of bolts equal to your caster level (maximum 10 bolts).</p>\n      <p>If you are outdoors and in a stormy area-a rain shower, clouds and wind, hot and cloudy conditions, or even a tornado (including a whirlwind formed by a djinni or an air elemental of at least Large size)-each bolt deals 3d10 points of electricity damage instead of 3d6.</p>\n      <p>This spell functions indoors or underground but not underwater.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Call Lightning\" level=\"5\"><p><h5>Call Lightning</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Electricity]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One or more 30-ft. -long vertical lines of lightning<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>Immediately upon completion of the spell, and once per round thereafter, you may call down a 5-foot-wide, 30-foot-long, vertical bolt of lightning that deals 3d6 points of electricity damage. The bolt of lightning flashes down in a vertical stroke at whatever target point you choose within the spell\'s range (measured from your position at the time). Any creature in the target square or in the path of the bolt is affected.</p><p>You need not call a bolt of lightning immediately; other actions, even spellcasting, can be performed. However, each round after the first you may use a standard action (concentrating on the spell) to call a bolt. You may call a total number of bolts equal to your caster level (maximum 10 bolts).</p><p>If you are outdoors and in a stormy area-a rain shower, clouds and wind, hot and cloudy conditions, or even a tornado (including a whirlwind formed by a djinni or an air elemental of at least Large size)-each bolt deals 3d10 points of electricity damage instead of 3d6.</p><p>This spell functions indoors or underground but not underwater.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (147,'Call Lightning Storm','call lightning storm','Evocation',NULL,'Electricity',NULL,'Druid 5','V, S','1 round','Long (400 ft. + 40 ft./level)',NULL,NULL,'One or more 30-ft. -long vertical lines of lightning','1 min./level','Reflex half','Yes','As call lightning, but 5d6 damage per bolt.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>call lightning</i>, except that each bolt deals 5d6 points of electricity damage (or 5d10 if created outdoors in a stormy area), and you may call a maximum of 15 bolts.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Call Lightning Storm\" level=\"5\"><p><h5>Call Lightning Storm</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Electricity]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr></table><p>This spell functions like <i>call lightning</i>, except that each bolt deals 5d6 points of electricity damage (or 5d10 if created outdoors in a stormy area), and you may call a maximum of 15 bolts.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (148,'Calm Animals','calm animals','Enchantment','Compulsion','Mind-Affecting',NULL,'Animal 1, Druid 1, Ranger 1','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','Animals within 30 ft. of each other',NULL,NULL,'1 min./level','Will negates; see text','Yes','Calms (2d4 + level) HD of animals.',NULL,NULL,NULL,NULL,'\n      <p>This spell soothes and quiets animals, rendering them docile and harmless. Only ordinary animals (those with Intelligence scores of 1 or 2) can be affected by this spell. All the subjects must be of the same kind, and no two may be more than 30 feet apart. The maximum number of Hit Dice of animals you can affect is equal to 2d4 + caster level. A dire animal or an animal trained to attack or guard is allowed a saving throw; other animals are not.</p>\n      <p>The affected creatures remain where they are and do not attack or flee. They are not helpless and defend themselves normally if attacked. Any threat breaks the spell on the threatened creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Calm Animals\" level=\"5\"><p><h5>Calm Animals</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Animal 1, Druid 1, Ranger 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Animals within 30 ft. of each other<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell soothes and quiets animals, rendering them docile and harmless. Only ordinary animals (those with Intelligence scores of 1 or 2) can be affected by this spell. All the subjects must be of the same kind, and no two may be more than 30 feet apart. The maximum number of Hit Dice of animals you can affect is equal to 2d4 + caster level. A dire animal or an animal trained to attack or guard is allowed a saving throw; other animals are not.</p><p>The affected creatures remain where they are and do not attack or flee. They are not helpless and defend themselves normally if attacked. Any threat breaks the spell on the threatened creatures.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (149,'Calm Emotions','calm emotions','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 2, Cleric 2, Law 2','V, S, DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'Creatures in a 20-ft. -radius spread',NULL,'Concentration, up to 1 round/level (D)','Will negates','Yes','Calms creatures, negating emotion effects.',NULL,NULL,NULL,NULL,'\n      <p>This spell calms agitated creatures. You have no control over the affected creatures, but <i>calm emotions</i> can stop raging creatures from fighting or joyous ones from reveling. Creatures so affected cannot take violent actions (although they can defend themselves) or do anything destructive. Any aggressive action against or damage dealt to a calmed creature immediately breaks the spell on all calmed creatures.</p>\n      <p>This spell automatically suppresses (but does not dispel) any morale bonuses granted by spells such as <i>bless</i>,  <i>good hope</i>,  and <i>rage</i>,  as well as negating a bard\'s ability to inspire courage or a barbarian\'s rage ability. It also suppresses any fear effects and removes the <i>confused</i> condition from all targets. While the spell lasts, a suppressed spell or effect has no effect. When the <i>calm emotions</i> spell ends, the original spell or effect takes hold of the creature again, provided that its duration has not expired in the meantime.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Calm Emotions\" level=\"5\"><p><h5>Calm Emotions</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Cleric 2, Law 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Creatures in a 20-ft. -radius spread<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell calms agitated creatures. You have no control over the affected creatures, but <i>calm emotions</i> can stop raging creatures from fighting or joyous ones from reveling. Creatures so affected cannot take violent actions (although they can defend themselves) or do anything destructive. Any aggressive action against or damage dealt to a calmed creature immediately breaks the spell on all calmed creatures.</p><p>This spell automatically suppresses (but does not dispel) any morale bonuses granted by spells such as <i>bless</i>,  <i>good hope</i>,  and <i>rage</i>,  as well as negating a bard\'s ability to inspire courage or a barbarian\'s rage ability. It also suppresses any fear effects and removes the <i>confused</i> condition from all targets. While the spell lasts, a suppressed spell or effect has no effect. When the <i>calm emotions</i> spell ends, the original spell or effect takes hold of the creature again, provided that its duration has not expired in the meantime.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (150,'Cat\'s Grace','cat\'s grace','Transmutation',NULL,NULL,NULL,'Bard 2, Druid 2, Ranger 2, Sorcerer/Wizard 2','V, S, M','1 standard action','Touch','Creature touched',NULL,NULL,'1 min./level','Will negates (harmless)','Yes','Subject gains +4 to Dex for 1 min./level.',NULL,'A pinch of cat fur.',NULL,NULL,'\n      <p>The transmuted creature becomes more graceful, agile, and coordinated. The spell grants a +4 enhancement bonus to Dexterity, adding the usual benefits to AC, Reflex saves, and other uses of the Dexterity modifier.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cat\'s Grace\" level=\"5\"><p><h5>Cat\'s Grace</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Druid 2, Ranger 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>The transmuted creature becomes more graceful, agile, and coordinated. The spell grants a +4 enhancement bonus to Dexterity, adding the usual benefits to AC, Reflex saves, and other uses of the Dexterity modifier.</p><p><i>Material Component:</i> A pinch of cat fur.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (151,'Cat\'s Grace, Mass','mass cat\'s grace','Transmutation',NULL,NULL,NULL,'Bard 6, Druid 6, Sorcerer/Wizard 6','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'1 min./level','Will negates (harmless)','Yes','As cat\'s grace, affects one subject/level.',NULL,'A pinch of cat fur.',NULL,NULL,'\n      <p>This spell functions like <i>cat\'s grace</i>, except that it affects multiple creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cat\'s Grace, Mass\" level=\"5\"><p><h5>Cat\'s Grace, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 6, Druid 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level, no two of which can be more than 30 ft. apart<br/></td></tr></table><p>This spell functions like <i>cat\'s grace</i>, except that it affects multiple creatures.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (152,'Cause Fear','cause fear','Necromancy',NULL,'Fear, Mind-Affecting',NULL,'Bard 1, Cleric 1, Death 1, Sorcerer/Wizard 1','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One living creature with 5 or fewer HD',NULL,NULL,'1d4 rounds or 1 round; see text','Will partial','Yes','One creature of 5 HD or less flees for 1d4 rounds.',NULL,NULL,NULL,NULL,'\n      <p>The affected creature becomes frightened. If the subject succeeds on a Will save, it is shaken for 1 round. Creatures with 6 or more Hit Dice are immune to this effect.</p>\n      <p><i>Cause fear</i> counters and dispels <i>remove fear</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cause Fear\" level=\"5\"><p><h5>Cause Fear</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Fear, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Cleric 1, Death 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature with 5 or fewer HD<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1d4 rounds or 1 round; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will partial<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>The affected creature becomes frightened. If the subject succeeds on a Will save, it is shaken for 1 round. Creatures with 6 or more Hit Dice are immune to this effect.</p><p><i>Cause fear</i> counters and dispels <i>remove fear</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (153,'Chain Lightning','chain lightning','Evocation',NULL,'Electricity',NULL,'Air 6, Sorcerer/Wizard 6','V, S, F','1 standard action','Long (400 ft. + 40 ft./level)','One primary target, plus one secondary target/level (each of which must be within 30 ft. of the primary target)',NULL,NULL,'Instantaneous','Reflex half','Yes','1d6/level damage; 1 secondary bolt/level each deals half damage.',NULL,NULL,NULL,'A bit of fur; a piece of amber, glass, or a crystal rod; plus one silver pin for each of your caster levels.','\n      <p>This spell creates an electrical discharge that begins as a single stroke commencing from your fingertips. Unlike <i>lightning bolt</i>, <i>chain lightning</i> strikes one object or creature initially, then arcs to other targets.</p>\n      <p>The bolt deals 1d6 points of electricity damage per caster level (maximum 20d6) to the primary target. After it strikes, lightning can arc to a number of secondary targets equal to your caster level (maximum 20). The secondary bolts each strike one target and deal half as much damage as the primary one did (rounded down).</p>\n      <p>Each target can attempt a Reflex saving throw for half damage. You choose secondary targets as you like, but they must all be within 30 feet of the primary target, and no target can be struck more than once. You can choose to affect fewer secondary targets than the maximum.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Chain Lightning\" level=\"5\"><p><h5>Chain Lightning</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Electricity]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Air 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One primary target, plus one secondary target/level (each of which must be within 30 ft. of the primary target)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell creates an electrical discharge that begins as a single stroke commencing from your fingertips. Unlike <i>lightning bolt</i>, <i>chain lightning</i> strikes one object or creature initially, then arcs to other targets.</p><p>The bolt deals 1d6 points of electricity damage per caster level (maximum 20d6) to the primary target. After it strikes, lightning can arc to a number of secondary targets equal to your caster level (maximum 20). The secondary bolts each strike one target and deal half as much damage as the primary one did (rounded down).</p><p>Each target can attempt a Reflex saving throw for half damage. You choose secondary targets as you like, but they must all be within 30 feet of the primary target, and no target can be struck more than once. You can choose to affect fewer secondary targets than the maximum.</p><p><i>Focus:</i> A bit of fur; a piece of amber, glass, or a crystal rod; plus one silver pin for each of your caster levels.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (154,'Changestaff','changestaff','Transmutation',NULL,NULL,NULL,'Druid 7','V, S, F','1 round','Touch','Your touched staff',NULL,NULL,'1 hour/level (D)','None','No','Your staff becomes a treant on command.',NULL,NULL,NULL,'The quarterstaff, which must be specially prepared. The staff must be a sound limb cut from an ash, oak, or yew, then cured, shaped, carved, and polished (a process requiring twenty-eight days).','\n      <p>You change a specially prepared quarterstaff into a Huge treantlike creature, about 24 feet tall. When you plant the end of the staff in the ground and speak a special command to conclude the casting of the spell, your staff turns into a creature that looks and fights just like a treant. The staff-treant defends you and obeys any spoken commands. However, it is by no means a true treant; it cannot converse with actual treants or control trees. If the staff-treant is reduced to 0 or fewer hit points, it crumbles to powder and the staff is destroyed. Otherwise, the staff returns to its normal form when the spell duration expires (or when the spell is dismissed), and it can be used as the focus for another casting of the spell. The staff-treant is always at full strength when created, despite any wounds it may have incurred the last time it appeared.</p>\n      <p>You cannot adventure or engage in other strenuous activity during the shaping and carving of the staff.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Changestaff\" level=\"5\"><p><h5>Changestaff</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Your touched staff<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You change a specially prepared quarterstaff into a Huge treantlike creature, about 24 feet tall. When you plant the end of the staff in the ground and speak a special command to conclude the casting of the spell, your staff turns into a creature that looks and fights just like a treant. The staff-treant defends you and obeys any spoken commands. However, it is by no means a true treant; it cannot converse with actual treants or control trees. If the staff-treant is reduced to 0 or fewer hit points, it crumbles to powder and the staff is destroyed. Otherwise, the staff returns to its normal form when the spell duration expires (or when the spell is dismissed), and it can be used as the focus for another casting of the spell. The staff-treant is always at full strength when created, despite any wounds it may have incurred the last time it appeared.</p><p><i>Focus:</i> The quarterstaff, which must be specially prepared. The staff must be a sound limb cut from an ash, oak, or yew, then cured, shaped, carved, and polished (a process requiring twenty-eight days).</p><p>You cannot adventure or engage in other strenuous activity during the shaping and carving of the staff.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (155,'Chaos Hammer','chaos hammer','Evocation',NULL,'Chaotic',NULL,'Chaos 4','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'20-ft. -radius burst',NULL,'Instantaneous (1d6 rounds); see text','Will partial; see text','Yes','Damages and staggers lawful creatures.',NULL,NULL,NULL,NULL,'\n      <p>You unleash chaotic power to smite your enemies. The power takes the form of a multicolored explosion of leaping, ricocheting energy. Only lawful and neutral (not chaotic) creatures are harmed by the spell.</p>\n      <p>The spell deals 1d8 points of damage per two caster levels (maximum 5d8) to lawful creatures (or 1d6 points of damage per caster level, maximum 10d6, to lawful outsiders) and slows them for 1d6 rounds (see the <i>slow</i> spell). A successful Will save reduces the damage by half and negates the slow effect.</p>\n      <p>The spell deals only half damage against creatures who are neither lawful nor chaotic, and they are not slowed. Such a creature can reduce the damage by half again (down to one-quarter) with a successful Will save.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Chaos Hammer\" level=\"5\"><p><h5>Chaos Hammer</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Chaotic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Chaos 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>20-ft. -radius burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous (1d6 rounds); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will partial; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You unleash chaotic power to smite your enemies. The power takes the form of a multicolored explosion of leaping, ricocheting energy. Only lawful and neutral (not chaotic) creatures are harmed by the spell.</p><p>The spell deals 1d8 points of damage per two caster levels (maximum 5d8) to lawful creatures (or 1d6 points of damage per caster level, maximum 10d6, to lawful outsiders) and slows them for 1d6 rounds (see the <i>slow</i> spell). A successful Will save reduces the damage by half and negates the slow effect.</p><p>The spell deals only half damage against creatures who are neither lawful nor chaotic, and they are not slowed. Such a creature can reduce the damage by half again (down to one-quarter) with a successful Will save.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (156,'Charm Animal','charm animal','Enchantment','Charm','Mind-Affecting',NULL,'Druid 1, Ranger 1','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One animal',NULL,NULL,'1 hour/level','Will negates','Yes','Makes one animal your friend.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>charm person</i>, except that it affects a creature of the animal type.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Charm Animal\" level=\"5\"><p><h5>Charm Animal</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Charm) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 1, Ranger 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One animal<br/></td></tr></table><p>This spell functions like <i>charm person</i>, except that it affects a creature of the animal type.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (157,'Charm Monster','charm monster','Enchantment','Charm','Mind-Affecting',NULL,'Bard 3, Sorcerer/Wizard 4','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'One day/level','Will negates','Yes','Makes monster believe it is your ally.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>charm person</i>, except that the effect is not restricted by creature type or size.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Charm Monster\" level=\"5\"><p><h5>Charm Monster</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Charm) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level<br/></td></tr></table><p>This spell functions like <i>charm person</i>, except that the effect is not restricted by creature type or size.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (158,'Charm Monster, Mass','mass charm monster','Enchantment','Charm','Mind-Affecting',NULL,'Bard 6, Sorcerer/Wizard 8','V','1 standard action','Close (25 ft. + 5 ft./2 levels)','One or more creatures, no two of which can be more than 30 ft. apart',NULL,NULL,'One day/level','Will negates','Yes','As charm monster, but all within 30 ft.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>charm monster</i>,  except that <i>mass charm monster</i> affects a number of creatures whose combined HD do not exceed twice your level, or at least one creature regardless of HD. If there are more potential targets than you can affect, you choose them one at a time until you choose a creature with too many HD.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Charm Monster, Mass\" level=\"5\"><p><h5>Charm Monster, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Charm) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 6, Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One or more creatures, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level<br/></td></tr></table><p>This spell functions like <i>charm monster</i>,  except that <i>mass charm monster</i> affects a number of creatures whose combined HD do not exceed twice your level, or at least one creature regardless of HD. If there are more potential targets than you can affect, you choose them one at a time until you choose a creature with too many HD.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (159,'Charm Person','charm person','Enchantment','Charm','Mind-Affecting',NULL,'Bard 1, Sorcerer/Wizard 1','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One humanoid creature',NULL,NULL,'1 hour/level','Will negates','Yes','Makes one person your friend.',NULL,NULL,NULL,NULL,'\n      <p>This charm makes a humanoid creature regard you as its trusted friend and ally (treat the target\'s attitude as friendly). If the creature is currently being threatened or attacked by you or your allies, however, it receives a +5 bonus on its saving throw.</p>\n      <p>The spell does not enable you to control the <i>charmed</i> person as if it were an automaton, but it perceives your words and actions in the most favorable way. You can try to give the subject orders, but you must win an opposed Charisma check to convince it to do anything it wouldn\'t ordinarily do. (Retries are not allowed.) An affected creature never obeys suicidal or obviously harmful orders, but it might be convinced that something very dangerous is worth doing.  Any act by you or your apparent allies that threatens the <i>charmed</i> person breaks the spell. You must speak the person\'s language to communicate your commands, or else be good at pantomiming.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Charm Person\" level=\"5\"><p><h5>Charm Person</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Charm) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One humanoid creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This charm makes a humanoid creature regard you as its trusted friend and ally (treat the target\'s attitude as friendly). If the creature is currently being threatened or attacked by you or your allies, however, it receives a +5 bonus on its saving throw.</p><p>The spell does not enable you to control the <i>charmed</i> person as if it were an automaton, but it perceives your words and actions in the most favorable way. You can try to give the subject orders, but you must win an opposed Charisma check to convince it to do anything it wouldn\'t ordinarily do. (Retries are not allowed.) An affected creature never obeys suicidal or obviously harmful orders, but it might be convinced that something very dangerous is worth doing.  Any act by you or your apparent allies that threatens the <i>charmed</i> person breaks the spell. You must speak the person\'s language to communicate your commands, or else be good at pantomiming.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (160,'Chill Metal','chill metal','Transmutation',NULL,'Cold',NULL,'Druid 2','V, S, DF','1 standard action','Close (25 ft. + 5 ft./2 levels)','Metal equipment of one creature per two levels, no two of which can be more than 30 ft. apart; or 25 lb. of metal/level, none of which can be more than 30 ft. away from any of the rest',NULL,NULL,'7 rounds','Will negates (object)','Yes (object)','Cold metal damages those who touch it.',NULL,NULL,NULL,NULL,'\n      <p><i>chill metal</i> makes metal extremely cold. Unattended, nonmagical metal gets no saving throw. Magical metal is allowed a saving throw against the spell. An item in a creature\'s possession uses the creature\'s saving throw bonus unless its own is higher.</p>\n      <p>A creature takes cold damage if its equipment is chilled. It takes full damage if its armor is affected or if it is holding, touching, wearing, or carrying metal weighing one-fifth of its weight. The creature takes minimum damage (1 point or 2 points; see the table) if it\'s not wearing metal armor and the metal that it\'s carrying weighs less than one-fifth of its weight.</p>\n      <p>On the first round of the spell, the metal becomes chilly and uncomfortable to touch but deals no damage. The same effect also occurs on the last round of the spell\'s duration. During the second (and also the next-to-last) round, icy coldness causes pain and damage. In the third, fourth, and fifth rounds, the metal is freezing cold, causing more damage, as shown on the table below.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Round</b><br/></td> <td><b>Metal Temperature</b><br/></td>\n<td><b>Damage</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>1<br/></td>\n<td>Cold<br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>2<br/></td>\n<td>Icy<br/></td>\n<td>1d4 points<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>3-5<br/></td>\n<td>Freezing<br/></td>\n<td>2d4 points<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>6<br/></td>\n<td>Icy<br/></td>\n<td>1d4 points<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>7<br/></td>\n<td>Cold<br/></td>\n<td>None<br/></td>\n\n</tr>\n</table>\n      <p>Any heat intense enough to damage the creature negates cold damage from the spell (and vice versa) on a point-for-point basis. Underwater, <i>chill metal</i> deals no damage, but ice immediately forms around the affected metal, making it more buoyant.</p>\n      <p><i>chill metal</i> counters and dispels <i>heat metal</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Chill Metal\" level=\"5\"><p><h5>Chill Metal</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Cold]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Metal equipment of one creature per two levels, no two of which can be more than 30 ft. apart; or 25 lb. of metal/level, none of which can be more than 30 ft. away from any of the rest<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>7 rounds<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p><i>chill metal</i> makes metal extremely cold. Unattended, nonmagical metal gets no saving throw. Magical metal is allowed a saving throw against the spell. An item in a creature\'s possession uses the creature\'s saving throw bonus unless its own is higher.</p><p>A creature takes cold damage if its equipment is chilled. It takes full damage if its armor is affected or if it is holding, touching, wearing, or carrying metal weighing one-fifth of its weight. The creature takes minimum damage (1 point or 2 points; see the table) if it\'s not wearing metal armor and the metal that it\'s carrying weighs less than one-fifth of its weight.</p><p>On the first round of the spell, the metal becomes chilly and uncomfortable to touch but deals no damage. The same effect also occurs on the last round of the spell\'s duration. During the second (and also the next-to-last) round, icy coldness causes pain and damage. In the third, fourth, and fifth rounds, the metal is freezing cold, causing more damage, as shown on the table below.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Round</b><br/></td> <td><b>Metal Temperature</b><br/></td>\n<td><b>Damage</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>1<br/></td>\n<td>Cold<br/></td>\n<td>None<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>2<br/></td>\n<td>Icy<br/></td>\n<td>1d4 points<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>3-5<br/></td>\n<td>Freezing<br/></td>\n<td>2d4 points<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>6<br/></td>\n<td>Icy<br/></td>\n<td>1d4 points<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>7<br/></td>\n<td>Cold<br/></td>\n<td>None<br/></td>\n\n</tr>\n</table><p>Any heat intense enough to damage the creature negates cold damage from the spell (and vice versa) on a point-for-point basis. Underwater, <i>chill metal</i> deals no damage, but ice immediately forms around the affected metal, making it more buoyant.</p><p><i>chill metal</i> counters and dispels <i>heat metal</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (161,'Chill Touch','chill touch','Necromancy',NULL,NULL,NULL,'Sorcerer/Wizard 1','V, S','1 standard action','Touch','Creature or creatures touched (up to one/level)',NULL,NULL,'Instantaneous','Fortitude partial or Will negates; see text','Yes','One touch/level deals 1d6 damage and possibly 1 Str damage.',NULL,NULL,NULL,NULL,'\n      <p>A touch from your hand, which glows with blue energy, disrupts the life force of living creatures. Each touch channels negative energy that deals 1d6 points of damage. The touched creature also takes 1 point of Strength damage unless it makes a successful Fortitude saving throw. You can use this melee touch attack up to one time per level.</p>\n      <p>An undead creature you touch takes no damage of either sort, but it must make a successful Will saving throw or flee as if panicked for 1d4 rounds +1 round per caster level.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Chill Touch\" level=\"5\"><p><h5>Chill Touch</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Creature or creatures touched (up to one/level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude partial or Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A touch from your hand, which glows with blue energy, disrupts the life force of living creatures. Each touch channels negative energy that deals 1d6 points of damage. The touched creature also takes 1 point of Strength damage unless it makes a successful Fortitude saving throw. You can use this melee touch attack up to one time per level.</p><p>An undead creature you touch takes no damage of either sort, but it must make a successful Will saving throw or flee as if panicked for 1d4 rounds +1 round per caster level.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (162,'Circle of Death','circle of death','Necromancy',NULL,'Death',NULL,'Sorcerer/Wizard 6','V, S, M','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,'Several living creatures within a 40-ft. -radius burst',NULL,'Instantaneous','Fortitude negates','Yes','Kills 1d4/level HD of creatures.',NULL,'The powder of a crushed black pearl with a minimum value of 500 gp.',NULL,NULL,'\n      <p>A <i>circle of death</i> snuffs out the life force of living creatures, killing them instantly.</p>\n      <p>The spell slays 1d4 HD worth of living creatures per caster level (maximum 20d4). Creatures with the fewest HD are affected first; among creatures with equal HD, those who are closest to the burst\'s point of origin are affected first. No creature of 9 or more HD can be affected, and Hit Dice that are not sufficient to affect a creature are wasted.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Circle of Death\" level=\"5\"><p><h5>Circle of Death</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Death]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Several living creatures within a 40-ft. -radius burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A <i>circle of death</i> snuffs out the life force of living creatures, killing them instantly.</p><p>The spell slays 1d4 HD worth of living creatures per caster level (maximum 20d4). Creatures with the fewest HD are affected first; among creatures with equal HD, those who are closest to the burst\'s point of origin are affected first. No creature of 9 or more HD can be affected, and Hit Dice that are not sufficient to affect a creature are wasted.</p><p><i>Material Component:</i> The powder of a crushed black pearl with a minimum value of 500 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (163,'Clairaudience/Clairvoyance','clairaudience/clairvoyance','Divination','Scrying',NULL,NULL,'Bard 3, Knowledge 3, Sorcerer/Wizard 3','V, S, F/DF','10 minutes','Long (400 ft. + 40 ft./level)',NULL,NULL,'Magical sensor','1 min./level (D)','None','No','Hear or see at a distance for 1 min./level.',NULL,NULL,NULL,NULL,'\n      <p><i>Clairaudience/clairvoyance</i> creates an invisible magical sensor at a specific location that enables you to hear or see (your choice) almost as if you were there. You don\'t need line of sight or line of effect, but the locale must be known-a place familiar to you or an obvious one. Once you have selected the locale, the sensor doesn\'t move, but you can rotate it in all directions to view the area as desired. Unlike other scrying spells, this spell does not allow magically or supernaturally enhanced senses to work through it. If the chosen locale is magically dark, you see nothing. If it is naturally pitch black, you can see in a 10- foot radius around the center of the spell\'s effect. <i>Clairaudience/clairvoyance</i> functions only on the plane of existence you are currently occupying.</p>\n      <p/>\n    ',NULL,'A small horn (for hearing) or a glass eye (for seeing).',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Clairaudience/Clairvoyance\" level=\"5\"><p><h5>Clairaudience/Clairvoyance</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination (Scrying)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Knowledge 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Magical sensor<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p><i>Clairaudience/clairvoyance</i> creates an invisible magical sensor at a specific location that enables you to hear or see (your choice) almost as if you were there. You don\'t need line of sight or line of effect, but the locale must be known-a place familiar to you or an obvious one. Once you have selected the locale, the sensor doesn\'t move, but you can rotate it in all directions to view the area as desired. Unlike other scrying spells, this spell does not allow magically or supernaturally enhanced senses to work through it. If the chosen locale is magically dark, you see nothing. If it is naturally pitch black, you can see in a 10- foot radius around the center of the spell\'s effect. <i>Clairaudience/clairvoyance</i> functions only on the plane of existence you are currently occupying.</p><p><i>Arcane Focus:</i> A small horn (for hearing) or a glass eye (for seeing).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (164,'Clenched Fist','clenched fist','Evocation',NULL,'Force',NULL,'Sorcerer/Wizard 8, Strength 8','V, S, F/DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'10-ft. hand','1 round/level (D)','None','Yes','Large hand provides cover, pushes, or attacks your foes.',NULL,NULL,NULL,'A soft glove.','\n      <p>This spell functions like <i>interposing hand</i>,  except that the hand can interpose itself, push, or strike one opponent that you select. The floating hand can move as far as 60 feet and can attack in the same round. Since this hand is directed by you, its ability to notice or attack invisible or concealed creatures is no better than yours.</p>\n      <p>The hand attacks once per round, and its attack bonus equals your caster level + your Intelligence, Wisdom, or Charisma modifier (for a wizard, cleric, or sorcerer, respectively), +11 for the hand\'s Strength score (33), -1 for being Large. The hand deals 1d8+11 points of damage on each attack, and any creature struck must make a Fortitude save (against this spell\'s save DC) or be stunned for 1 round. Directing the spell to a new target is a move action.</p>\n      <p>The <i>clenched fist</i> can also interpose itself as <i>interposing hand</i> does, or it can bull rush an opponent as <i>forceful hand</i> does, but at a +15 bonus on the Strength check.</p>\n      <p>Clerics who cast this spell name it for their deities.</p>\n      <p/>\n    ',NULL,'A leather glove.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Clenched Fist\" level=\"5\"><p><h5>Clenched Fist</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8, Strength 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F/DF<br/></td></tr></table><p>This spell functions like <i>interposing hand</i>,  except that the hand can interpose itself, push, or strike one opponent that you select. The floating hand can move as far as 60 feet and can attack in the same round. Since this hand is directed by you, its ability to notice or attack invisible or concealed creatures is no better than yours.</p><p>The hand attacks once per round, and its attack bonus equals your caster level + your Intelligence, Wisdom, or Charisma modifier (for a wizard, cleric, or sorcerer, respectively), +11 for the hand\'s Strength score (33), -1 for being Large. The hand deals 1d8+11 points of damage on each attack, and any creature struck must make a Fortitude save (against this spell\'s save DC) or be stunned for 1 round. Directing the spell to a new target is a move action.</p><p>The <i>clenched fist</i> can also interpose itself as <i>interposing hand</i> does, or it can bull rush an opponent as <i>forceful hand</i> does, but at a +15 bonus on the Strength check.</p><p>Clerics who cast this spell name it for their deities.</p><p><i>Arcane Focus:</i> A leather glove.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (165,'Cloak of Chaos','cloak of chaos','Abjuration',NULL,'Chaotic',NULL,'Chaos 8, Cleric 8','V, S, F','1 standard action','20 ft.','One creature/level in a 20-ft. -radius burst centered on you',NULL,NULL,'1 round/level (D)','See text','Yes (harmless)','+4 to AC, +4 resistance, spell resistance 25 against lawful spells.',NULL,NULL,NULL,'A tiny reliquary containing some sacred relic, such as a scrap of parchment from a chaotic text. The reliquary costs at least 500 gp.','\n      <p>A random pattern of color surrounds the subjects, protecting them from attacks, granting them resistance to spells cast by lawful creatures, and causing lawful creatures that strike the subjects to become <i>confused</i>. This abjuration has four effects.</p>\n      <p>First, each warded creature gains a +4 deflection bonus to AC and a +4 resistance bonus on saves. Unlike <i>protection from law</i>, the benefit of this spell applies against all attacks, not just against attacks by lawful creatures.</p>\n      <p>Second, each warded creature gains spell resistance 25 against lawful spells and spells cast by lawful creatures.</p>\n      <p>Third, the abjuration blocks possession and mental influence, just as <i>protection from law</i> does.</p>\n      <p>Finally, if a lawful creature succeeds on a melee attack against a warded creature, the offending attacker is <i>confused</i> for 1 round (Will save negates, as with the <i>confusion</i> spell, but against the save DC of <i>cloak of chaos</i>).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cloak of Chaos\" level=\"5\"><p><h5>Cloak of Chaos</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Abjuration [Chaotic]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Chaos 8, Cleric 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>20 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level in a 20-ft. -radius burst centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>See text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>A random pattern of color surrounds the subjects, protecting them from attacks, granting them resistance to spells cast by lawful creatures, and causing lawful creatures that strike the subjects to become <i>confused</i>. This abjuration has four effects.</p><p>First, each warded creature gains a +4 deflection bonus to AC and a +4 resistance bonus on saves. Unlike <i>protection from law</i>, the benefit of this spell applies against all attacks, not just against attacks by lawful creatures.</p><p>Second, each warded creature gains spell resistance 25 against lawful spells and spells cast by lawful creatures.</p><p>Third, the abjuration blocks possession and mental influence, just as <i>protection from law</i> does.</p><p>Finally, if a lawful creature succeeds on a melee attack against a warded creature, the offending attacker is <i>confused</i> for 1 round (Will save negates, as with the <i>confusion</i> spell, but against the save DC of <i>cloak of chaos</i>).</p><p><i>Focus:</i> A tiny reliquary containing some sacred relic, such as a scrap of parchment from a chaotic text. The reliquary costs at least 500 gp.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (166,'Clone','clone','Necromancy',NULL,NULL,NULL,'Sorcerer/Wizard 8','V, S, M, F','10 minutes','0 ft.',NULL,NULL,'One clone','Instantaneous','None','No','Duplicate awakens when original dies.',NULL,'The piece of flesh and various laboratory supplies (cost 1,000 gp).',NULL,'Special laboratory equipment (cost 500 gp).','\n      <p>This spell makes an inert duplicate of a creature. If the original individual has been slain, its soul immediately transfers to the clone, creating a replacement (provided that the soul is free and willing to return). The original\'s physical remains, should they still exist, become inert and cannot thereafter be restored to life. If the original creature has reached the end of its natural life span (that is, it has died of natural causes), any cloning attempt fails.</p>\n      <p>To create the duplicate, you must have a piece of flesh (not hair, nails, scales, or the like) with a volume of at least 1 cubic inch that was taken from the original creature\'s living body. The piece of flesh need not be fresh, but it must be kept from rotting. Once the spell is cast, the duplicate must be grown in a laboratory for 2d4 months.</p>\n      <p>When the clone is completed, the original\'s soul enters it immediately, if that creature is already dead. The clone is physically identical with the original and possesses the same personality and memories as the original. In other respects, treat the clone as if it were the original character raised from the dead, including the loss of one level or 2 points of Constitution (if the original was a 1st-level character). If this Constitution adjustment would give the clone a Constitution score of 0, the spell fails. If the original creature has lost levels since the flesh sample was taken and died at a lower level than the clone would otherwise be, the clone is one level below the level at which the original died.</p>\n      <p>The spell duplicates only the original\'s body and mind, not its equipment.</p>\n      <p>A duplicate can be grown while the original still lives, or when the original soul is unavailable, but the resulting body is merely a soulless bit of inert flesh, which rots if not preserved.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Clone\" level=\"5\"><p><h5>Clone</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>0 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One clone<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell makes an inert duplicate of a creature. If the original individual has been slain, its soul immediately transfers to the clone, creating a replacement (provided that the soul is free and willing to return). The original\'s physical remains, should they still exist, become inert and cannot thereafter be restored to life. If the original creature has reached the end of its natural life span (that is, it has died of natural causes), any cloning attempt fails.</p><p>To create the duplicate, you must have a piece of flesh (not hair, nails, scales, or the like) with a volume of at least 1 cubic inch that was taken from the original creature\'s living body. The piece of flesh need not be fresh, but it must be kept from rotting. Once the spell is cast, the duplicate must be grown in a laboratory for 2d4 months.</p><p>When the clone is completed, the original\'s soul enters it immediately, if that creature is already dead. The clone is physically identical with the original and possesses the same personality and memories as the original. In other respects, treat the clone as if it were the original character raised from the dead, including the loss of one level or 2 points of Constitution (if the original was a 1st-level character). If this Constitution adjustment would give the clone a Constitution score of 0, the spell fails. If the original creature has lost levels since the flesh sample was taken and died at a lower level than the clone would otherwise be, the clone is one level below the level at which the original died.</p><p>The spell duplicates only the original\'s body and mind, not its equipment.</p><p>A duplicate can be grown while the original still lives, or when the original soul is unavailable, but the resulting body is merely a soulless bit of inert flesh, which rots if not preserved.</p><p><i>Material Component:</i> The piece of flesh and various laboratory supplies (cost 1,000 gp).</p><p><i>Focus:</i> Special laboratory equipment (cost 500 gp).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (167,'Cloudkill','cloudkill','Conjuration','Creation',NULL,NULL,'Sorcerer/Wizard 5','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Cloud spreads in 20-ft. radius, 20 ft. high','1 min./level','Fortitude partial; see text','No','Kills 3 HD or less; 4-6 HD save or die, 6+ HD take Con damage.',NULL,NULL,NULL,NULL,'\n      <p>This spell generates a bank of fog, similar to a <i>fog cloud</i>,  except that its vapors are yellowish green and poisonous. These vapors automatically kill any living creature with 3 or fewer HD (no save). A living creature with 4 to 6 HD is slain unless it succeeds on a Fortitude save (in which case it takes 1d4 points of Constitution damage on your turn each round while in the cloud).</p>\n      <p>A living creature with 6 or more HD takes 1d4 points of Constitution damage on your turn each round while in the cloud (a successful Fortitude save halves this damage). Holding one\'s breath doesn\'t help, but creatures immune to poison are unaffected by the spell.</p>\n      <p>Unlike a <i>fog cloud</i>, the <i>cloudkill</i> moves away from you at 10 feet per round, rolling along the surface of the ground.</p>\n      <p>Figure out the cloud\'s new spread each round based on its new point of origin, which is 10 feet farther away from the point of origin where you cast the spell.</p>\n      <p>Because the vapors are heavier than air, they sink to the lowest level of the land, even pouring down den or sinkhole openings. It cannot penetrate liquids, nor can it be cast underwater.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cloudkill\" level=\"5\"><p><h5>Cloudkill</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Cloud spreads in 20-ft. radius, 20 ft. high<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude partial; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell generates a bank of fog, similar to a <i>fog cloud</i>,  except that its vapors are yellowish green and poisonous. These vapors automatically kill any living creature with 3 or fewer HD (no save). A living creature with 4 to 6 HD is slain unless it succeeds on a Fortitude save (in which case it takes 1d4 points of Constitution damage on your turn each round while in the cloud).</p><p>A living creature with 6 or more HD takes 1d4 points of Constitution damage on your turn each round while in the cloud (a successful Fortitude save halves this damage). Holding one\'s breath doesn\'t help, but creatures immune to poison are unaffected by the spell.</p><p>Unlike a <i>fog cloud</i>, the <i>cloudkill</i> moves away from you at 10 feet per round, rolling along the surface of the ground.</p><p>Figure out the cloud\'s new spread each round based on its new point of origin, which is 10 feet farther away from the point of origin where you cast the spell.</p><p>Because the vapors are heavier than air, they sink to the lowest level of the land, even pouring down den or sinkhole openings. It cannot penetrate liquids, nor can it be cast underwater.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (168,'Color Spray','color spray','Illusion','Pattern','Mind-Affecting',NULL,'Sorcerer/Wizard 1','V, S, M','1 standard action','15 ft.',NULL,'Cone-shaped burst',NULL,'Instantaneous; see text','Will negates','Yes','Knocks unconscious, blinds, and/or stuns weak creatures.',NULL,'A pinch each of powder or sand that is colored red, yellow, and blue.',NULL,NULL,'\n      <p>A vivid cone of clashing colors springs forth from your hand, causing creatures to become stunned, perhaps also blinded, and possibly knocking them unconscious.</p>\n      <p>Each creature within the cone is affected according to its Hit Dice.</p>\n      <p><i>2 HD or less:</i> The creature is unconscious, blinded, and stunned for 2d4 rounds, then blinded and stunned for 1d4 rounds, and then stunned for 1 round. (Only living creatures are knocked unconscious.)</p>\n      <p><i>3 or 4 HD:</i> The creature is blinded and stunned for 1d4 rounds, then stunned for 1 round.</p>\n      <p><i>5 or more HD:</i> The creature is stunned for 1 round.</p>\n      <p>Sightless creatures are not affected by <i>color spray</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Color Spray\" level=\"5\"><p><h5>Color Spray</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Illusion (Pattern) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>15 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>A vivid cone of clashing colors springs forth from your hand, causing creatures to become stunned, perhaps also blinded, and possibly knocking them unconscious.</p><p>Each creature within the cone is affected according to its Hit Dice.</p><p><i>2 HD or less:</i> The creature is unconscious, blinded, and stunned for 2d4 rounds, then blinded and stunned for 1d4 rounds, and then stunned for 1 round. (Only living creatures are knocked unconscious.)</p><p><i>3 or 4 HD:</i> The creature is blinded and stunned for 1d4 rounds, then stunned for 1 round.</p><p><i>5 or more HD:</i> The creature is stunned for 1 round.</p><p>Sightless creatures are not affected by <i>color spray</i>.</p><p><i>Material Component:</i> A pinch each of powder or sand that is colored red, yellow, and blue.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (169,'Command','command','Enchantment','Compulsion','Language-Dependent, Mind-Affecting',NULL,'Cleric 1','V','1 standard action','Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'1 round','Will negates','Yes','One subject obeys selected command for 1 round.',NULL,NULL,NULL,NULL,'\n      <p>You give the subject a single command, which it obeys to the best of its ability at its earliest opportunity. You may select from the following options.</p>\n      <p><i>Approach:</i> On its turn, the subject moves toward you as quickly and directly as possible for 1 round. The creature may do nothing but move during its turn, and it provokes attacks of opportunity for this movement as normal.</p>\n      <p><i>Drop:</i> On its turn, the subject drops whatever it is holding. It can\'t pick up any dropped item until its next turn.</p>\n      <p><i>Fall:</i> On its turn, the subject falls to the ground and remains prone for 1 round. It may act normally while prone but takes any appropriate penalties.</p>\n      <p><i>Flee:</i> On its turn, the subject moves away from you as quickly as possible for 1 round. It may do nothing but move during its turn, and it provokes attacks of opportunity for this movement as normal.</p>\n      <p><i>Halt:</i> The subject stands in place for 1 round. It may not take any actions but is not considered helpless.</p>\n      <p>If the subject can\'t carry out your command on its next turn, the spell automatically fails.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Command\" level=\"5\"><p><h5>Command</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Language-Dependent, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You give the subject a single command, which it obeys to the best of its ability at its earliest opportunity. You may select from the following options.</p><p><i>Approach:</i> On its turn, the subject moves toward you as quickly and directly as possible for 1 round. The creature may do nothing but move during its turn, and it provokes attacks of opportunity for this movement as normal.</p><p><i>Drop:</i> On its turn, the subject drops whatever it is holding. It can\'t pick up any dropped item until its next turn.</p><p><i>Fall:</i> On its turn, the subject falls to the ground and remains prone for 1 round. It may act normally while prone but takes any appropriate penalties.</p><p><i>Flee:</i> On its turn, the subject moves away from you as quickly as possible for 1 round. It may do nothing but move during its turn, and it provokes attacks of opportunity for this movement as normal.</p><p><i>Halt:</i> The subject stands in place for 1 round. It may not take any actions but is not considered helpless.</p><p>If the subject can\'t carry out your command on its next turn, the spell automatically fails.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (170,'Command, Greater','greater command','Enchantment','Compulsion','Language-Dependent, Mind-Affecting',NULL,'Cleric 5','V','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'1 round/level','Will negates','Yes','As command, but affects one subject/level.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>command</i>,  except that up to one creature per level may be affected, and the activities continue beyond 1 round. At the start of each commanded creature\'s action after the first, it gets another Will save to attempt to break free from the spell. Each creature must receive the same command.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Command, Greater\" level=\"5\"><p><h5>Command, Greater</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Language-Dependent, Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One creature/level, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr></table><p>This spell functions like <i>command</i>,  except that up to one creature per level may be affected, and the activities continue beyond 1 round. At the start of each commanded creature\'s action after the first, it gets another Will save to attempt to break free from the spell. Each creature must receive the same command.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (171,'Command Plants','command plants','Transmutation',NULL,NULL,NULL,'Druid 4, Plant 4, Ranger 3','V','1 standard action','Close (25 ft. + 5 ft./2 levels)','Up to 2 HD/level of plant creatures, no two of which can be more than 30 ft. apart',NULL,NULL,'One day/level','Will negates','Yes','Sway the actions of one or more plant creatures.',NULL,NULL,NULL,NULL,'\n      <p>This spell allows you some degree of control over one or more plant creatures. Affected plant creatures can understand you, and they perceive your words and actions in the most favorable way (treat their attitude as friendly). They will not attack you while the spell lasts. You can try to give a subject orders, but you must win an opposed Charisma check to convince it to do anything it wouldn\'t ordinarily do. (Retries are not allowed.) A commanded plant never obeys suicidal or obviously harmful orders, but it might be convinced that something very dangerous is worth doing.</p>\n      <p>You can affect a number of plant creatures whose combined level or HD do not exceed twice your level.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Command Plants\" level=\"5\"><p><h5>Command Plants</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 4, Plant 4, Ranger 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to 2 HD/level of plant creatures, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell allows you some degree of control over one or more plant creatures. Affected plant creatures can understand you, and they perceive your words and actions in the most favorable way (treat their attitude as friendly). They will not attack you while the spell lasts. You can try to give a subject orders, but you must win an opposed Charisma check to convince it to do anything it wouldn\'t ordinarily do. (Retries are not allowed.) A commanded plant never obeys suicidal or obviously harmful orders, but it might be convinced that something very dangerous is worth doing.</p><p>You can affect a number of plant creatures whose combined level or HD do not exceed twice your level.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (172,'Command Undead','command undead','Necromancy',NULL,NULL,NULL,'Sorcerer/Wizard 2','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)','One undead creature',NULL,NULL,'One day/level','Will negates; see text','Yes','Undead creature obeys your commands.',NULL,'A shred of raw meat and a splinter of bone.',NULL,NULL,'\n      <p>This spell allows you some degree of control over an undead creature. Assuming the subject is intelligent, it perceives your words and actions in the most favorable way (treat its attitude as friendly). It will not attack you while the spell lasts. You can try to give the subject orders, but you must win an opposed Charisma check to convince it to do anything it wouldn\'t ordinarily do. (Retries are not allowed.) An intelligent commanded undead never obeys suicidal or obviously harmful orders, but it might be convinced that something very dangerous is worth doing.</p>\n      <p>A nonintelligent undead creature gets no saving throw against this spell. When you control a mindless being, you can communicate only basic commands, such as \'come here,\' \'go there,\' \'fight,\' \'stand still,\' and so on. Nonintelligent undead won\'t resist suicidal or obviously harmful orders.</p>\n      <p>Any act by you or your apparent allies that threatens the commanded undead (regardless of its Intelligence) breaks the spell.</p>\n      <p>Your commands are not telepathic. The undead creature must be able to hear you.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Command Undead\" level=\"5\"><p><h5>Command Undead</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>One undead creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell allows you some degree of control over an undead creature. Assuming the subject is intelligent, it perceives your words and actions in the most favorable way (treat its attitude as friendly). It will not attack you while the spell lasts. You can try to give the subject orders, but you must win an opposed Charisma check to convince it to do anything it wouldn\'t ordinarily do. (Retries are not allowed.) An intelligent commanded undead never obeys suicidal or obviously harmful orders, but it might be convinced that something very dangerous is worth doing.</p><p>A nonintelligent undead creature gets no saving throw against this spell. When you control a mindless being, you can communicate only basic commands, such as \'come here,\' \'go there,\' \'fight,\' \'stand still,\' and so on. Nonintelligent undead won\'t resist suicidal or obviously harmful orders.</p><p>Any act by you or your apparent allies that threatens the commanded undead (regardless of its Intelligence) breaks the spell.</p><p>Your commands are not telepathic. The undead creature must be able to hear you.</p><p><i>Material Component:</i> A shred of raw meat and a splinter of bone.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (173,'Commune','commune','Divination',NULL,NULL,NULL,'Cleric 5','V, S, M, DF, XP','10 minutes','Personal','You',NULL,NULL,'1 round/level',NULL,NULL,'Deity answers one yes-or-no question/level.',NULL,'Holy (or unholy) water and incense.',NULL,NULL,'\n      <p>You contact your deity-or agents thereof -and ask questions that can be answered by a simple yes or no. (A cleric of no particular deity contacts a philosophically allied deity.) You are allowed one such question per caster level. The answers given are correct within the limits of the entity\'s knowledge. \'Unclear\' is a legitimate answer, because powerful beings of the Outer Planes are not necessarily omniscient. In cases where a one-word answer would be misleading or contrary to the deity\'s interests, a short phrase (five words or less) may be given as an answer instead.</p>\n      <p>The spell, at best, provides information to aid character decisions. The entities contacted structure their answers to further their own purposes. If you lag, discuss the answers, or go off to do anything else, the spell ends.</p>\n      <p/>\n    ','100 XP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Commune\" level=\"5\"><p><h5>Commune</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, DF, XP<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr></table><p>You contact your deity-or agents thereof -and ask questions that can be answered by a simple yes or no. (A cleric of no particular deity contacts a philosophically allied deity.) You are allowed one such question per caster level. The answers given are correct within the limits of the entity\'s knowledge. \'Unclear\' is a legitimate answer, because powerful beings of the Outer Planes are not necessarily omniscient. In cases where a one-word answer would be misleading or contrary to the deity\'s interests, a short phrase (five words or less) may be given as an answer instead.</p><p>The spell, at best, provides information to aid character decisions. The entities contacted structure their answers to further their own purposes. If you lag, discuss the answers, or go off to do anything else, the spell ends.</p><p><i>Material Component:</i> Holy (or unholy) water and incense.</p><p><i>XP Cost:</i> 100 XP.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (174,'Commune with Nature','commune with nature','Divination',NULL,NULL,NULL,'Animal 5, Druid 5, Ranger 4','V, S','10 minutes','Personal','You',NULL,NULL,'Instantaneous',NULL,NULL,'Learn about terrain for 1 mile/level.',NULL,NULL,NULL,NULL,'\n      <p>You become one with nature, attaining knowledge of the surrounding territory. You instantly gain knowledge of as many as three facts from among the following subjects: the ground or terrain, plants, minerals, bodies of water, people, general animal population, presence of woodland creatures, presence of powerful unnatural creatures, or even the general state of the natural setting.</p>\n      <p>In outdoor settings, the spell operates in a radius of 1 mile per caster level. In natural underground settings-caves, caverns, and the like-the radius is limited to 100 feet per caster level. The spell does not function where nature has been replaced by construction or settlement, such as in dungeons and towns.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Commune with Nature\" level=\"5\"><p><h5>Commune with Nature</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Animal 5, Druid 5, Ranger 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr></table><p>You become one with nature, attaining knowledge of the surrounding territory. You instantly gain knowledge of as many as three facts from among the following subjects: the ground or terrain, plants, minerals, bodies of water, people, general animal population, presence of woodland creatures, presence of powerful unnatural creatures, or even the general state of the natural setting.</p><p>In outdoor settings, the spell operates in a radius of 1 mile per caster level. In natural underground settings-caves, caverns, and the like-the radius is limited to 100 feet per caster level. The spell does not function where nature has been replaced by construction or settlement, such as in dungeons and towns.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (175,'Comprehend Languages','comprehend languages','Divination',NULL,NULL,NULL,'Bard 1, Cleric 1, Sorcerer/Wizard 1','V, S, M/DF','1 standard action','Personal','You',NULL,NULL,'10 min./level',NULL,NULL,'You understand all spoken and written languages.',NULL,NULL,'A pinch of soot and a few grains of salt.',NULL,'\n      <p>You can understand the spoken words of creatures or read otherwise incomprehensible written messages. In either case, you must touch the creature or the writing. The ability to read does not necessarily impart insight into the material, merely its literal meaning. The spell enables you to understand or read an unknown language, not speak or write it.</p>\n      <p>Written material can be read at the rate of one page (250 words) per minute. Magical writing cannot be read, though the spell reveals that it is magical. This spell can be foiled by certain warding magic (such as the <i>secret page</i> and <i>illusory script</i> spells). It does not decipher codes or reveal messages concealed in otherwise normal text.</p>\n      <p><i>Comprehend languages</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Comprehend Languages\" level=\"5\"><p><h5>Comprehend Languages</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Cleric 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr></table><p>You can understand the spoken words of creatures or read otherwise incomprehensible written messages. In either case, you must touch the creature or the writing. The ability to read does not necessarily impart insight into the material, merely its literal meaning. The spell enables you to understand or read an unknown language, not speak or write it.</p><p>Written material can be read at the rate of one page (250 words) per minute. Magical writing cannot be read, though the spell reveals that it is magical. This spell can be foiled by certain warding magic (such as the <i>secret page</i> and <i>illusory script</i> spells). It does not decipher codes or reveal messages concealed in otherwise normal text.</p><p><i>Comprehend languages</i> can be made permanent with a <i>permanency</i> spell.</p><p><i>Arcane Material Component:</i> A pinch of soot and a few grains of salt.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (176,'Cone of Cold','cone of cold','Evocation',NULL,'Cold',NULL,'Sorcerer/Wizard 5, Water 6','V, S, M/DF','1 standard action','60 ft.',NULL,'Cone-shaped burst',NULL,'Instantaneous','Reflex half','Yes','1d6/level cold damage.',NULL,NULL,'A very small crystal or glass cone.',NULL,'\n      <p><i>Cone of cold</i> creates an area of extreme cold, originating at your hand and extending outward in a cone. It drains heat, dealing 1d6 points of cold damage per caster level (maximum 15d6).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cone of Cold\" level=\"5\"><p><h5>Cone of Cold</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Cold]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5, Water 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Reflex half<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p><i>Cone of cold</i> creates an area of extreme cold, originating at your hand and extending outward in a cone. It drains heat, dealing 1d6 points of cold damage per caster level (maximum 15d6).</p><p><i>Arcane Material Component:</i> A very small crystal or glass cone.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (177,'Confusion','confusion','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 3, Sorcerer/Wizard 4, Trickery 4','V, S, M/DF','1 standard action','Medium (100 ft. + 10 ft./level)','All creatures in a 15-ft. radius burst',NULL,NULL,'1 round/level','Will negates','Yes','Subjects behave oddly for 1 round/level.',NULL,NULL,'A set of three nut shells.',NULL,'\n      <p>This spell causes the targets to become <i>confused</i>,  making them unable to independently determine what they will do.</p>\n      <p>Roll on the following table at the beginning of each subject\'s turn each round to see what the subject does in that round.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>d%</b><br/></td> <td><b>Behavior</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>01-10<br/></td>\n<td>Attack caster with melee or ranged weapons (or close with caster if attack is not possible).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>11-20<br/></td>\n<td>Act normally.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>21-50<br/></td>\n<td>Do nothing but babble incoherently.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>51-70<br/></td>\n<td>Flee away from caster at top possible speed.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>71-100<br/></td>\n<td>Attack nearest creature (for this purpose, a familiar counts as part of the subject\'s self).<br/></td>\n\n</tr>\n</table>\n      <p>A <i>confused</i> character who can\'t carry out the indicated action does nothing but babble incoherently. Attackers are not at any special advantage when attacking a <i>confused</i> character. Any <i>confused</i> character who is attacked automatically attacks its attackers on its next turn, as long as it is still <i>confused</i> when its turn comes. Note that a <i>confused</i> character will not make attacks of opportunity against any creature that it is not already devoted to attacking (either because of its most recent action or because it has just been attacked).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Confusion\" level=\"5\"><p><h5>Confusion</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 4, Trickery 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>All creatures in a 15-ft. radius burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell causes the targets to become <i>confused</i>,  making them unable to independently determine what they will do.</p><p>Roll on the following table at the beginning of each subject\'s turn each round to see what the subject does in that round.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>d%</b><br/></td> <td><b>Behavior</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>01-10<br/></td>\n<td>Attack caster with melee or ranged weapons (or close with caster if attack is not possible).<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>11-20<br/></td>\n<td>Act normally.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>21-50<br/></td>\n<td>Do nothing but babble incoherently.<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>51-70<br/></td>\n<td>Flee away from caster at top possible speed.<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>71-100<br/></td>\n<td>Attack nearest creature (for this purpose, a familiar counts as part of the subject\'s self).<br/></td>\n\n</tr>\n</table><p>A <i>confused</i> character who can\'t carry out the indicated action does nothing but babble incoherently. Attackers are not at any special advantage when attacking a <i>confused</i> character. Any <i>confused</i> character who is attacked automatically attacks its attackers on its next turn, as long as it is still <i>confused</i> when its turn comes. Note that a <i>confused</i> character will not make attacks of opportunity against any creature that it is not already devoted to attacking (either because of its most recent action or because it has just been attacked).</p><p><i>Arcane Material Component:</i> A set of three nut shells.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (178,'Confusion, Lesser','lesser confusion','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 1','V, S, DF','1 standard action','Close (25 ft. + 5 ft./2 levels)','One living creature',NULL,NULL,'1 round','Will negates','Yes','Subjects behave oddly for 1 round/level.',NULL,NULL,'A set of three nut shells.',NULL,'\n      <p>As <i>confusion</i>, except that this spell causes a single creature to become <i>confused</i> for 1 round. See the <i>confusion</i> spell, above, to determine the exact effect on the subject.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Confusion, Lesser\" level=\"5\"><p><h5>Confusion, Lesser</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round<br/></td></tr></table><p>As <i>confusion</i>, except that this spell causes a single creature to become <i>confused</i> for 1 round. See the <i>confusion</i> spell, above, to determine the exact effect on the subject.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (179,'Consecrate','consecrate','Evocation',NULL,'Good',NULL,'Cleric 2','V, S, M, DF','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,'20-ft. -radius emanation',NULL,'2 hours/level','None','No','Fills area with positive energy, making undead weaker.',NULL,'A vial of holy water and 25 gp worth (5 pounds) of silver dust, all of which must be sprinkled around the area.',NULL,NULL,'\n      <p>This spell blesses an area with positive energy. Each Charisma check made to turn undead within this area gains a +3 sacred bonus. Every undead creature entering a <i>consecrated</i> area suffers minor disruption, giving it a -1 penalty on attack rolls, damage rolls, and saves. Undead cannot be created within or summoned into a <i>consecrated</i> area.</p>\n      <p>If the <i>consecrated</i> area contains an altar, shrine, or other permanent fixture dedicated to your deity, pantheon, or aligned higher power, the modifiers given above are doubled (+6 sacred bonus on turning checks, -2 penalties for undead in the area). You cannot consecrate an area with a similar fixture of a deity other than your own patron.</p>\n      <p>If the area does contain an altar, shrine, or other permanent fixture of a deity, pantheon, or higher power other than your patron, the <i>Consecrate</i> spell instead curses the area, cutting off its connection with the associated deity or power. This secondary function, if used, does not also grant the bonuses and penalties relating to undead, as given above.</p>\n      <p><i>Consecrate</i> counters and dispels <i>desecrate</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Consecrate\" level=\"5\"><p><h5>Consecrate</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Good]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>20-ft. -radius emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>2 hours/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell blesses an area with positive energy. Each Charisma check made to turn undead within this area gains a +3 sacred bonus. Every undead creature entering a <i>consecrated</i> area suffers minor disruption, giving it a -1 penalty on attack rolls, damage rolls, and saves. Undead cannot be created within or summoned into a <i>consecrated</i> area.</p><p>If the <i>consecrated</i> area contains an altar, shrine, or other permanent fixture dedicated to your deity, pantheon, or aligned higher power, the modifiers given above are doubled (+6 sacred bonus on turning checks, -2 penalties for undead in the area). You cannot consecrate an area with a similar fixture of a deity other than your own patron.</p><p>If the area does contain an altar, shrine, or other permanent fixture of a deity, pantheon, or higher power other than your patron, the <i>Consecrate</i> spell instead curses the area, cutting off its connection with the associated deity or power. This secondary function, if used, does not also grant the bonuses and penalties relating to undead, as given above.</p><p><i>Consecrate</i> counters and dispels <i>desecrate</i>.</p><p><i>Material Component:</i> A vial of holy water and 25 gp worth (5 pounds) of silver dust, all of which must be sprinkled around the area.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (180,'Contact Other Plane','contact other plane','Divination',NULL,NULL,NULL,'Sorcerer/Wizard 5','V','10 minutes','Personal','You',NULL,NULL,'Concentration',NULL,NULL,'Lets you ask question of extraplanar entity.',NULL,NULL,NULL,NULL,'\n      <p>You send your mind to another plane of existence (an Elemental Plane or some plane farther removed) in order to receive advice and information from powers there. (See the accompanying table for possible consequences and results of the attempt.) The powers reply in a language you understand, but they resent such contact and give only brief answers to your questions. (All questions are answered with \'yes,\' \'no,\' \'maybe,\' \'never,\' \'irrelevant,\' or some other one-word answer.)</p>\n      <p>You must concentrate on maintaining the spell (a standard action) in order to ask questions at the rate of one per round. A question is answered by the power during the same round. For every two caster levels, you may ask one question.</p>\n      <p>Contact with minds far removed from your home plane increases the probability that you will incur a decrease to Intelligence and Charisma, but the chance of the power knowing the answer, as well as the probability of the entity answering correctly, are likewise increased by moving to distant planes.</p>\n      <p>Once the Outer Planes are reached, the power of the deity contacted determines the effects. (Random results obtained from the table are subject to the personalities of individual deities.)</p>\n      <p>On rare occasions, this divination may be blocked by an act of certain deities or forces.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>Plane Contacted</b><br/></td>\n<td><b>Avoid Int/Cha Decrease</b><br/></td>\n<td><b>True Answer</b><br/></td>\n<td><b>Don\'t Know</b><br/></td>\n<td><b>Lie</b><br/></td>\n<td><b>Random Answer</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Elemental Plane<br/></td>\n<td>DC 7/1 week<br/></td>\n<td>01-34<br/></td>\n<td>35-62<br/></td>\n<td>63-83<br/></td>\n<td>84-100<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>(appropriate)<br/></td>\n<td>(DC 7/1 week)<br/></td>\n<td>(01-68)<br/></td>\n<td>(69-75)<br/></td>\n<td>(76-98)<br/></td>\n<td>(99-100)<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Positive/Negative Energy Plane<br/></td>\n<td>DC 8/1 week<br/></td>\n<td>01-39<br/></td>\n<td>40-65<br/></td>\n<td>66-86<br/></td>\n<td>87-100<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Astral Plane<br/></td>\n<td>DC 9/1 week<br/></td>\n<td>01-44<br/></td>\n<td>45-67<br/></td>\n<td>68-88<br/></td>\n<td>89-100<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Outer Plane, demideity<br/></td>\n<td>DC 10/2 weeks<br/></td>\n<td>01-49<br/></td>\n<td>50-70<br/></td>\n<td>71-91<br/></td>\n<td>92-100<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Outer Plane, lesser deity<br/></td>\n<td>DC 12/3 weeks<br/></td>\n<td>01-60<br/></td>\n<td>61-75<br/></td>\n<td>76-95<br/></td>\n<td>96-100<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Outer Plane, intermediate deity<br/></td>\n<td>DC 14/4 weeks<br/></td>\n<td>01-73<br/></td>\n<td>74-81<br/></td>\n<td>82-98<br/></td>\n<td>99-100<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Outer Plane, greater deity<br/></td>\n<td>DC 16/5 weeks<br/></td>\n<td>01-88<br/></td>\n<td>89-90<br/></td>\n<td>91-99<br/></td>\n<td>100<br/></td>\n\n</tr>\n</table>\n      <p><i>Avoid Int/Cha Decrease:</i> You must succeed on an Intelligence check against this DC to avoid a decrease in Intelligence and Charisma. If the check fails, your Intelligence and Charisma scores each fall to 8 for the stated duration, and you become unable to cast arcane spells. If you lose Intelligence and Charisma, the effect strikes as soon as the first question is asked, and no answer is received. (The entries in parentheses are for questions that pertain to the appropriate Elemental Plane.)</p>\n      <div topic=\"Results of A Successful Contact\" level=\"8\"><p><b>Results of a Successful Contact:</b> d% is rolled for the result shown on the table:</p><p><i>True Answer:</i> You get a true, one-word answer. Questions that cannot be answered in this way are answered randomly.</p><p><i>Don\'t Know:</i> The entity tells you that it doesn\'t know.</p><p><i>Lie:</i> The entity intentionally lies to you.</p><p><i>Random Answer:</i> The entity tries to lie but doesn\'t know the answer, so it makes one up.</p><p/>\n</div>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Contact Other Plane\" level=\"5\"><p><h5>Contact Other Plane</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration<br/></td></tr></table><p>You send your mind to another plane of existence (an Elemental Plane or some plane farther removed) in order to receive advice and information from powers there. (See the accompanying table for possible consequences and results of the attempt.) The powers reply in a language you understand, but they resent such contact and give only brief answers to your questions. (All questions are answered with \'yes,\' \'no,\' \'maybe,\' \'never,\' \'irrelevant,\' or some other one-word answer.)</p><p>You must concentrate on maintaining the spell (a standard action) in order to ask questions at the rate of one per round. A question is answered by the power during the same round. For every two caster levels, you may ask one question.</p><p>Contact with minds far removed from your home plane increases the probability that you will incur a decrease to Intelligence and Charisma, but the chance of the power knowing the answer, as well as the probability of the entity answering correctly, are likewise increased by moving to distant planes.</p><p>Once the Outer Planes are reached, the power of the deity contacted determines the effects. (Random results obtained from the table are subject to the personalities of individual deities.)</p><p>On rare occasions, this divination may be blocked by an act of certain deities or forces.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td><b>Plane Contacted</b><br/></td>\n<td><b>Avoid Int/Cha Decrease</b><br/></td>\n<td><b>True Answer</b><br/></td>\n<td><b>Don\'t Know</b><br/></td>\n<td><b>Lie</b><br/></td>\n<td><b>Random Answer</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Elemental Plane<br/></td>\n<td>DC 7/1 week<br/></td>\n<td>01-34<br/></td>\n<td>35-62<br/></td>\n<td>63-83<br/></td>\n<td>84-100<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>(appropriate)<br/></td>\n<td>(DC 7/1 week)<br/></td>\n<td>(01-68)<br/></td>\n<td>(69-75)<br/></td>\n<td>(76-98)<br/></td>\n<td>(99-100)<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Positive/Negative Energy Plane<br/></td>\n<td>DC 8/1 week<br/></td>\n<td>01-39<br/></td>\n<td>40-65<br/></td>\n<td>66-86<br/></td>\n<td>87-100<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Astral Plane<br/></td>\n<td>DC 9/1 week<br/></td>\n<td>01-44<br/></td>\n<td>45-67<br/></td>\n<td>68-88<br/></td>\n<td>89-100<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Outer Plane, demideity<br/></td>\n<td>DC 10/2 weeks<br/></td>\n<td>01-49<br/></td>\n<td>50-70<br/></td>\n<td>71-91<br/></td>\n<td>92-100<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Outer Plane, lesser deity<br/></td>\n<td>DC 12/3 weeks<br/></td>\n<td>01-60<br/></td>\n<td>61-75<br/></td>\n<td>76-95<br/></td>\n<td>96-100<br/></td>\n\n</tr>\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Outer Plane, intermediate deity<br/></td>\n<td>DC 14/4 weeks<br/></td>\n<td>01-73<br/></td>\n<td>74-81<br/></td>\n<td>82-98<br/></td>\n<td>99-100<br/></td>\n\n</tr>\n\n<tr maxcol=\"7\" curcol=\"7\">\n<td>Outer Plane, greater deity<br/></td>\n<td>DC 16/5 weeks<br/></td>\n<td>01-88<br/></td>\n<td>89-90<br/></td>\n<td>91-99<br/></td>\n<td>100<br/></td>\n\n</tr>\n</table><p><i>Avoid Int/Cha Decrease:</i> You must succeed on an Intelligence check against this DC to avoid a decrease in Intelligence and Charisma. If the check fails, your Intelligence and Charisma scores each fall to 8 for the stated duration, and you become unable to cast arcane spells. If you lose Intelligence and Charisma, the effect strikes as soon as the first question is asked, and no answer is received. (The entries in parentheses are for questions that pertain to the appropriate Elemental Plane.)</p><div topic=\"Results of A Successful Contact\" level=\"8\"><p><b>Results of a Successful Contact:</b> d% is rolled for the result shown on the table:</p><p><i>True Answer:</i> You get a true, one-word answer. Questions that cannot be answered in this way are answered randomly.</p><p><i>Don\'t Know:</i> The entity tells you that it doesn\'t know.</p><p><i>Lie:</i> The entity intentionally lies to you.</p><p><i>Random Answer:</i> The entity tries to lie but doesn\'t know the answer, so it makes one up.</p><p/>\n</div>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (181,'Contagion','contagion','Necromancy',NULL,'Evil',NULL,'Cleric 3, Destruction 3, Druid 3, Sorcerer/Wizard 4','V, S','1 standard action','Touch','Living creature touched',NULL,NULL,'Instantaneous','Fortitude negates','Yes','Infects subject with chosen disease.',NULL,NULL,NULL,NULL,'\n      <p>The subject contracts a disease selected from the table below, which strikes immediately (no incubation period). The DC noted is for the subsequent saves (use <i>contagion</i>\'s normal save DC for the initial saving throw).</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Disease</b><br/></td> <td><b>DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Blinding sickness<br/></td>\n<td>16<br/></td>\n<td>1d4 Str<sup><b>1</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Cackle fever<br/></td>\n<td>16<br/></td>\n<td>1d6 Wis<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Filth fever<br/></td>\n<td>12<br/></td>\n<td>1d3 Dex and 1d3 Con<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Mindfire<br/></td>\n<td>12<br/></td>\n<td>1d4 Int<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Red ache<br/></td>\n<td>15<br/></td>\n<td>1d6 Str<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Shakes<br/></td>\n<td>13<br/></td>\n<td>1d8 Dex<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Slimy doom<br/></td>\n<td>14<br/></td>\n<td>1d4 Con<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"2\">\n<td colspan=\"3\">1 Each time a victim takes 2 or more points of Strength damage from blinding sickness, he or she must make another Fortitude save (using the disease\'s save DC) or be permanently blinded.<br/></td>\n\n</tr>\n</table>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Contagion\" level=\"5\"><p><h5>Contagion</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Destruction 3, Druid 3, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>The subject contracts a disease selected from the table below, which strikes immediately (no incubation period). The DC noted is for the subsequent saves (use <i>contagion</i>\'s normal save DC for the initial saving throw).</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td><b>Disease</b><br/></td> <td><b>DC</b><br/></td>\n<td><b>Damage</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Blinding sickness<br/></td>\n<td>16<br/></td>\n<td>1d4 Str<sup><b>1</b></sup><br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Cackle fever<br/></td>\n<td>16<br/></td>\n<td>1d6 Wis<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Filth fever<br/></td>\n<td>12<br/></td>\n<td>1d3 Dex and 1d3 Con<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Mindfire<br/></td>\n<td>12<br/></td>\n<td>1d4 Int<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Red ache<br/></td>\n<td>15<br/></td>\n<td>1d6 Str<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Shakes<br/></td>\n<td>13<br/></td>\n<td>1d8 Dex<br/></td>\n\n</tr>\n<tr maxcol=\"4\" curcol=\"4\">\n<td>Slimy doom<br/></td>\n<td>14<br/></td>\n<td>1d4 Con<br/></td>\n\n</tr>\n\n<tr maxcol=\"4\" curcol=\"2\">\n<td colspan=\"3\">1 Each time a victim takes 2 or more points of Strength damage from blinding sickness, he or she must make another Fortitude save (using the disease\'s save DC) or be permanently blinded.<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (182,'Contingency','contingency','Evocation',NULL,NULL,NULL,'Sorcerer/Wizard 6','V, S, M, F','At least 10 minutes; see text','Personal','You',NULL,NULL,'One day/level (D) or until discharged',NULL,NULL,'Sets trigger condition for another spell.',NULL,'That of the companion spell, plus quicksilver and an eyelash of an ogre mage, rakshasa, or similar spell-using creature.',NULL,'A statuette of you carved from elephant ivory and decorated with gems (worth at least 1,500 gp). You must carry the focus for the contingency to work.','\n      <p>You can place another spell upon your person so that it comes into effect under some condition you dictate when casting <i>contingency</i>. The <i>contingency</i> spell and the companion spell are cast at the same time. The 10-minute casting time is the minimum total for both castings; if the companion spell has a casting time longer than 10 minutes, use that instead.</p>\n      <p>The spell to be brought into effect by the <i>contingency</i> must be one that affects your person and be of a spell level no higher than one-third your caster level (rounded down, maximum 6th level).</p>\n      <p>The conditions needed to bring the spell into effect must be clear, although they can be general. In all cases, the <i>contingency</i> immediately brings into effect the companion spell, the latter being \'cast\' instantaneously when the prescribed circumstances occur. If complicated or convoluted conditions are prescribed, the whole spell combination (<i>contingency</i> and the companion magic) may fail when called on. The companion spell occurs based solely on the stated conditions, regardless of whether you want it to.</p>\n      <p>You can use only one <i>contingency</i> spell at a time; if a second is cast, the first one (if still active) is dispelled.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Contingency\" level=\"5\"><p><h5>Contingency</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>At least 10 minutes; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Personal<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>You<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level (D) or until discharged<br/></td></tr></table><p>You can place another spell upon your person so that it comes into effect under some condition you dictate when casting <i>contingency</i>. The <i>contingency</i> spell and the companion spell are cast at the same time. The 10-minute casting time is the minimum total for both castings; if the companion spell has a casting time longer than 10 minutes, use that instead.</p><p>The spell to be brought into effect by the <i>contingency</i> must be one that affects your person and be of a spell level no higher than one-third your caster level (rounded down, maximum 6th level).</p><p>The conditions needed to bring the spell into effect must be clear, although they can be general. In all cases, the <i>contingency</i> immediately brings into effect the companion spell, the latter being \'cast\' instantaneously when the prescribed circumstances occur. If complicated or convoluted conditions are prescribed, the whole spell combination (<i>contingency</i> and the companion magic) may fail when called on. The companion spell occurs based solely on the stated conditions, regardless of whether you want it to.</p><p>You can use only one <i>contingency</i> spell at a time; if a second is cast, the first one (if still active) is dispelled.</p><p><i>Material Component:</i> That of the companion spell, plus quicksilver and an eyelash of an ogre mage, rakshasa, or similar spell-using creature.</p><p><i>Focus:</i> A statuette of you carved from elephant ivory and decorated with gems (worth at least 1,500 gp). You must carry the focus for the <i>contingency</i> to work.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (183,'Continual Flame','continual flame','Evocation',NULL,'Light',NULL,'Cleric 3, Sorcerer/Wizard 2','V, S, M','1 standard action','Touch','Object touched',NULL,'Magical, heatless flame','Permanent','None','No','Makes a permanent, heatless torch.',NULL,'You sprinkle ruby dust (worth 50 gp) on the item that is to carry the flame.',NULL,NULL,'\n      <p>A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn\'t use oxygen. A <i>continual flame</i> can be covered and hidden but not smothered or quenched.</p>\n      <p>Light spells counter and dispel darkness spells of an equal or lower level.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Continual Flame\" level=\"5\"><p><h5>Continual Flame</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Light]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Object touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Magical, heatless flame<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Permanent<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>A flame, equivalent in brightness to a torch, springs forth from an object that you touch. The effect looks like a regular flame, but it creates no heat and doesn\'t use oxygen. A <i>continual flame</i> can be covered and hidden but not smothered or quenched.</p><p>Light spells counter and dispel darkness spells of an equal or lower level.</p><p><i>Material Component:</i> You sprinkle ruby dust (worth 50 gp) on the item that is to carry the flame.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (184,'Control Plants','control plants','Transmutation',NULL,NULL,NULL,'Druid 8, Plant 8','V, S, DF','1 standard action','Close (25 ft. + 5 ft./2 levels)','Up to 2 HD/level of plant creatures, no two of which can be more than 30 ft. apart',NULL,NULL,'1 min./level','Will negates','No','Control actions of one or more plant creatures.',NULL,NULL,NULL,NULL,'\n      <p>This spell enables you to control the actions of one or more plant creatures for a short period of time. You command the creatures by voice and they understand you, no matter what language you speak. Even if vocal communication is impossible  the controlled plants do not attack you. At the end of the spell, the subjects revert to their normal behavior.</p>\n      <p>Suicidal or self-destructive commands are simply ignored.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Control Plants\" level=\"5\"><p><h5>Control Plants</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 8, Plant 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to 2 HD/level of plant creatures, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell enables you to control the actions of one or more plant creatures for a short period of time. You command the creatures by voice and they understand you, no matter what language you speak. Even if vocal communication is impossible  the controlled plants do not attack you. At the end of the spell, the subjects revert to their normal behavior.</p><p>Suicidal or self-destructive commands are simply ignored.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (185,'Control Undead','control undead','Necromancy',NULL,NULL,NULL,'Sorcerer/Wizard 7','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)','Up to 2 HD/level of undead creatures, no two of which can be more than 30 ft. apart',NULL,NULL,'1 min./level','Will negates','Yes','Undead don\'t attack you while under your command.',NULL,'A small piece of bone and a small piece of raw meat.',NULL,NULL,'\n      <p>This spell enables you to command undead creatures for a short period of time. You command them by voice and they understand you, no matter what language you speak. Even if vocal communication is impossible the controlled undead do not attack you. At the end of the spell, the subjects revert to their normal behavior.</p>\n      <p>Intelligent undead creatures remember that you controlled them.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Control Undead\" level=\"5\"><p><h5>Control Undead</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Targets:</b><br/></td><td>Up to 2 HD/level of undead creatures, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell enables you to command undead creatures for a short period of time. You command them by voice and they understand you, no matter what language you speak. Even if vocal communication is impossible the controlled undead do not attack you. At the end of the spell, the subjects revert to their normal behavior.</p><p>Intelligent undead creatures remember that you controlled them.</p><p><i>Material Component:</i> A small piece of bone and a small piece of raw meat.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (186,'Control Water','control water','Transmutation',NULL,'Water',NULL,'Cleric 4, Druid 4, Sorcerer/Wizard 6, Water 4','V, S, M/DF','1 standard action','Long (400 ft. + 40 ft./level)',NULL,'Water in a volume of 10 ft./level by 10 ft./level by 2 ft./level (S)',NULL,'10 min./level (D)','None; see text','No','Raises or lowers bodies of water.',NULL,NULL,'A drop of water (for raise water) or a pinch of dust (for lower water).',NULL,'\n      <p>Depending on the version you choose, the <i>control water</i> spell raises or lowers water.</p>\n      <p><i>Lower Water:</i> This causes water or similar liquid to reduce its depth by as much as 2 feet per caster level (to a minimum depth of 1 inch). The water is lowered within a squarish depression whose sides are up to caster level x 10 feet long. In extremely large and deep bodies of water, such as a deep ocean, the spell creates a whirlpool that sweeps ships and similar craft downward, putting them at risk and rendering them unable to leave by normal movement for the duration of the spell. When cast on water elementals and other water-based creatures, this spell acts as a <i>slow</i> spell (Will negates). The spell has no effect on other creatures.</p>\n      <p><i>Raise Water:</i> This causes water or similar liquid to rise in height, just as the <i>lower water</i> version causes it to lower. Boats raised in this way slide down the sides of the hump that the spell creates. If the area affected by the spell includes riverbanks, a beach, or other land nearby, the water can spill over onto dry land.</p>\n      <p>With either version, you may reduce one horizontal dimension by half and double the other horizontal dimension.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Control Water\" level=\"5\"><p><h5>Control Water</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Water]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 4, Druid 4, Sorcerer/Wizard 6, Water 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Water in a volume of 10 ft./level by 10 ft./level by 2 ft./level (S)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>Depending on the version you choose, the <i>control water</i> spell raises or lowers water.</p><p><i>Lower Water:</i> This causes water or similar liquid to reduce its depth by as much as 2 feet per caster level (to a minimum depth of 1 inch). The water is lowered within a squarish depression whose sides are up to caster level x 10 feet long. In extremely large and deep bodies of water, such as a deep ocean, the spell creates a whirlpool that sweeps ships and similar craft downward, putting them at risk and rendering them unable to leave by normal movement for the duration of the spell. When cast on water elementals and other water-based creatures, this spell acts as a <i>slow</i> spell (Will negates). The spell has no effect on other creatures.</p><p><i>Raise Water:</i> This causes water or similar liquid to rise in height, just as the <i>lower water</i> version causes it to lower. Boats raised in this way slide down the sides of the hump that the spell creates. If the area affected by the spell includes riverbanks, a beach, or other land nearby, the water can spill over onto dry land.</p><p>With either version, you may reduce one horizontal dimension by half and double the other horizontal dimension.</p><p><i>Arcane Material Component:</i> A drop of water (for <i>raise water</i>) or a pinch of dust (for <i>lower water</i>).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (187,'Control Weather','control weather','Transmutation',NULL,NULL,NULL,'Air 7, Cleric 7, Druid 7, Sorcerer/Wizard 7','V, S','10 minutes; see text','2 miles',NULL,'2-mile-radius circle, centered on you; see text',NULL,'4d12 hours; see text','None','No','Changes weather in local area.',NULL,NULL,NULL,NULL,'\n      <p>You change the weather in the local area. It takes 10 minutes to cast the spell and an additional 10 minutes for the effects to manifest. You can call forth weather appropriate to the climate and season of the area you are in.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Season</b><br/></td> <td><b>Possible Weather</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Spring<br/></td>\n<td>Tornado, thunderstorm, sleet storm, or hot weather<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Summer<br/></td>\n<td>Torrential rain, heat wave, or hailstorm<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Autumn<br/></td>\n<td>Hot or cold weather, fog, or sleet<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Winter<br/></td>\n<td>Frigid cold, blizzard, or thaw<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Late winter<br/></td>\n<td>Hurricane-force winds or early spring (coastal area)<br/></td>\n\n</tr>\n</table>\n      <p>You control the general tendencies of the weather, such as the direction and intensity of the wind. You cannot control specific applications of the weather-where lightning strikes, for example, or the exact path of a tornado. When you select a certain weather condition to occur, the weather assumes that condition 10 minutes later (changing gradually, not abruptly). The weather continues as you left it for the duration, or until you use a standard action to designate a new kind of weather (which fully manifests itself 10 minutes later). Contradictory conditions are not possible simultaneously.</p>\n      <p><i>Control weather</i> can do away with atmospheric phenomena (naturally occurring or otherwise) as well as create them.</p>\n      <p>A druid casting this spell doubles the duration and affects a circle with a 3-mile radius.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Control Weather\" level=\"5\"><p><h5>Control Weather</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Air 7, Cleric 7, Druid 7, Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>2 miles<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>2-mile-radius circle, centered on you; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>4d12 hours; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You change the weather in the local area. It takes 10 minutes to cast the spell and an additional 10 minutes for the effects to manifest. You can call forth weather appropriate to the climate and season of the area you are in.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Season</b><br/></td> <td><b>Possible Weather</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Spring<br/></td>\n<td>Tornado, thunderstorm, sleet storm, or hot weather<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Summer<br/></td>\n<td>Torrential rain, heat wave, or hailstorm<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Autumn<br/></td>\n<td>Hot or cold weather, fog, or sleet<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Winter<br/></td>\n<td>Frigid cold, blizzard, or thaw<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Late winter<br/></td>\n<td>Hurricane-force winds or early spring (coastal area)<br/></td>\n\n</tr>\n</table><p>You control the general tendencies of the weather, such as the direction and intensity of the wind. You cannot control specific applications of the weather-where lightning strikes, for example, or the exact path of a tornado. When you select a certain weather condition to occur, the weather assumes that condition 10 minutes later (changing gradually, not abruptly). The weather continues as you left it for the duration, or until you use a standard action to designate a new kind of weather (which fully manifests itself 10 minutes later). Contradictory conditions are not possible simultaneously.</p><p><i>Control weather</i> can do away with atmospheric phenomena (naturally occurring or otherwise) as well as create them.</p><p>A druid casting this spell doubles the duration and affects a circle with a 3-mile radius.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (188,'Control Winds','control winds','Transmutation',NULL,'Air',NULL,'Air 5, Druid 5','V, S','1 standard action','40 ft./level',NULL,'40 ft./level radius cylinder 40 ft. high',NULL,'10 min./level','Fortitude negates','No','Change wind direction and speed.',NULL,NULL,NULL,NULL,'\n      <p>You alter wind force in the area surrounding you. You can make the wind blow in a certain direction or manner, increase its strength, or decrease its strength. The new wind direction and strength persist until the spell ends or until you choose to alter your handiwork, which requires concentration. You may create an \'eye\' of calm air up to 80 feet in diameter at the center of the area if you so desire, and you may choose to limit the area to any cylindrical area less than your full limit.</p>\n      <p><i>Wind Direction:</i> You may choose one of four basic wind patterns to function over the spell\'s area.</p>\n      <ul>\n <li> A downdraft blows from the center outward in equal strength in all directions.</li>\n <li> An updraft blows from the outer edges in toward the center in equal strength from all directions, veering upward before impinging on the eye in the center.</li>\n <li> A rotation causes the winds to circle the center in clockwise or counterclockwise fashion.</li>\n <li> A blast simply causes the winds to blow in one direction across the entire area from one side to the other.</li>\n</ul>\n      <p><i>Wind Strength:</i> For every three caster levels, you can increase or decrease wind strength by one level. Each round on your turn, a creature in the wind must make a Fortitude save or suffer the effect of being in the windy area.</p>\n      <p>Strong winds (21+ mph) make sailing difficult.</p>\n      <p>A severe wind (31+ mph) causes minor ship and building damage.</p>\n      <p>A windstorm (51+ mph) drives most flying creatures from the skies, uproots small trees, knocks down light wooden structures, tears off roofs, and endangers ships.</p>\n      <p>Hurricane force winds (75+ mph) destroy wooden buildings, sometimes uproot even large trees, and cause most ships to founder.</p>\n      <p>A tornado (175+ mph) destroys all nonfortified buildings and often uproots large trees.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Control Winds\" level=\"5\"><p><h5>Control Winds</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation [Air]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Air 5, Druid 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>40 ft./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>40 ft./level radius cylinder 40 ft. high<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You alter wind force in the area surrounding you. You can make the wind blow in a certain direction or manner, increase its strength, or decrease its strength. The new wind direction and strength persist until the spell ends or until you choose to alter your handiwork, which requires concentration. You may create an \'eye\' of calm air up to 80 feet in diameter at the center of the area if you so desire, and you may choose to limit the area to any cylindrical area less than your full limit.</p><p><i>Wind Direction:</i> You may choose one of four basic wind patterns to function over the spell\'s area.</p><ul>\n <li> A downdraft blows from the center outward in equal strength in all directions.</li>\n <li> An updraft blows from the outer edges in toward the center in equal strength from all directions, veering upward before impinging on the eye in the center.</li>\n <li> A rotation causes the winds to circle the center in clockwise or counterclockwise fashion.</li>\n <li> A blast simply causes the winds to blow in one direction across the entire area from one side to the other.</li>\n</ul><p><i>Wind Strength:</i> For every three caster levels, you can increase or decrease wind strength by one level. Each round on your turn, a creature in the wind must make a Fortitude save or suffer the effect of being in the windy area.</p><p>Strong winds (21+ mph) make sailing difficult.</p><p>A severe wind (31+ mph) causes minor ship and building damage.</p><p>A windstorm (51+ mph) drives most flying creatures from the skies, uproots small trees, knocks down light wooden structures, tears off roofs, and endangers ships.</p><p>Hurricane force winds (75+ mph) destroy wooden buildings, sometimes uproot even large trees, and cause most ships to founder.</p><p>A tornado (175+ mph) destroys all nonfortified buildings and often uproots large trees.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (189,'Corrupt Weapon','corrupt weapon','Transmutation',NULL,NULL,NULL,'Blackguard 1','V, S','1 standard action','Touch','Weapon touched',NULL,NULL,'1 min./level','None','No',NULL,NULL,NULL,NULL,NULL,'\n      <p>This transmutation makes a weapon strike true against good foes. The weapon is treated as having a +1 enhancement bonus for the purpose of bypassing the damage reduction of good creatures or striking good incorporeal creatures (though the spell doesn\'t grant an actual enhancement bonus). The weapon also becomes good, which means it can bypass the damage reduction of certain creatures. (This effect overrides and suppresses any other alignment the weapon might have.) Individual arrows or bolts can be transmuted, but affected projectile weapons (such as bows) don\'t confer the benefit to the projectiles they shoot.</p>\n      <p>In addition, all critical hit rolls against good foes are automatically successful, so every threat is a critical hit. This last effect does not apply to any weapon that already has a magical effect related to critical hits, such as a keen weapon or a vorpal sword.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Corrupt Weapon\" level=\"5\"><p><h5>Corrupt Weapon</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Blackguard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Weapon touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This transmutation makes a weapon strike true against good foes. The weapon is treated as having a +1 enhancement bonus for the purpose of bypassing the damage reduction of good creatures or striking good incorporeal creatures (though the spell doesn\'t grant an actual enhancement bonus). The weapon also becomes good, which means it can bypass the damage reduction of certain creatures. (This effect overrides and suppresses any other alignment the weapon might have.) Individual arrows or bolts can be transmuted, but affected projectile weapons (such as bows) don\'t confer the benefit to the projectiles they shoot.</p><p>In addition, all critical hit rolls against good foes are automatically successful, so every threat is a critical hit. This last effect does not apply to any weapon that already has a magical effect related to critical hits, such as a keen weapon or a vorpal sword.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (190,'Create Food and Water','create food and water','Conjuration','Creation',NULL,NULL,'Cleric 3','V, S','10 minutes','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'Food and water to sustain three humans or one horse/level for 24 hours','24 hours; see text','None','No','Feeds three humans (or one horse)/level.',NULL,NULL,NULL,NULL,'\n      <p>The food that this spell creates is simple fare of your choice-highly nourishing, if rather bland. Food so created decays and becomes inedible within 24 hours, although it can be kept fresh for another 24 hours by casting a <i>purify food and water</i> spell on it. The water created by this spell is just like clean rain water, and it doesn\'t go bad as the food does.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Create Food and Water\" level=\"5\"><p><h5>Create Food and Water</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>10 minutes<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Food and water to sustain three humans or one horse/level for 24 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>24 hours; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>The food that this spell creates is simple fare of your choice-highly nourishing, if rather bland. Food so created decays and becomes inedible within 24 hours, although it can be kept fresh for another 24 hours by casting a <i>purify food and water</i> spell on it. The water created by this spell is just like clean rain water, and it doesn\'t go bad as the food does.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (191,'Create Greater Undead','create greater undead','Necromancy',NULL,'Evil',NULL,'Cleric 8, Death 8, Sorcerer/Wizard 8','V, S, M','1 hour','Close (25 ft. + 5 ft./2 levels)','One corpse',NULL,NULL,'Instantaneous','None','No','Create shadows, wraiths, spectres, or devourers.',NULL,'A clay pot filled with grave dirt and another filled with brackish water. The spell must be cast on a dead body. You must place a black onyx gem worth at least 50 gp per HD of the undead to be created into the mouth or eye socket of each corpse. The magic of the spell turns these gems into worthless shells.',NULL,NULL,'\n      <p>This spell functions like create undead, except that you can create more powerful and intelligent sorts of undead: shadows, wraiths, spectres, and devourers. The type or types of undead you can create is based on your caster level, as shown on the table below.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Caster Level</b><br/></td>\n<td><b>Undead Created</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15th or lower<br/></td>\n<td>Shadow<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>16th-17th<br/></td>\n<td>Wraith<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18th-19th<br/></td>\n<td>Spectre<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20th or higher<br/></td>\n<td>Devourer<br/></td>\n\n</tr>\n</table>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Create Greater Undead\" level=\"5\"><p><h5>Create Greater Undead</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 8, Death 8, Sorcerer/Wizard 8<br/></td></tr></table><p>This spell functions like create undead, except that you can create more powerful and intelligent sorts of undead: shadows, wraiths, spectres, and devourers. The type or types of undead you can create is based on your caster level, as shown on the table below.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Caster Level</b><br/></td>\n<td><b>Undead Created</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15th or lower<br/></td>\n<td>Shadow<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>16th-17th<br/></td>\n<td>Wraith<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18th-19th<br/></td>\n<td>Spectre<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>20th or higher<br/></td>\n<td>Devourer<br/></td>\n\n</tr>\n</table><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (192,'Create Undead','create undead','Necromancy',NULL,'Evil',NULL,'Cleric 6, Death 6, Evil 6, Sorcerer/Wizard 6','V, S, M','1 hour','Close (25 ft. + 5 ft./2 levels)','One corpse',NULL,NULL,'Instantaneous','None','No','Creates ghouls, ghasts, mummies, or mohrgs.',NULL,'A clay pot filled with grave dirt and another filled with brackish water. The spell must be cast on a dead body. You must place a black onyx gem worth at least 50 gp per HD of the undead to be created into the mouth or eye socket of each corpse. The magic of the spell turns these gems into worthless shells.',NULL,NULL,'\n      <p>A much more potent spell than <i>animate dead</i>,  this evil spell allows you to create more powerful sorts of undead: ghouls, ghasts, mummies, and mohrgs. The type or types of undead you can create is based on your caster level, as shown on the table below.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Caster Level</b><br/></td> <td><b>Undead Created</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>11th or lower<br/></td>\n<td>Ghoul<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12th-14th<br/></td>\n<td>Ghast<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15th-17th<br/></td>\n<td>Mummy<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18th or higher<br/></td>\n<td>Mohrg<br/></td>\n\n</tr>\n</table>\n      <p>You may create less powerful undead than your level would allow if you choose. Created undead are not automatically under the control of their animator. If you are capable of commanding undead, you may attempt to command the undead creature as it forms.</p>\n      <p>This spell must be cast at night.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Create Undead\" level=\"5\"><p><h5>Create Undead</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 6, Death 6, Evil 6, Sorcerer/Wizard 6<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 hour<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One corpse<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>A much more potent spell than <i>animate dead</i>,  this evil spell allows you to create more powerful sorts of undead: ghouls, ghasts, mummies, and mohrgs. The type or types of undead you can create is based on your caster level, as shown on the table below.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Caster Level</b><br/></td> <td><b>Undead Created</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>11th or lower<br/></td>\n<td>Ghoul<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>12th-14th<br/></td>\n<td>Ghast<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>15th-17th<br/></td>\n<td>Mummy<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>18th or higher<br/></td>\n<td>Mohrg<br/></td>\n\n</tr>\n</table><p>You may create less powerful undead than your level would allow if you choose. Created undead are not automatically under the control of their animator. If you are capable of commanding undead, you may attempt to command the undead creature as it forms.</p><p>This spell must be cast at night.</p><p><i>Material Component:</i> A clay pot filled with grave dirt and another filled with brackish water. The spell must be cast on a dead body. You must place a black onyx gem worth at least 50 gp per HD of the undead to be created into the mouth or eye socket of each corpse. The magic of the spell turns these gems into worthless shells.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (193,'Create Water','create water','Conjuration','Creation','Water',NULL,'Cleric 0, Druid 0, Paladin 1','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,NULL,'Up to 2 gallons of water/level','Instantaneous','None','No','Creates 2 gallons/level of pure water.',NULL,NULL,NULL,NULL,'\n      <p>This spell generates wholesome, drinkable water, just like clean rain water. Water can be created in an area as small as will actually contain the liquid, or in an area three times as large-possibly creating a downpour or filling many small receptacles.</p>\n      <p><i>Note:</i> Conjuration spells can\'t create substances or objects within a creature. Water weighs about 8 pounds per gallon. One cubic foot of water contains roughly 8 gallons and weighs about 60 pounds.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Create Water\" level=\"5\"><p><h5>Create Water</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Creation) [Water]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 0, Druid 0, Paladin 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Up to 2 gallons of water/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell generates wholesome, drinkable water, just like clean rain water. Water can be created in an area as small as will actually contain the liquid, or in an area three times as large-possibly creating a downpour or filling many small receptacles.</p><p><i>Note:</i> Conjuration spells can\'t create substances or objects within a creature. Water weighs about 8 pounds per gallon. One cubic foot of water contains roughly 8 gallons and weighs about 60 pounds.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (194,'Creeping Doom','creeping doom','Conjuration','Summoning',NULL,NULL,'Druid 7','V, S','1 round','Close (25 ft. + 5 ft./2 levels)/100 ft.; see text',NULL,NULL,'One swarm of centipedes per two levels','1 min./level','None','No','Swarms of centipedes attack at your command.',NULL,NULL,NULL,NULL,'\n      <p>When you utter the spell of <i>creeping doom</i>,  you call forth a mass of centipede swarms (one per two caster levels, to a maximum of ten swarms at 20th level), which need not appear adjacent to one another.</p>\n      <p>You may summon the centipede swarms so that they share the area of other creatures. The swarms remain stationary, attacking any creatures in their area, unless you command the creeping doom to move (a standard action). As a standard action, you can command any number of the swarms to move toward any prey within 100 feet of you. You cannot command any swarm to move more than 100 feet away from you, and if you move more than 100 feet from any swarm, that swarm remains stationary, attacking any creatures in its area (but it can be commanded again if you move within 100 feet).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Creeping Doom\" level=\"5\"><p><h5>Creeping Doom</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Summoning)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)/100 ft.; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>One swarm of centipedes per two levels<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>When you utter the spell of <i>creeping doom</i>,  you call forth a mass of centipede swarms (one per two caster levels, to a maximum of ten swarms at 20th level), which need not appear adjacent to one another.</p><p>You may summon the centipede swarms so that they share the area of other creatures. The swarms remain stationary, attacking any creatures in their area, unless you command the creeping doom to move (a standard action). As a standard action, you can command any number of the swarms to move toward any prey within 100 feet of you. You cannot command any swarm to move more than 100 feet away from you, and if you move more than 100 feet from any swarm, that swarm remains stationary, attacking any creatures in its area (but it can be commanded again if you move within 100 feet).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (195,'Crushing Despair','crushing despair','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 3, Sorcerer/Wizard 4','V, S, M','1 standard action','30 ft.',NULL,'Cone-shaped burst',NULL,'1 min./level','Will negates','Yes','Subjects take -2 on attack rolls, damage rolls, saves, and checks.',NULL,'A vial of tears.',NULL,NULL,'\n      <p>An invisible cone of despair causes great sadness in the subjects. Each affected creature takes a -2 penalty on attack rolls, saving throws, ability checks, skill checks, and weapon damage rolls.</p>\n      <p><i>Crushing despair</i> counters and dispels <i>good hope</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Crushing Despair\" level=\"5\"><p><h5>Crushing Despair</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>30 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped burst<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>An invisible cone of despair causes great sadness in the subjects. Each affected creature takes a -2 penalty on attack rolls, saving throws, ability checks, skill checks, and weapon damage rolls.</p><p><i>Crushing despair</i> counters and dispels <i>good hope</i>.</p><p><i>Material Component:</i> A vial of tears.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (196,'Crushing Hand','crushing hand','Evocation',NULL,'Force',NULL,'Sorcerer/Wizard 9, Strength 9','V, S, M, F/DF','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'10-ft. hand','1 round/level (D)','None','Yes','Large hand provides cover, pushes, or crushes your foes.',NULL,NULL,'The shell of an egg.','A soft glove.','\n      <p>This spell functions like <i>interposing hand</i>,  except that the hand can interpose itself, push, or crush one opponent that you select.</p>\n      <p>The <i>crushing hand</i> can grapple an opponent like <i>grasping hand</i> does. Its grapple bonus equals your caster level + your Intelligence, Wisdom, or Charisma modifier (for a wizard, cleric, or sorcerer, respectively), +12 for the hand\'s Strength score (35), +4 for being Large. The hand deals 2d6+12 points of damage (lethal, not nonlethal) on each successful grapple check against an opponent.</p>\n      <p>The <i>crushing hand</i> can also interpose itself as <i>interposing hand</i> does, or it can bull rush an opponent as <i>forceful hand</i> does, but at a +18 bonus.</p>\n      <p>Directing the spell to a new target is a move action.</p>\n      <p>Clerics who cast this spell name it for their deities.</p>\n      <p/>\n    ',NULL,'A glove of snakeskin.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Crushing Hand\" level=\"5\"><p><h5>Crushing Hand</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Force]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 9, Strength 9<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, F/DF<br/></td></tr></table><p>This spell functions like <i>interposing hand</i>,  except that the hand can interpose itself, push, or crush one opponent that you select.</p><p>The <i>crushing hand</i> can grapple an opponent like <i>grasping hand</i> does. Its grapple bonus equals your caster level + your Intelligence, Wisdom, or Charisma modifier (for a wizard, cleric, or sorcerer, respectively), +12 for the hand\'s Strength score (35), +4 for being Large. The hand deals 2d6+12 points of damage (lethal, not nonlethal) on each successful grapple check against an opponent.</p><p>The <i>crushing hand</i> can also interpose itself as <i>interposing hand</i> does, or it can bull rush an opponent as <i>forceful hand</i> does, but at a +18 bonus.</p><p>Directing the spell to a new target is a move action.</p><p>Clerics who cast this spell name it for their deities.</p><p><i>Arcane Material Component:</i> The shell of an egg.</p><p><i>Arcane Focus:</i> A glove of snakeskin.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (197,'Cure Critical Wounds','cure critical wounds','Conjuration','Healing',NULL,NULL,'Bard 4, Cleric 4, Druid 5, Healing 4','V, S','1 standard action','Touch','Creature touched',NULL,NULL,'Instantaneous','Will half (harmless); see text','Yes (harmless); see text','Cures 4d8 damage +1/level (max +20).',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>cure light wounds</i>, except that it cures 4d8 points of damage +1 point per caster level (maximum +20).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cure Critical Wounds\" level=\"5\"><p><h5>Cure Critical Wounds</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4, Cleric 4, Druid 5, Healing 4<br/></td></tr></table><p>This spell functions like <i>cure light wounds</i>, except that it cures 4d8 points of damage +1 point per caster level (maximum +20).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (198,'Cure Critical Wounds, Mass','mass cure critical wounds','Conjuration','Healing',NULL,NULL,'Cleric 8, Druid 9, Healing 8','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'Instantaneous','Will half (harmless) or Will half; see text','Yes (harmless) or Yes; see text','Cures 4d8 damage +1/level for many creatures.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>mass cure light wounds</i>, except that it cures 4d8 points of damage +1 point per caster level (maximum +40).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cure Critical Wounds, Mass\" level=\"5\"><p><h5>Cure Critical Wounds, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 8, Druid 9, Healing 8<br/></td></tr></table><p>This spell functions like <i>mass cure light wounds</i>, except that it cures 4d8 points of damage +1 point per caster level (maximum +40).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (199,'Cure Light Wounds','cure light wounds','Conjuration','Healing',NULL,NULL,'Bard 1, Cleric 1, Druid 1, Healing 1, Paladin 1, Ranger 2','V, S','1 standard action','Touch','Creature touched',NULL,NULL,'Instantaneous','Will half (harmless); see text','Yes (harmless); see text','Cures 1d8 damage +1/level (max +5).',NULL,NULL,NULL,NULL,'\n      <p>When laying your hand upon a living creature, you channel positive energy that cures 1d8 points of damage +1 point per caster level (maximum +5).</p>\n      <p>Since undead are powered by negative energy, this spell deals damage to them instead of curing their wounds. An undead creature can apply spell resistance, and can attempt a Will save to take half damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cure Light Wounds\" level=\"5\"><p><h5>Cure Light Wounds</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Cleric 1, Druid 1, Healing 1, Paladin 1, Ranger 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will half (harmless); see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless); see text<br/></td></tr></table><p>When laying your hand upon a living creature, you channel positive energy that cures 1d8 points of damage +1 point per caster level (maximum +5).</p><p>Since undead are powered by negative energy, this spell deals damage to them instead of curing their wounds. An undead creature can apply spell resistance, and can attempt a Will save to take half damage.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (200,'Cure Light Wounds, Mass','mass cure light wounds','Conjuration','Healing',NULL,NULL,'Bard 5, Cleric 5, Druid 6, Healing 5','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'Instantaneous','Will half (harmless) or Will half; see text','Yes (harmless) or Yes; see text','Cures 1d8 damage +1/level for many creatures.',NULL,NULL,NULL,NULL,'\n      <p>You channel positive energy to cure 1d8 points of damage +1 point per caster level (maximum +25) in each selected creature.</p>\n      <p>Like other <i>cure</i> spells, <i>mass cure light wounds</i> deals damage to undead in its area rather than curing them. Each affected undead may attempt a Will save for half damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cure Light Wounds, Mass\" level=\"5\"><p><h5>Cure Light Wounds, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 5, Cleric 5, Druid 6, Healing 5<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature/level, no two of which can be more than 30 ft. apart<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will half (harmless) or Will half; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless) or Yes; see text<br/></td></tr></table><p>You channel positive energy to cure 1d8 points of damage +1 point per caster level (maximum +25) in each selected creature.</p><p>Like other <i>cure</i> spells, <i>mass cure light wounds</i> deals damage to undead in its area rather than curing them. Each affected undead may attempt a Will save for half damage.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (201,'Cure Minor Wounds','cure minor wounds','Conjuration','Healing',NULL,NULL,'Cleric 0, Druid 0','V, S','1 standard action','Touch','Creature touched',NULL,NULL,'Instantaneous','Will half (harmless); see text','Yes (harmless); see text','Cures 1 point of damage.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>cure light wounds</i>, except that it cures only 1 point of damage.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cure Minor Wounds\" level=\"5\"><p><h5>Cure Minor Wounds</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 0, Druid 0<br/></td></tr></table><p>This spell functions like <i>cure light wounds</i>, except that it cures only 1 point of damage.</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (202,'Cure Moderate Wounds','cure moderate wounds','Conjuration','Healing',NULL,NULL,'Bard 2, Cleric 2, Druid 3, Healing 2, Paladin 3, Ranger 3','V, S','1 standard action','Touch','Creature touched',NULL,NULL,'Instantaneous','Will half (harmless); see text','Yes (harmless); see text','Cures 2d8 damage +1/level (max +10).',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>cure light wounds</i>, except that it cures 2d8 points of damage +1 point per caster level (maximum +10).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cure Moderate Wounds\" level=\"5\"><p><h5>Cure Moderate Wounds</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Cleric 2, Druid 3, Healing 2, Paladin 3, Ranger 3<br/></td></tr></table><p>This spell functions like <i>cure light wounds</i>, except that it cures 2d8 points of damage +1 point per caster level (maximum +10).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (203,'Cure Moderate Wounds, Mass','mass cure moderate wounds','Conjuration','Healing',NULL,NULL,'Bard 6, Cleric 6, Druid 7','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'Instantaneous','Will half (harmless) or Will half; see text','Yes (harmless) or Yes; see text','Cures 2d8 damage +1/level for many creatures.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>mass cure light wounds</i>, except that it cures 2d8 points of damage +1 point per caster level (maximum +30).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cure Moderate Wounds, Mass\" level=\"5\"><p><h5>Cure Moderate Wounds, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 6, Cleric 6, Druid 7<br/></td></tr></table><p>This spell functions like <i>mass cure light wounds</i>, except that it cures 2d8 points of damage +1 point per caster level (maximum +30).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (204,'Cure Serious Wounds','cure serious wounds','Conjuration','Healing',NULL,NULL,'Bard 3, Cleric 3, Druid 4, Paladin 4, Ranger 4, Healing 3','V, S','1 standard action','Touch','Creature touched',NULL,NULL,'Instantaneous','Will half (harmless); see text','Yes (harmless); see text','Cures 3d8 damage +1/level (max +15).',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>cure light wounds</i>, except that it cures 3d8 points of damage +1 point per caster level (maximum +15).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cure Serious Wounds\" level=\"5\"><p><h5>Cure Serious Wounds</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Cleric 3, Druid 4, Paladin 4, Ranger 4, Healing 3<br/></td></tr></table><p>This spell functions like <i>cure light wounds</i>, except that it cures 3d8 points of damage +1 point per caster level (maximum +15).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (205,'Cure Serious Wounds, Mass','mass cure serious wounds','Conjuration','Healing',NULL,NULL,'Cleric 7, Druid 8','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature/level, no two of which can be more than 30 ft. apart',NULL,NULL,'Instantaneous','Will half (harmless) or Will half; see text','Yes (harmless) or Yes; see text','Cures 3d8 damage +1/level for many creatures.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>mass cure light wounds</i>, except that it cures 3d8 points of damage +1 point per caster level (maximum +35).</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Cure Serious Wounds, Mass\" level=\"5\"><p><h5>Cure Serious Wounds, Mass</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7, Druid 8<br/></td></tr></table><p>This spell functions like <i>mass cure light wounds</i>, except that it cures 3d8 points of damage +1 point per caster level (maximum +35).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (206,'Curse Water','curse water','Necromancy',NULL,'Evil',NULL,'Cleric 1','V, S, M','1 minute','Touch','Flask of water touched',NULL,NULL,'Instantaneous','Will negates (object)','Yes (object)','Makes unholy water.',NULL,'5 pounds of powdered silver (worth 25 gp).',NULL,NULL,'\n      <p>This spell imbues a flask (1 pint) of water with negative energy, turning it into unholy water. Unholy water damages good outsiders the way holy water damages undead and evil outsiders.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Curse Water\" level=\"5\"><p><h5>Curse Water</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 minute<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Flask of water touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (object)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (object)<br/></td></tr></table><p>This spell imbues a flask (1 pint) of water with negative energy, turning it into unholy water. Unholy water damages good outsiders the way holy water damages undead and evil outsiders.</p><p><i>Material Component:</i> 5 pounds of powdered silver (worth 25 gp).</p><p/>\n</div>\n    ','SRD 3.5 SpellsC');
INSERT INTO spell VALUES (207,'Dancing Lights','dancing lights','Evocation',NULL,'Light',NULL,'Bard 0, Sorcerer/Wizard 0','V, S','1 standard action','Medium (100 ft. + 10 ft./level)',NULL,NULL,'Up to four lights, all within a 10- ft. -radius area','1 minute (D)','None','No','Creates torches or other lights.',NULL,NULL,NULL,NULL,'\n      <p>Depending on the version selected, you create up to four lights that resemble lanterns or torches (and cast that amount of light), or up to four glowing spheres of light (which look like will-o\'-wisps), or one faintly glowing, vaguely humanoid shape. The <i>Dancing lights</i> must stay within a 10-foot-radius area in relation to each other but otherwise move as you desire (no concentration required): forward or back, up or down, straight or turning corners, or the like. The lights can move up to 100 feet per round. A light winks out if the distance between you and it exceeds the spell\'s range.</p>\n      <p><i>Dancing lights</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Dancing Lights\" level=\"5\"><p><h5>Dancing Lights</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Light]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 0, Sorcerer/Wizard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Effect:</b><br/></td><td>Up to four lights, all within a 10- ft. -radius area<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 minute (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>Depending on the version selected, you create up to four lights that resemble lanterns or torches (and cast that amount of light), or up to four glowing spheres of light (which look like will-o\'-wisps), or one faintly glowing, vaguely humanoid shape. The <i>Dancing lights</i> must stay within a 10-foot-radius area in relation to each other but otherwise move as you desire (no concentration required): forward or back, up or down, straight or turning corners, or the like. The lights can move up to 100 feet per round. A light winks out if the distance between you and it exceeds the spell\'s range.</p><p><i>Dancing lights</i> can be made permanent with a <i>permanency</i> spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (208,'Darkness','darkness','Evocation',NULL,'Darkness',NULL,'Bard 2, Cleric 2, Sorcerer/Wizard 2','V, M/DF','1 standard action','Touch','Object touched',NULL,NULL,'10 min./level (D)','None','No','20-ft. radius of supernatural shadow.',NULL,NULL,'A bit of bat fur and either a drop of pitch or a piece of coal.',NULL,'\n      <p>This spell causes an object to radiate shadowy illumination out to a 20-foot radius. All creatures in the area gain concealment (20% miss chance). Even creatures that can normally see in such conditions (such as with darkvision or low-light vision) have the miss chance in an area shrouded in magical <i>darkness</i>.</p>\n      <p>Normal lights (torches, candles, lanterns, and so forth) are incapable of brightening the area, as are light spells of lower level. Higher level light spells are not affected by <i>darkness</i>.</p>\n      <p>If <i>darkness</i> is cast on a small object that is then placed inside or under a lightproof covering, the spell\'s effect is blocked until the covering is removed.</p>\n      <p><i>darkness</i> counters or dispels any light spell of equal or lower spell level.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Darkness\" level=\"5\"><p><h5>Darkness</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Darkness]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Cleric 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Object touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>This spell causes an object to radiate shadowy illumination out to a 20-foot radius. All creatures in the area gain concealment (20% miss chance). Even creatures that can normally see in such conditions (such as with darkvision or low-light vision) have the miss chance in an area shrouded in magical <i>darkness</i>.</p><p>Normal lights (torches, candles, lanterns, and so forth) are incapable of brightening the area, as are light spells of lower level. Higher level light spells are not affected by <i>darkness</i>.</p><p>If <i>darkness</i> is cast on a small object that is then placed inside or under a lightproof covering, the spell\'s effect is blocked until the covering is removed.</p><p><i>darkness</i> counters or dispels any light spell of equal or lower spell level.</p><p><i>Arcane Material Component:</i> A bit of bat fur and either a drop of pitch or a piece of coal.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (209,'Darkvision','darkvision','Transmutation',NULL,NULL,NULL,'Ranger 3, Sorcerer/Wizard 2','V, S, M','1 standard action','Touch','Creature touched',NULL,NULL,'1 hour/level','Will negates (harmless)','Yes (harmless)','See 60 ft. in total darkness.',NULL,'Either a pinch of dried carrot or an agate.',NULL,NULL,'\n      <p>The subject gains the ability to see 60 feet even in total darkness. Darkvision is black and white only but otherwise like normal sight. <i>Darkvision</i> does not grant one the ability to see in magical darkness.</p>\n      <p><i>Darkvision</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Darkvision\" level=\"5\"><p><h5>Darkvision</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Transmutation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Ranger 3, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject gains the ability to see 60 feet even in total darkness. Darkvision is black and white only but otherwise like normal sight. <i>Darkvision</i> does not grant one the ability to see in magical darkness.</p><p><i>Darkvision</i> can be made permanent with a <i>permanency</i> spell.</p><p><i>Material Component:</i> Either a pinch of dried carrot or an agate.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (210,'Daylight','daylight','Evocation',NULL,'Light',NULL,'Bard 3, Cleric 3, Druid 3, Paladin 3, Sorcerer/Wizard 3','V, S','1 standard action','Touch','Object touched',NULL,NULL,'10 min./level (D)','None','No','60-ft. radius of bright light.',NULL,NULL,NULL,NULL,'\n      <p>The object touched sheds light as bright as full daylight in a 60-foot radius, and dim light for an additional 60 feet beyond that. Creatures that take penalties in bright light also take them while within the radius of this magical light. Despite its name, this spell is not the equivalent of daylight for the purposes of creatures that are damaged or destroyed by bright light.</p>\n      <p>If <i>daylight</i> is cast on a small object that is then placed inside or under a light- proof covering, the spell\'s effects are blocked until the covering is removed.</p>\n      <p><i>daylight</i> brought into an area of magical darkness (or vice versa) is temporarily negated, so that the otherwise prevailing light conditions exist in the overlapping areas of effect.</p>\n      <p><i>daylight</i> counters or dispels any darkness spell of equal or lower level, such as <i>darkness</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Daylight\" level=\"5\"><p><h5>Daylight</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Light]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Cleric 3, Druid 3, Paladin 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Object touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>The object touched sheds light as bright as full daylight in a 60-foot radius, and dim light for an additional 60 feet beyond that. Creatures that take penalties in bright light also take them while within the radius of this magical light. Despite its name, this spell is not the equivalent of daylight for the purposes of creatures that are damaged or destroyed by bright light.</p><p>If <i>daylight</i> is cast on a small object that is then placed inside or under a light- proof covering, the spell\'s effects are blocked until the covering is removed.</p><p><i>daylight</i> brought into an area of magical darkness (or vice versa) is temporarily negated, so that the otherwise prevailing light conditions exist in the overlapping areas of effect.</p><p><i>daylight</i> counters or dispels any darkness spell of equal or lower level, such as <i>darkness</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (211,'Daze','daze','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 0, Sorcerer/Wizard 0','V, S, M','1 standard action','Close (25 ft. + 5 ft./2 levels)','One humanoid creature of 4 HD or less',NULL,NULL,'1 round','Will negates','Yes','Humanoid creature of 4 HD or less loses next action.',NULL,'A pinch of wool or similar substance.',NULL,NULL,'\n      <p>This enchantment clouds the mind of a humanoid creature with 4 or fewer Hit Dice so that it takes no actions. Humanoids of 5 or more HD are not affected. A dazed subject is not stunned, so attackers get no special advantage against it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Daze\" level=\"5\"><p><h5>Daze</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 0, Sorcerer/Wizard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One humanoid creature of 4 HD or less<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 round<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This enchantment clouds the mind of a humanoid creature with 4 or fewer Hit Dice so that it takes no actions. Humanoids of 5 or more HD are not affected. A dazed subject is not stunned, so attackers get no special advantage against it.</p><p><i>Material Component:</i> A pinch of wool or similar substance.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (212,'Daze Monster','daze monster','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 2, Sorcerer/Wizard 2','V, S, M','1 standard action','Medium (100 ft. + 10 ft./level)','One living creature of 6 HD or less',NULL,NULL,'1 round','Will negates','Yes','Living creature of 6 HD or less loses next action.',NULL,'A pinch of wool or similar substance.',NULL,NULL,'\n      <p>This spell functions like <i>daze</i>,  but <i>daze monster</i> can affect any one living creature of any type. Creatures of 7 or more HD are not affected.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Daze Monster\" level=\"5\"><p><h5>Daze Monster</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Medium (100 ft. + 10 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One living creature of 6 HD or less<br/></td></tr></table><p>This spell functions like <i>daze</i>,  but <i>daze monster</i> can affect any one living creature of any type. Creatures of 7 or more HD are not affected.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (213,'Death Knell','death knell','Necromancy',NULL,'Death, Evil',NULL,'Cleric 2, Death 2','V, S','1 standard action','Touch','Living creature touched',NULL,NULL,'Instantaneous/10 minutes per HD of subject; see text','Will negates','Yes','Kill dying creature and gain 1d8 temporary hp, +2 to Str, and +1 caster level.',NULL,NULL,NULL,NULL,'\n      <p>You draw forth the ebbing life force of a creature and use it to fuel your own power. Upon casting this spell, you touch a living creature that has -1 or fewer hit points. If the subject fails its saving throw, it dies, and you gain 1d8 temporary hit points and a +2 bonus to Strength. Additionally, your effective caster level goes up by +1, improving spell effects dependent on caster level. (This increase in effective caster level does not grant you access to more spells.) These effects last for 10 minutes per HD of the subject creature.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Death Knell\" level=\"5\"><p><h5>Death Knell</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Death, Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Death 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous/10 minutes per HD of subject; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>You draw forth the ebbing life force of a creature and use it to fuel your own power. Upon casting this spell, you touch a living creature that has -1 or fewer hit points. If the subject fails its saving throw, it dies, and you gain 1d8 temporary hit points and a +2 bonus to Strength. Additionally, your effective caster level goes up by +1, improving spell effects dependent on caster level. (This increase in effective caster level does not grant you access to more spells.) These effects last for 10 minutes per HD of the subject creature.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (214,'Death Ward','death ward','Necromancy',NULL,NULL,NULL,'Cleric 4, Death 4, Druid 5, Paladin 4','V, S, DF','1 standard action','Touch','Living creature touched',NULL,NULL,'1 min./level','Will negates (harmless)','Yes (harmless)','Grants immunity to death spells and negative energy effects.',NULL,NULL,NULL,NULL,'\n      <p>The subject is immune to all death spells, magical death effects, energy drain, and any negative energy effects.</p>\n      <p>This spell doesn\'t remove negative levels that the subject has already gained, nor does it affect the saving throw necessary 24 hours after gaining a negative level.</p>\n      <p><i>Death ward</i> does not protect against other sorts of attacks even if those attacks might be lethal.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Death Ward\" level=\"5\"><p><h5>Death Ward</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 4, Death 4, Druid 5, Paladin 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Living creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject is immune to all death spells, magical death effects, energy drain, and any negative energy effects.</p><p>This spell doesn\'t remove negative levels that the subject has already gained, nor does it affect the saving throw necessary 24 hours after gaining a negative level.</p><p><i>Death ward</i> does not protect against other sorts of attacks even if those attacks might be lethal.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (215,'Deathwatch','deathwatch','Necromancy',NULL,'Evil',NULL,'Cleric 1','V, S','1 standard action','30 ft.',NULL,'Cone-shaped emanation',NULL,'10 min./level','None','No','Reveals how near death subjects within 30 ft. are.',NULL,NULL,NULL,NULL,'\n      <p>Using the foul sight granted by the powers of unlife, you can determine the condition of creatures near death within the spell\'s range. You instantly know whether each creature within the area is dead, fragile (alive and wounded, with 3 or fewer hit points left), fighting off death (alive with 4 or more hit points), undead, or neither alive nor dead (such as a construct).</p>\n      <p><i>Deathwatch</i> sees through any spell or ability that allows creatures to feign death.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Deathwatch\" level=\"5\"><p><h5>Deathwatch</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>30 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>10 min./level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>Using the foul sight granted by the powers of unlife, you can determine the condition of creatures near death within the spell\'s range. You instantly know whether each creature within the area is dead, fragile (alive and wounded, with 3 or fewer hit points left), fighting off death (alive with 4 or more hit points), undead, or neither alive nor dead (such as a construct).</p><p><i>Deathwatch</i> sees through any spell or ability that allows creatures to feign death.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (216,'Deep Slumber','deep slumber','Enchantment','Compulsion','Mind-Affecting',NULL,'Bard 3, Sorcerer/Wizard 3','V, S, M','1 round','Close (25 ft. + 5 ft./2 levels)',NULL,'One or more living creatures within a 10-ft. -radius burst',NULL,'1 min./level','Will negates','Yes','Puts 10 HD of creatures to sleep.',NULL,'A pinch of fine sand, rose petals, or a live cricket.',NULL,NULL,'\n      <p>This spell functions like <i>sleep</i>,  except that it affects 10 HD of creatures.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Deep Slumber\" level=\"5\"><p><h5>Deep Slumber</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 3, Sorcerer/Wizard 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr></table><p>This spell functions like <i>sleep</i>,  except that it affects 10 HD of creatures.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (217,'Deeper Darkness','deeper darkness','Evocation',NULL,'Darkness',NULL,'Cleric 3','V, M/DF','1 standard action','Touch','Object touched',NULL,NULL,'One day/level (D)','None','No','Object sheds supernatural shadow in 60-ft. radius.',NULL,NULL,'A bit of bat fur and either a drop of pitch or a piece of coal.',NULL,'\n      <p>This spell functions like <i>darkness</i>, except that the object radiates shadowy illumination in a 60-foot radius and the <i>darkness</i> lasts longer.</p>\n      <p><i>daylight</i> brought into an area of <i>Deeper darkness</i> (or vice versa) is temporarily negated, so that the otherwise prevailing light conditions exist in the overlapping areas of effect.</p>\n      <p><i>Deeper darkness</i> counters and dispels any light spell of equal or lower level, including <i>daylight</i> and <i>light</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Deeper Darkness\" level=\"5\"><p><h5>Deeper Darkness</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Darkness]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 3<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>One day/level (D)<br/></td></tr></table><p>This spell functions like <i>darkness</i>, except that the object radiates shadowy illumination in a 60-foot radius and the <i>darkness</i> lasts longer.</p><p><i>daylight</i> brought into an area of <i>Deeper darkness</i> (or vice versa) is temporarily negated, so that the otherwise prevailing light conditions exist in the overlapping areas of effect.</p><p><i>Deeper darkness</i> counters and dispels any light spell of equal or lower level, including <i>daylight</i> and <i>light</i>.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (218,'Delay Poison','delay poison','Conjuration','Healing',NULL,NULL,'Bard 2, Cleric 2, Druid 2, Paladin 2, Ranger 1','V, S, DF','1 standard action','Touch','Creature touched',NULL,NULL,'1 hour/level','Fortitude negates (harmless)','Yes (harmless)','Stops poison from harming subject for 1 hour/level.',NULL,NULL,NULL,NULL,'\n      <p>The subject becomes temporarily immune to poison. Any poison in its system or any poison to which it is exposed during the spell\'s duration does not affect the subject until the spell\'s duration has expired. <i>Delay poison</i> does not cure any damage that poison may have already done.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Delay Poison\" level=\"5\"><p><h5>Delay Poison</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Conjuration (Healing)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Cleric 2, Druid 2, Paladin 2, Ranger 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Touch<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>Creature touched<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>1 hour/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude negates (harmless)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes (harmless)<br/></td></tr></table><p>The subject becomes temporarily immune to poison. Any poison in its system or any poison to which it is exposed during the spell\'s duration does not affect the subject until the spell\'s duration has expired. <i>Delay poison</i> does not cure any damage that poison may have already done.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (219,'Delayed Blast Fireball','delayed blast fireball','Evocation',NULL,'Fire',NULL,'Sorcerer/Wizard 7','V, S, M','1 standard action','Long (400 ft. + 40 ft./level)',NULL,'20-ft. -radius spread',NULL,'5 rounds or less; see text','Reflex half','Yes','1d6/level fire damage; you can postpone blast for 5 rounds.',NULL,'A tiny ball of bat guano and sulfur.',NULL,NULL,'\n      <p>This spell functions like <i>fireball</i>,  except that it is more powerful and can detonate up to 5 rounds after the spell is cast. The burst of flame deals 1d6 points of fire damage per caster level (maximum 20d6).</p>\n      <p>The glowing bead created by <i>delayed blast fireball</i> can detonate immediately if you desire, or you can choose to delay the burst for as many as 5 rounds. You select the amount of delay upon completing the spell, and that time cannot change once it has been set unless someone touches the bead (see below). If you choose a delay, the glowing bead sits at its destination until it detonates. A creature can pick up and hurl the bead as a thrown weapon (range increment 10 feet). If a creature handles and moves the bead within 1 round of its detonation, there is a 25% chance that the bead detonates while being handled.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Delayed Blast Fireball\" level=\"5\"><p><h5>Delayed Blast Fireball</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Fire]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>5 rounds or less; see text<br/></td></tr></table><p>This spell functions like <i>fireball</i>,  except that it is more powerful and can detonate up to 5 rounds after the spell is cast. The burst of flame deals 1d6 points of fire damage per caster level (maximum 20d6).</p><p>The glowing bead created by <i>delayed blast fireball</i> can detonate immediately if you desire, or you can choose to delay the burst for as many as 5 rounds. You select the amount of delay upon completing the spell, and that time cannot change once it has been set unless someone touches the bead (see below). If you choose a delay, the glowing bead sits at its destination until it detonates. A creature can pick up and hurl the bead as a thrown weapon (range increment 10 feet). If a creature handles and moves the bead within 1 round of its detonation, there is a 25% chance that the bead detonates while being handled.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (220,'Demand','demand','Enchantment','Compulsion','Mind-Affecting',NULL,'Sorcerer/Wizard 8','V, S, M/DF','10 minutes','See text','One creature',NULL,NULL,'1 round; see text','Will partial','Yes','As sending, plus you can send suggestion.',NULL,'A short piece of copper wire and some small part of the subject-a hair, a bit of nail, or the like.','A short piece of fine copper wire.',NULL,'\n      <p>This spell functions like <i>sending</i>,  but the message can also contain a <i>suggestion</i> (see the <i>suggestion</i> spell), which the subject does its best to carry out. A successful Will save negates the <i>suggestion</i> effect but not the contact itself. The <i>demand</i>,  if received, is understood even if the subject\'s Intelligence score is as low as 1. If the message is impossible or meaningless according to the circumstances that exist for the subject at the time the <i>demand</i> is issued, the message is understood but the <i>suggestion</i> is ineffective.</p>\n      <p>The <i>demand</i>\'s message to the creature must be twenty-five words or less, including the <i>suggestion</i>. The creature can also give a short reply immediately.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Demand\" level=\"5\"><p><h5>Demand</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Enchantment (Compulsion) [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Sorcerer/Wizard 8<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will partial<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell functions like <i>sending</i>,  but the message can also contain a <i>suggestion</i> (see the <i>suggestion</i> spell), which the subject does its best to carry out. A successful Will save negates the <i>suggestion</i> effect but not the contact itself. The <i>demand</i>,  if received, is understood even if the subject\'s Intelligence score is as low as 1. If the message is impossible or meaningless according to the circumstances that exist for the subject at the time the <i>demand</i> is issued, the message is understood but the <i>suggestion</i> is ineffective.</p><p>The <i>demand</i>\'s message to the creature must be twenty-five words or less, including the <i>suggestion</i>. The creature can also give a short reply immediately.</p><p><i>Material Component:</i> A short piece of copper wire and some small part of the subject-a hair, a bit of nail, or the like.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (221,'Desecrate','desecrate','Evocation',NULL,'Evil',NULL,'Cleric 2, Evil 2','V, S, M, DF','1 standard action','Close (25 ft. + 5 ft./2 levels)',NULL,'20-ft. -radius emanation',NULL,'2 hours/level','None','Yes','Fills area with negative energy, making undead stronger.',NULL,'A vial of unholy water and 25 gp worth (5 pounds) of silver dust, all of which must be sprinkled around the area.',NULL,NULL,'\n      <p>This spell imbues an area with negative energy. Each Charisma check made to turn undead within this area takes a -3 profane penalty, and every undead creature entering a <i>desecrated</i> area gains a +1 profane bonus on attack rolls, damage rolls, and saving throws. An undead creature created within or summoned into such an area gains +1 hit points per HD.</p>\n      <p>If the <i>desecrated</i> area contains an altar, shrine, or other permanent fixture dedicated to your deity or aligned higher power, the modifiers given above are doubled (-6 profane penalty on turning checks, +2 profane bonus and +2 hit points per HD for undead in the area).</p>\n      <p>Furthermore, anyone who casts <i>animate dead</i> within this area may create as many as double the normal amount of undead (that is, 4 HD per caster level rather than 2 HD per caster level).</p>\n      <p>If the area contains an altar, shrine, or other permanent fixture of a deity, pantheon, or higher power other than your patron, the <i>Desecrate</i> spell instead curses the area, cutting off its connection with the associated deity or power. This secondary function, if used, does not also grant the bonuses and penalties relating to undead, as given above.</p>\n      <p><i>Desecrate</i> counters and dispels <i>consecrate</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Desecrate\" level=\"5\"><p><h5>Desecrate</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Evocation [Evil]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 2, Evil 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>20-ft. -radius emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>2 hours/level<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell imbues an area with negative energy. Each Charisma check made to turn undead within this area takes a -3 profane penalty, and every undead creature entering a <i>desecrated</i> area gains a +1 profane bonus on attack rolls, damage rolls, and saving throws. An undead creature created within or summoned into such an area gains +1 hit points per HD.</p><p>If the <i>desecrated</i> area contains an altar, shrine, or other permanent fixture dedicated to your deity or aligned higher power, the modifiers given above are doubled (-6 profane penalty on turning checks, +2 profane bonus and +2 hit points per HD for undead in the area).</p><p>Furthermore, anyone who casts <i>animate dead</i> within this area may create as many as double the normal amount of undead (that is, 4 HD per caster level rather than 2 HD per caster level).</p><p>If the area contains an altar, shrine, or other permanent fixture of a deity, pantheon, or higher power other than your patron, the <i>Desecrate</i> spell instead curses the area, cutting off its connection with the associated deity or power. This secondary function, if used, does not also grant the bonuses and penalties relating to undead, as given above.</p><p><i>Desecrate</i> counters and dispels <i>consecrate</i>.</p><p><i>Material Component:</i> A vial of unholy water and 25 gp worth (5 pounds) of silver dust, all of which must be sprinkled around the area.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (222,'Destruction','destruction','Necromancy',NULL,'Death',NULL,'Cleric 7, Death 7','V, S, F','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature',NULL,NULL,'Instantaneous','Fortitude partial','Yes','Kills subject and destroys remains.',NULL,NULL,NULL,'A special holy (or unholy) symbol of silver marked with verses of anathema (cost 500 gp).','\n      <p>This spell instantly slays the subject and consumes its remains (but not its equipment and possessions) utterly. If the target\'s Fortitude saving throw succeeds, it instead takes 10d6 points of damage. The only way to restore life to a character who has failed to save against this spell is to use <i>true resurrection</i>, a carefully worded <i>wish</i> spell followed by <i>resurrection</i>, or <i>miracle</i>.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Destruction\" level=\"5\"><p><h5>Destruction</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Necromancy [Death]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 7, Death 7<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target:</b><br/></td><td>One creature<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Fortitude partial<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>Yes<br/></td></tr></table><p>This spell instantly slays the subject and consumes its remains (but not its equipment and possessions) utterly. If the target\'s Fortitude saving throw succeeds, it instead takes 10d6 points of damage. The only way to restore life to a character who has failed to save against this spell is to use <i>true resurrection</i>, a carefully worded <i>wish</i> spell followed by <i>resurrection</i>, or <i>miracle</i>.</p><p><i>Focus:</i> A special holy (or unholy) symbol of silver marked with verses of anathema (cost 500 gp).</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (223,'Detect Animals or Plants','detect animals or plants','Divination',NULL,NULL,NULL,'Druid 1, Ranger 1','V, S','1 standard action','Long (400 ft. + 40 ft./level)',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 10 min./level (D)','None','No','Detects kinds of animals or plants.',NULL,NULL,NULL,NULL,'\n      <p>You can detect a particular kind of animal or plant in a cone emanating out from you in whatever direction you face. You must think of a kind of animal or plant when using the spell, but you can change the animal or plant kind each round. The amount of information revealed depends on how long you search a particular area or focus on a specific kind of animal or plant.</p>\n      <p><i>1st Round:</i> Presence or absence of that kind of animal or plant in the area.</p>\n      <p><i>2nd Round:</i> Number of individuals of the specified kind in the area, and the condition of the healthiest specimen.</p>\n      <p><i>3rd Round:</i> The condition (see below) and location of each individual present. If an animal or plant is outside your line of sight, then you discern its direction but not its exact location.</p>\n      <p><i>Conditions:</i> For purposes of this spell, the categories of condition are as follows:</p>\n      <p>Normal: Has at least 90% of full normal hit points, free of disease.</p>\n      <p>Fair: 30% to 90% of full normal hit points remaining.</p>\n      <p>Poor: Less than 30% of full normal hit points remaining, afflicted with a disease, or suffering from a debilitating injury.</p>\n      <p>Weak: 0 or fewer hit points remaining, afflicted with a disease in the terminal stage, or crippled.</p>\n      <p>If a creature falls into more than one category, the spell indicates the weaker of the two.</p>\n      <p>Each round you can turn to detect a kind of animal or plant in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Animals or Plants\" level=\"5\"><p><h5>Detect Animals or Plants</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 1, Ranger 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Long (400 ft. + 40 ft./level)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You can detect a particular kind of animal or plant in a cone emanating out from you in whatever direction you face. You must think of a kind of animal or plant when using the spell, but you can change the animal or plant kind each round. The amount of information revealed depends on how long you search a particular area or focus on a specific kind of animal or plant.</p><p><i>1st Round:</i> Presence or absence of that kind of animal or plant in the area.</p><p><i>2nd Round:</i> Number of individuals of the specified kind in the area, and the condition of the healthiest specimen.</p><p><i>3rd Round:</i> The condition (see below) and location of each individual present. If an animal or plant is outside your line of sight, then you discern its direction but not its exact location.</p><p><i>Conditions:</i> For purposes of this spell, the categories of condition are as follows:</p><p>Normal: Has at least 90% of full normal hit points, free of disease.</p><p>Fair: 30% to 90% of full normal hit points remaining.</p><p>Poor: Less than 30% of full normal hit points remaining, afflicted with a disease, or suffering from a debilitating injury.</p><p>Weak: 0 or fewer hit points remaining, afflicted with a disease in the terminal stage, or crippled.</p><p>If a creature falls into more than one category, the spell indicates the weaker of the two.</p><p>Each round you can turn to detect a kind of animal or plant in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (224,'Detect Chaos','detect chaos','Divination',NULL,NULL,NULL,'Cleric 1','V, S, DF','1 standard action','60 ft.',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 10 min./level (D)','None','No','Reveals creatures, spells, or objects of selected alignment.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>detect evil</i>, except that it detects the auras of chaotic creatures, clerics of chaotic deities, chaotic spells, and chaotic magic items, and you are vulnerable to an overwhelming chaotic aura if you are lawful.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Chaos\" level=\"5\"><p><h5>Detect Chaos</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1<br/></td></tr></table><p>This spell functions like <i>detect evil</i>, except that it detects the auras of chaotic creatures, clerics of chaotic deities, chaotic spells, and chaotic magic items, and you are vulnerable to an overwhelming chaotic aura if you are lawful.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (225,'Detect Evil','detect evil','Divination',NULL,NULL,NULL,'Cleric 1','V, S, DF','1 standard action','60 ft.',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 10 min./level (D)','None','No','Reveals creatures, spells, or objects of selected alignment.',NULL,NULL,NULL,NULL,'\n      <p>You can sense the presence of evil. The amount of information revealed depends on how long you study a particular area or subject.</p>\n      <p><i>1st Round:</i> Presence or absence of evil.</p>\n      <p><i>2nd Round:</i> Number of evil auras (creatures, objects, or spells) in the area and the power of the most potent evil aura present.</p>\n      <p>If you are of good alignment, and the strongest evil aura\'s power is overwhelming (see below), and the HD or level of the aura\'s source is at least twice your character level, you are stunned for 1 round and the spell ends.</p>\n      <p><i>3rd Round:</i> The power and location of each aura. If an aura is outside your line of sight, then you discern its direction but not its exact location.</p>\n      <p><i>Aura Power:</i> An evil aura\'s power depends on the type of evil creature or object that you\'re detecting and its HD, caster level, or (in the case of a cleric) class level; see the accompanying table. If an aura falls into more than one strength category, the spell indicates the stronger of the two.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"3\">\n<td/>\n<td colspan=\"4\" align=\"center\"><b>-------- Aura Power --------</b><br/></td> \n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Creature/Object</b><br/></td>\n<td><b>Faint</b><br/></td>\n<td><b>Moderate</b><br/></td>\n<td><b>Strong</b><br/></td>\n<td><b>Overwhelming</b><br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Evil creature<b>1</b> (HD)<br/></td>\n<td>10 or lower<br/></td>\n<td>11-25<br/></td>\n<td>26-50<br/></td>\n<td>51 or higher<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Undead (HD)<br/></td>\n<td>2 or lower<br/></td>\n<td>3-8<br/></td>\n<td>9-20<br/></td>\n<td>21 or higher<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Evil outsider (HD)<br/></td>\n<td>1 or lower<br/></td>\n<td>2-4<br/></td>\n<td>5-10<br/></td>\n<td>11 or higher<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Cleric of an evil deity <b>2</b> (class levels)<br/></td>\n<td>1<br/></td>\n<td>2-4<br/></td>\n<td>5-10<br/></td>\n<td>11 or higher<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Evil magic item or spell (caster level)<br/></td>\n<td>2nd or lower<br/></td>\n<td>3rd-8th<br/></td>\n<td>9th-20th<br/></td>\n<td>21st or higher<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"2\">\n<td colspan=\"5\">1 Except for undead and outsiders, which have their own entries on the table.<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"2\">\n<td colspan=\"5\">2 Some characters who are not clerics may radiate an aura of equivalent power. The class description will indicate whether this applies.<br/></td>\n\n</tr>\n</table>\n      <p><i>Lingering Aura:</i> An evil aura lingers after its original source dissipates (in the case of a spell) or is destroyed (in the case of a creature or magic item). If <i>detect evil</i> is cast and directed at such a location, the spell indicates an aura strength of dim (even weaker than a faint aura). How long the aura lingers at this dim level depends on its original power:</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Original Strength</b><br/></td> <td><b>Duration of</b>\n <b>Lingering Aura</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Faint<br/></td>\n<td>1d6 rounds<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Moderate<br/></td>\n<td>1d6 minutes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Strong<br/></td>\n<td>1d6x10 minutes<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Overwhelming<br/></td>\n<td>1d6 days<br/></td>\n\n</tr>\n</table>\n      <p>Animals, traps, poisons, and other potential perils are not evil, and as such this spell does not detect them.</p>\n      <p>Each round, you can turn to detect evil in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Evil\" level=\"5\"><p><h5>Detect Evil</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You can sense the presence of evil. The amount of information revealed depends on how long you study a particular area or subject.</p><p><i>1st Round:</i> Presence or absence of evil.</p><p><i>2nd Round:</i> Number of evil auras (creatures, objects, or spells) in the area and the power of the most potent evil aura present.</p><p>If you are of good alignment, and the strongest evil aura\'s power is overwhelming (see below), and the HD or level of the aura\'s source is at least twice your character level, you are stunned for 1 round and the spell ends.</p><p><i>3rd Round:</i> The power and location of each aura. If an aura is outside your line of sight, then you discern its direction but not its exact location.</p><p><i>Aura Power:</i> An evil aura\'s power depends on the type of evil creature or object that you\'re detecting and its HD, caster level, or (in the case of a cleric) class level; see the accompanying table. If an aura falls into more than one strength category, the spell indicates the stronger of the two.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"3\">\n<td/>\n<td colspan=\"4\" align=\"center\"><b>-------- Aura Power --------</b><br/></td> \n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Creature/Object</b><br/></td>\n<td><b>Faint</b><br/></td>\n<td><b>Moderate</b><br/></td>\n<td><b>Strong</b><br/></td>\n<td><b>Overwhelming</b><br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Evil creature<b>1</b> (HD)<br/></td>\n<td>10 or lower<br/></td>\n<td>11-25<br/></td>\n<td>26-50<br/></td>\n<td>51 or higher<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Undead (HD)<br/></td>\n<td>2 or lower<br/></td>\n<td>3-8<br/></td>\n<td>9-20<br/></td>\n<td>21 or higher<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Evil outsider (HD)<br/></td>\n<td>1 or lower<br/></td>\n<td>2-4<br/></td>\n<td>5-10<br/></td>\n<td>11 or higher<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Cleric of an evil deity <b>2</b> (class levels)<br/></td>\n<td>1<br/></td>\n<td>2-4<br/></td>\n<td>5-10<br/></td>\n<td>11 or higher<br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Evil magic item or spell (caster level)<br/></td>\n<td>2nd or lower<br/></td>\n<td>3rd-8th<br/></td>\n<td>9th-20th<br/></td>\n<td>21st or higher<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"2\">\n<td colspan=\"5\">1 Except for undead and outsiders, which have their own entries on the table.<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"2\">\n<td colspan=\"5\">2 Some characters who are not clerics may radiate an aura of equivalent power. The class description will indicate whether this applies.<br/></td>\n\n</tr>\n</table><p><i>Lingering Aura:</i> An evil aura lingers after its original source dissipates (in the case of a spell) or is destroyed (in the case of a creature or magic item). If <i>detect evil</i> is cast and directed at such a location, the spell indicates an aura strength of dim (even weaker than a faint aura). How long the aura lingers at this dim level depends on its original power:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Original Strength</b><br/></td> <td><b>Duration of</b>\n <b>Lingering Aura</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Faint<br/></td>\n<td>1d6 rounds<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Moderate<br/></td>\n<td>1d6 minutes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Strong<br/></td>\n<td>1d6x10 minutes<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Overwhelming<br/></td>\n<td>1d6 days<br/></td>\n\n</tr>\n</table><p>Animals, traps, poisons, and other potential perils are not evil, and as such this spell does not detect them.</p><p>Each round, you can turn to detect evil in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (226,'Detect Good','detect good','Divination',NULL,NULL,NULL,'Cleric 1','V, S, DF','1 standard action','60 ft.',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 10 min./level (D)','None','No','Reveals creatures, spells, or objects of selected alignment.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>detect evil</i>, except that it detects the auras of good creatures, clerics or paladins of good deities, good spells, and good magic items, and you are vulnerable to an overwhelming good aura if you are evil. Healing potions, antidotes, and similar beneficial items are not good.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Good\" level=\"5\"><p><h5>Detect Good</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1<br/></td></tr></table><p>This spell functions like <i>detect evil</i>, except that it detects the auras of good creatures, clerics or paladins of good deities, good spells, and good magic items, and you are vulnerable to an overwhelming good aura if you are evil. Healing potions, antidotes, and similar beneficial items are not good.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (227,'Detect Law','detect law','Divination',NULL,NULL,NULL,'Cleric 1','V, S, DF','1 standard action','60 ft.',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 10 min./level (D)','None','No','Reveals creatures, spells, or objects of selected alignment.',NULL,NULL,NULL,NULL,'\n      <p>This spell functions like <i>detect evil</i>, except that it detects the auras of lawful creatures, clerics of lawful deities, lawful spells, and lawful magic items, and you are vulnerable to an overwhelming lawful aura if you are chaotic.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Law\" level=\"5\"><p><h5>Detect Law</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1<br/></td></tr></table><p>This spell functions like <i>detect evil</i>, except that it detects the auras of lawful creatures, clerics of lawful deities, lawful spells, and lawful magic items, and you are vulnerable to an overwhelming lawful aura if you are chaotic.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (228,'Detect Magic','detect magic','Divination',NULL,NULL,NULL,'Bard 0, Cleric 0, Druid 0, Sorcerer/Wizard 0','V, S','1 standard action','60 ft.',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 1 min./level (D)','None','No','Detects spells and magic items within 60 ft.',NULL,NULL,NULL,NULL,'\n      <p>You detect magical auras. The amount of information revealed depends on how long you study a particular area or subject.</p>\n      <p><i>1st Round:</i> Presence or absence of magical auras.</p>\n      <p><i>2nd Round:</i> Number of different magical auras and the power of the most potent aura.</p>\n      <p><i>3rd Round:</i> The strength and location of each aura. If the items or creatures bearing the auras are in line of sight, you can make Spellcraft skill checks to determine the school of magic involved in each. (Make one check per aura; DC 15 + spell level, or 15 + half caster level for a nonspell effect.)</p>\n      <p>Magical areas, multiple types of magic, or strong local magical emanations may distort or conceal weaker auras.</p>\n      <p><i>Aura Strength:</i> An aura\'s power depends on a spell\'s functioning spell level or an item\'s caster level. If an aura falls into more than one category, <i>Detect magic</i> indicates the stronger of the two.</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"3\">\n<td/>\n<td colspan=\"4\" align=\"center\"><b>--------- Aura Power ---------</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Spell or Object</b><br/></td>\n<td><b>Faint</b><br/></td>\n<td><b>Moderate</b><br/></td>\n<td><b>Strong</b><br/></td>\n<td><b>Overwhelming</b><br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Functioning spell (spell level)<br/></td>\n<td>3rd or lower<br/></td>\n<td>4th-6th<br/></td>\n<td>7th-9th<br/></td>\n<td>10th+ (deity-level)<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Magic item (caster level)<br/></td>\n<td>5th or lower<br/></td>\n<td>6th-11th<br/></td>\n<td>12th-20th<br/></td>\n<td>21st+ (artifact)<br/></td>\n\n</tr>\n</table>\n      <p><i>Lingering Aura:</i> A magical aura lingers after its original source dissipates (in the case of a spell) or is destroyed (in the case of a magic item). If <i>Detect magic</i> is cast and directed at such a location, the spell indicates an aura strength of dim (even weaker than a faint aura). How long the aura lingers at this dim level depends on its original power:</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Original Strength</b><br/></td> <td><b>Duration of Lingering Aura</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Faint<br/></td>\n<td>1d6 rounds<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Moderate<br/></td>\n<td>1d6 minutes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Strong<br/></td>\n<td>1d6x10 minutes<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Overwhelming<br/></td>\n<td>1d6 days<br/></td>\n\n</tr>\n</table>\n      <p>Outsiders and elementals are not magical in themselves, but if they are summoned, the conjuration spell registers.</p>\n      <p>Each round, you can turn to detect magic in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p>\n      <p><i>Detect magic</i> can be made permanent with a <i>permanency</i> spell.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Magic\" level=\"5\"><p><h5>Detect Magic</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 0, Cleric 0, Druid 0, Sorcerer/Wizard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You detect magical auras. The amount of information revealed depends on how long you study a particular area or subject.</p><p><i>1st Round:</i> Presence or absence of magical auras.</p><p><i>2nd Round:</i> Number of different magical auras and the power of the most potent aura.</p><p><i>3rd Round:</i> The strength and location of each aura. If the items or creatures bearing the auras are in line of sight, you can make Spellcraft skill checks to determine the school of magic involved in each. (Make one check per aura; DC 15 + spell level, or 15 + half caster level for a nonspell effect.)</p><p>Magical areas, multiple types of magic, or strong local magical emanations may distort or conceal weaker auras.</p><p><i>Aura Strength:</i> An aura\'s power depends on a spell\'s functioning spell level or an item\'s caster level. If an aura falls into more than one category, <i>Detect magic</i> indicates the stronger of the two.</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"6\" curcol=\"3\">\n<td/>\n<td colspan=\"4\" align=\"center\"><b>--------- Aura Power ---------</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td><b>Spell or Object</b><br/></td>\n<td><b>Faint</b><br/></td>\n<td><b>Moderate</b><br/></td>\n<td><b>Strong</b><br/></td>\n<td><b>Overwhelming</b><br/></td>\n\n</tr>\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Functioning spell (spell level)<br/></td>\n<td>3rd or lower<br/></td>\n<td>4th-6th<br/></td>\n<td>7th-9th<br/></td>\n<td>10th+ (deity-level)<br/></td>\n\n</tr>\n\n<tr maxcol=\"6\" curcol=\"6\">\n<td>Magic item (caster level)<br/></td>\n<td>5th or lower<br/></td>\n<td>6th-11th<br/></td>\n<td>12th-20th<br/></td>\n<td>21st+ (artifact)<br/></td>\n\n</tr>\n</table><p><i>Lingering Aura:</i> A magical aura lingers after its original source dissipates (in the case of a spell) or is destroyed (in the case of a magic item). If <i>Detect magic</i> is cast and directed at such a location, the spell indicates an aura strength of dim (even weaker than a faint aura). How long the aura lingers at this dim level depends on its original power:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Original Strength</b><br/></td> <td><b>Duration of Lingering Aura</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Faint<br/></td>\n<td>1d6 rounds<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Moderate<br/></td>\n<td>1d6 minutes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Strong<br/></td>\n<td>1d6x10 minutes<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Overwhelming<br/></td>\n<td>1d6 days<br/></td>\n\n</tr>\n</table><p>Outsiders and elementals are not magical in themselves, but if they are summoned, the conjuration spell registers.</p><p>Each round, you can turn to detect magic in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p><p><i>Detect magic</i> can be made permanent with a <i>permanency</i> spell.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (229,'Detect Poison','detect poison','Divination',NULL,NULL,NULL,'Cleric 0, Druid 0, Paladin 1, Ranger 1, Sorcerer/Wizard 0','V, S','1 standard action','Close (25 ft. + 5 ft./2 levels)','One creature, one object, or a 5-ft. cube','One creature, one object, or a 5-ft. cube',NULL,'Instantaneous','None','No','Detects poison in one creature or small object.',NULL,NULL,NULL,NULL,'\n      <p>You determine whether a creature, object, or area has been poisoned or is poisonous. You can determine the exact type of poison with a DC 20 Wisdom check. A character with the Craft (alchemy) skill may try a DC 20 Craft (alchemy) check if the Wisdom check fails, or may try the Craft (alchemy) check prior to the Wisdom check.</p>\n      <p>The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Poison\" level=\"5\"><p><h5>Detect Poison</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 0, Druid 0, Paladin 1, Ranger 1, Sorcerer/Wizard 0<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>Close (25 ft. + 5 ft./2 levels)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Target or Area:</b><br/></td><td>One creature, one object, or a 5-ft. cube<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Instantaneous<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You determine whether a creature, object, or area has been poisoned or is poisonous. You can determine the exact type of poison with a DC 20 Wisdom check. A character with the Craft (alchemy) skill may try a DC 20 Craft (alchemy) check if the Wisdom check fails, or may try the Craft (alchemy) check prior to the Wisdom check.</p><p>The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (230,'Detect Scrying','detect scrying','Divination',NULL,NULL,NULL,'Bard 4, Sorcerer/Wizard 4','V, S, M','1 standard action','40 ft.',NULL,'40-ft. -radius emanation centered on you',NULL,'24 hours','None','No','Alerts you of magical eavesdropping.',NULL,'A small piece of mirror and a miniature brass hearing trumpet.',NULL,NULL,'\n      <p>You immediately become aware of any attempt to observe you by means of a divination (scrying) spell or effect. The spell\'s area radiates from you and moves as you move. You know the location of every magical sensor within the spell\'s area.</p>\n      <p>If the scrying attempt originates within the area, you also know its location; otherwise, you and the scrier immediately make opposed caster level checks (1d20 + caster level). If you at least match the scrier\'s result, you get a visual image of the scrier and an accurate sense of his or her direction and distance from you.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Scrying\" level=\"5\"><p><h5>Detect Scrying</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 4, Sorcerer/Wizard 4<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>40 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>40-ft. -radius emanation centered on you<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>24 hours<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You immediately become aware of any attempt to observe you by means of a divination (scrying) spell or effect. The spell\'s area radiates from you and moves as you move. You know the location of every magical sensor within the spell\'s area.</p><p>If the scrying attempt originates within the area, you also know its location; otherwise, you and the scrier immediately make opposed caster level checks (1d20 + caster level). If you at least match the scrier\'s result, you get a visual image of the scrier and an accurate sense of his or her direction and distance from you.</p><p><i>Material Component:</i> A small piece of mirror and a miniature brass hearing trumpet.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (231,'Detect Secret Doors','detect secret doors','Divination',NULL,NULL,NULL,'Bard 1, Knowledge 1, Sorcerer/Wizard 1','V, S','1 standard action','60 ft.',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 1 min./level (D)','None','No','Reveals hidden doors within 60 ft.',NULL,NULL,NULL,NULL,'\n      <p>You can detect secret doors, compartments, caches, and so forth. Only passages, doors, or openings that have been specifically constructed to escape detection are detected by this spell. The amount of information revealed depends on how long you study a particular area or subject.</p>\n      <p><i>1st Round:</i> Presence or absence of secret doors.</p>\n      <p><i>2nd Round:</i> Number of secret doors and the location of each. If an aura is outside your line of sight, then you discern its direction but not its exact location.</p>\n      <p><i>Each Additional Round:</i> The mechanism or trigger for one particular secret portal closely examined by you. Each round, you can turn to detect secret doors in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Secret Doors\" level=\"5\"><p><h5>Detect Secret Doors</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 1, Knowledge 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You can detect secret doors, compartments, caches, and so forth. Only passages, doors, or openings that have been specifically constructed to escape detection are detected by this spell. The amount of information revealed depends on how long you study a particular area or subject.</p><p><i>1st Round:</i> Presence or absence of secret doors.</p><p><i>2nd Round:</i> Number of secret doors and the location of each. If an aura is outside your line of sight, then you discern its direction but not its exact location.</p><p><i>Each Additional Round:</i> The mechanism or trigger for one particular secret portal closely examined by you. Each round, you can turn to detect secret doors in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (232,'Detect Snares and Pits','detect snares and pits','Divination',NULL,NULL,NULL,'Druid 1, Ranger 1','V, S','1 standard action','60 ft.',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 10 min./level (D)','None','No','Reveals natural or primitive traps.',NULL,NULL,NULL,NULL,'\n      <p>You can detect simple pits, deadfalls, and snares as well as mechanical traps constructed of natural materials. The spell does not detect complex traps, including trapdoor traps.</p>\n      <p><i>Detect snares and pits</i> does detect certain natural hazards-quicksand (a snare), a sinkhole (a pit), or unsafe walls of natural rock (a deadfall). However, it does not reveal other potentially dangerous conditions. The spell does not detect magic traps (except those that operate by pit, deadfall, or snaring; see the spell <i>snare</i>), nor mechanically complex ones, nor those that have been rendered safe or inactive.</p>\n      <p>The amount of information revealed depends on how long you study a particular area.</p>\n      <p><i>1st Round:</i> Presence or absence of hazards.</p>\n      <p><i>2nd Round:</i> Number of hazards and the location of each. If a hazard is outside your line of sight, then you discern its direction but not its exact location.</p>\n      <p><i>Each Additional Round:</i> The general type and trigger for one particular hazard closely examined by you.</p>\n      <p>Each round, you can turn to detect snares and pits in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Snares and Pits\" level=\"5\"><p><h5>Detect Snares and Pits</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Druid 1, Ranger 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 10 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You can detect simple pits, deadfalls, and snares as well as mechanical traps constructed of natural materials. The spell does not detect complex traps, including trapdoor traps.</p><p><i>Detect snares and pits</i> does detect certain natural hazards-quicksand (a snare), a sinkhole (a pit), or unsafe walls of natural rock (a deadfall). However, it does not reveal other potentially dangerous conditions. The spell does not detect magic traps (except those that operate by pit, deadfall, or snaring; see the spell <i>snare</i>), nor mechanically complex ones, nor those that have been rendered safe or inactive.</p><p>The amount of information revealed depends on how long you study a particular area.</p><p><i>1st Round:</i> Presence or absence of hazards.</p><p><i>2nd Round:</i> Number of hazards and the location of each. If a hazard is outside your line of sight, then you discern its direction but not its exact location.</p><p><i>Each Additional Round:</i> The general type and trigger for one particular hazard closely examined by you.</p><p>Each round, you can turn to detect snares and pits in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (233,'Detect Thoughts','detect thoughts','Divination',NULL,'Mind-Affecting',NULL,'Bard 2, Knowledge 2, Sorcerer/Wizard 2','V, S, F/DF','1 standard action','60 ft.',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 1 min./level (D)','Will negates; see text','No','Allows \'listening\' to surface thoughts.',NULL,NULL,NULL,NULL,'\n      <p>You detect surface thoughts. The amount of information revealed depends on how long you study a particular area or subject.</p>\n      <p><i>1st Round:</i> Presence or absence of thoughts (from conscious creatures with Intelligence scores of 1 or higher).</p>\n      <p><i>2nd Round:</i> Number of thinking minds and the Intelligence score of each. If the highest Intelligence is 26 or higher (and at least 10 points higher than your own Intelligence score), you are stunned for 1 round and the spell ends. This spell does not let you determine the location of the thinking minds if you can\'t see the creatures whose thoughts you are detecting.</p>\n      <p><i>3rd Round:</i> Surface thoughts of any mind in the area. A target\'s Will save prevents you from reading its thoughts, and you must cast <i>detect thoughts</i> again to have another chance. Creatures of animal intelligence (Int 1 or 2) have simple, instinctual thoughts that you can pick up.</p>\n      <p>Each round, you can turn to detect thoughts in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p>\n      <p/>\n    ',NULL,'A copper piece.',NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Thoughts\" level=\"5\"><p><h5>Detect Thoughts</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination [Mind-Affecting]<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Bard 2, Knowledge 2, Sorcerer/Wizard 2<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, F/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 1 min./level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>Will negates; see text<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You detect surface thoughts. The amount of information revealed depends on how long you study a particular area or subject.</p><p><i>1st Round:</i> Presence or absence of thoughts (from conscious creatures with Intelligence scores of 1 or higher).</p><p><i>2nd Round:</i> Number of thinking minds and the Intelligence score of each. If the highest Intelligence is 26 or higher (and at least 10 points higher than your own Intelligence score), you are stunned for 1 round and the spell ends. This spell does not let you determine the location of the thinking minds if you can\'t see the creatures whose thoughts you are detecting.</p><p><i>3rd Round:</i> Surface thoughts of any mind in the area. A target\'s Will save prevents you from reading its thoughts, and you must cast <i>detect thoughts</i> again to have another chance. Creatures of animal intelligence (Int 1 or 2) have simple, instinctual thoughts that you can pick up.</p><p>Each round, you can turn to detect thoughts in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p><p><i>Arcane Focus:</i> A copper piece.</p><p/>\n</div>\n    ','SRD 3.5 SpellsD-E');
INSERT INTO spell VALUES (234,'Detect Undead','detect undead','Divination',NULL,NULL,NULL,'Cleric 1, Paladin 1, Sorcerer/Wizard 1','V, S, M/DF','1 standard action','60 ft.',NULL,'Cone-shaped emanation',NULL,'Concentration, up to 1 minute/level (D)','None','No','Reveals undead within 60 ft.',NULL,NULL,'A bit of earth from a grave.',NULL,'\n      <p>You can detect the aura that surrounds undead creatures. The amount of information revealed depends on how long you study a particular area.</p>\n      <p><i>1st Round:</i> Presence or absence of undead auras.</p>\n      <p><i>2nd Round:</i> Number of undead auras in the area and the strength of the strongest undead aura present. If you are of good alignment, and the strongest undead aura\'s strength is overwhelming (see below), and the creature has HD of at least twice your character level, you are stunned for 1 round and the spell ends.</p>\n      <p><i>3rd Round:</i> The strength and location of each undead aura. If an aura is outside your line of sight, then you discern its direction but not its exact location.</p>\n      <p><i>Aura Strength:</i> The strength of an undead aura is determined by the HD of the undead creature, as given on the following table:</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>HD</b><br/></td>\n<td><b>Strength</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1 or lower<br/></td>\n<td>Faint<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2-4<br/></td>\n<td>Moderate<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5-10<br/></td>\n<td>Strong<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>11 or higher<br/></td>\n<td>Overwhelming<br/></td>\n\n</tr>\n</table>\n      <p><i>Lingering Aura:</i> An undead aura lingers after its original source is destroyed. If <i>detect undead</i> is cast and directed at such a location, the spell indicates an aura strength of dim (even weaker than a faint aura). How long the aura lingers at this dim level depends on its original power:</p>\n      <table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Original Strength</b><br/></td> <td><b>Duration of Lingering Aura</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Faint<br/></td>\n<td>1d6 rounds<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Moderate<br/></td>\n<td>1d6 minutes<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Strong<br/></td>\n<td>1d6x10 minutes<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Overwhelming<br/></td>\n<td>1d6 days<br/></td>\n\n</tr>\n</table>\n      <p>Each round, you can turn to detect undead in a new area. The spell can penetrate barriers, but 1 foot of stone, 1 inch of common metal, a thin sheet of lead, or 3 feet of wood or dirt blocks it.</p>\n      <p/>\n    ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'\n      <div topic=\"Detect Undead\" level=\"5\"><p><h5>Detect Undead</h5></p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\"><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"/><td>Divination<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Level:</b><br/></td><td>Cleric 1, Paladin 1, Sorcerer/Wizard 1<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Components:</b><br/></td><td>V, S, M/DF<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Casting Time:</b><br/></td><td>1 standard action<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Range:</b><br/></td><td>60 ft.<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Area:</b><br/></td><td>Cone-shaped emanation<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Duration:</b><br/></td><td>Concentration, up to 1 minute/level (D)<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Saving Throw:</b><br/></td><td>None<br/></td></tr><tr maxcol=\"3\" curcol=\"3\"><td width=\"25%\"><b>Spell Resistance:</b><br/></td><td>No<br/></td></tr></table><p>You can detect the aura that surrounds undead creatures. The amount of information revealed depends on how long you study a particular area.</p><p><i>1st Round:</i> Presence or absence of undead auras.</p><p><i>2nd Round:</i> Number of undead auras in the area and the strength of the strongest undead aura present. If you are of good alignment, and the strongest undead aura\'s strength is overwhelming (see below), and the creature has HD of at least twice your character level, you are stunned for 1 round and the spell ends.</p><p><i>3rd Round:</i> The strength and location of each undead aura. If an aura is outside your line of sight, then you discern its direction but not its exact location.</p><p><i>Aura Strength:</i> The strength of an undead aura is determined by the HD of the undead creature, as given on the following table:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>HD</b><br/></td>\n<td><b>Strength</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>1 or lower<br/></td>\n<td>Faint<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>2-4<br/></td>\n<td>Moderate<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>5-10<br/></td>\n<td>Strong<br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>11 or higher<br/></td>\n<td>Overwhelming<br/></td>\n\n</tr>\n</table><p><i>Lingering Aura:</i> An undead aura lingers after its original source is destroyed. If <i>detect undead</i> is cast and directed at such a location, the spell indicates an aura strength of dim (even weaker than a faint aura). How long the aura lingers at this dim level depends on its original power:</p><table width=\"100%\" border=\"1\" cellpadding=\"2\" cellspacing=\"2\" frame=\"VOID\" rules=\"ROWS\">\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td><b>Original Strength</b><br/></td> <td><b>Duration of Lingering Aura</b><br/></td>\n\n</tr>\n\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Faint<br/></td>\n<td>1d6 rounds<br/></td>\n\n</tr>\n<tr maxcol=\"3\" curcol=\"3\">\n<td>Moderate<br/></td>\n<td>1d6 minutes<br/></td>\n\n</tr>